function reviewCheckHasContractField(check: any, field: string) {
  const camelField = camelizeSnakeField(field)
  const hasSnake = Object.prototype.hasOwnProperty.call(check || {}, field)
  const hasCamel = camelField !== field && Object.prototype.hasOwnProperty.call(check || {}, camelField)
  if (!hasSnake && !hasCamel) return false
  if (field === 'remaining_risk') return true
  return compactBriefText(check?.[field] || check?.[camelField]) !== ''
}

function structuredReviewCheckMissingRequiredFields(check: any, checkField = '') {
  if (!checkField || !check || typeof check !== 'object') return []
  if (Object.prototype.hasOwnProperty.call(check, 'delivered')) return []
  const requiredFields = STRUCTURED_REVIEW_REQUIRED_FIELDS[checkField] || []
  if (!requiredFields.length) return []
  return requiredFields.filter(field => !reviewCheckHasContractField(check, field))
}

export function hasFailingReviewChecks(review: any) {
  const directChecks = STRUCTURED_REVIEW_CHECK_FIELDS
    .flatMap(([snakeField, camelField]) => asArray(review?.[snakeField] || review?.[camelField]))
  const diagnostics = review?.deslop_gate_diagnostics || review?.deslopGateDiagnostics || {}
  const diagnosticGates = asArray(diagnostics?.gates)
  return [...directChecks, ...diagnosticGates]
    .some((check: any) => String(check?.status || '').toLowerCase() === 'fail')
}

export function hasReviewChecksNeedingRepair(review: any) {
  const directChecks = STRUCTURED_REVIEW_CHECK_FIELDS
    .flatMap(([snakeField, camelField]) => asArray(review?.[snakeField] || review?.[camelField])
      .map(check => ({ check, snakeField })))
  const diagnostics = review?.deslop_gate_diagnostics || review?.deslopGateDiagnostics || {}
  const diagnosticGates = asArray(diagnostics?.gates)
  return directChecks.some(({ check, snakeField }) => (
    platformCheckNeedsCarryOver(check)
    || structuredReviewCheckMissingRequiredFields(check, snakeField).length > 0
  )) || diagnosticGates.some(platformCheckNeedsCarryOver)
}

export type ChapterWordTarget = {
  mode: 'standard' | 'long' | 'custom'
  label: string
  target: number
  min: number
  max: number
  rangeText: string
}

function clampWordTarget(value: number) {
  if (!Number.isFinite(value) || value <= 0) return 3000
  return Math.min(12000, Math.max(1000, Math.round(value)))
}

export function resolveChapterWordTarget(project: any, chapter: any, options: any = {}): ChapterWordTarget {
  const raw = options.word_target || chapter?.raw_payload?.word_target || project?.reference_config?.chapter_word_target || {}
  const requestedMode = String(options.word_target_mode || raw.mode || raw.word_target_mode || '').toLowerCase()
  const requestedTarget = Number(options.target_word_count || raw.target || raw.target_word_count || 0)

  if (requestedMode === 'long') {
    return {
      mode: 'long',
      label: '长章',
      target: 10000,
      min: 9000,
      max: 11000,
      rangeText: '9000-11000 字',
    }
  }

  if (requestedMode === 'custom' || requestedTarget > 0) {
    const target = clampWordTarget(requestedTarget)
    const min = Math.max(800, Math.round(target * 0.9))
    const max = Math.round(target * 1.1)
    return {
      mode: 'custom',
      label: `自定义 ${target} 字`,
      target,
      min,
      max,
      rangeText: `${min}-${max} 字`,
    }
  }

  return {
    mode: 'standard',
    label: '标准章',
    target: 3000,
    min: 2800,
    max: 3500,
    rangeText: '2800-3500 字',
  }
}

export function applyChapterWordTargetToContext(contextPackage: any, target: ChapterWordTarget) {
  const chapterTarget = {
    ...((contextPackage || {}).chapterTarget || {}),
    ...((contextPackage || {}).chapter_target || {}),
    word_target: target,
  }
  return {
    ...(contextPackage || {}),
    chapter_target: chapterTarget,
    chapterTarget,
    style_lock: {
      ...((contextPackage || {}).style_lock || {}),
      chapter_word_range: target.rangeText,
    },
  }
}

export function proseMaxTokensForWordTarget(target: ChapterWordTarget | null | undefined) {
  const targetWords = Number(target?.target || 3000)
  if (targetWords >= 9000) return 18000
  if (targetWords >= 6000) return 14000
  return 8000
}

export type ProseWordTargetEvaluation = {
  actual: number
  target: number
  min: number
  max: number
  deficit: number
  too_short: boolean
  too_long: boolean
  passed: boolean
}

export function countProseChars(text: string) {
  return String(text || '').replace(/\s/g, '').length
}

const PROSE_META_TERM_PATTERN = /第[一二三四五六七八九十百千万两0-9]+章|上一章|上章|前一章|本章|这一章|前文|后文|伏笔|细纲|读者/g

function isLikelyChapterTitleLine(line: string) {
  return /^#{0,6}\s*第[一二三四五六七八九十百千万两0-9]+章(?:\s|$|[：:《「【_ -])/.test(String(line || '').trim())
}

function isLikelyInWorldChapterTextReference(line: string, term: string) {
  const evidence = String(line || '')
  const escapedTerm = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  if (/^第[一二三四五六七八九十百千万两0-9]+章$/.test(term) && new RegExp(`《[^》]{1,40}》\\s*${escapedTerm}`).test(evidence)) return true
  if (!/^(第[一二三四五六七八九十百千万两0-9]+章|这一章|本章)$/.test(term)) return false
  return /(翻到|翻开|读到|看到|查到|指着|写着|记着|目录|书页|卷宗|档案|册子|抄本|碑文|条文)/.test(evidence)
}

export function scanProseMetaLeaks(text: string) {
  const lines = String(text || '').split(/\r?\n/)
  const firstContentLine = lines.findIndex(line => String(line || '').trim())
  const hits: Array<{ key: string; label: string; term: string; line: number; status: 'warn'; evidence: string; fix: string }> = []
  lines.forEach((line, index) => {
    if (index === firstContentLine && isLikelyChapterTitleLine(line)) return
    const evidence = String(line || '').trim()
    if (!evidence) return
    PROSE_META_TERM_PATTERN.lastIndex = 0
    const terms = new Set<string>()
    let match: RegExpExecArray | null
    while ((match = PROSE_META_TERM_PATTERN.exec(evidence))) {
      terms.add(match[0])
    }
    for (const term of terms) {
      if (isLikelyInWorldChapterTextReference(evidence, term)) continue
      hits.push({
        key: `meta_${term}`,
        label: '正文元信息扫描',
        term,
        line: index + 1,
        status: 'warn',
        evidence,
        fix: `将“${term}”改成角色当下能感知的事件锚点或相对时间；只有故事世界内真实讨论文本/读者身份时才保留。`,
      })
    }
  })
  return hits
}

export function buildProseMetaSyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const missed = scanProseMetaLeaks(chapterText).map((item: any) => ({
    ...item,
    text: item.evidence,
    expected: item.fix,
    delivered: false,
    status: 'warn',
  }))
  const missedCount = missed.length
  const score = Math.max(0, Math.min(100, missedCount ? 100 - missedCount * 18 : 92))
  const status = missedCount > 0 ? 'warn' : 'ok'

  return {
    report_id: `prose-meta-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: status === 'ok' ? '正文元信息 OK' : `正文元信息缺口 ${missedCount}`,
    summary: status === 'ok'
      ? '正文标题行以外没有发现上一章、本章、伏笔、细纲、读者等作者视角元信息。'
      : `正文有 ${missedCount} 处作者视角元信息，需要改成角色当下能感知的事件锚点或相对时间。`,
    missed_count: missedCount,
    priority_repair: missedCount > 0 ? '优先修正文元信息' : '',
    planned_count: missedCount,
    delivered_count: status === 'ok' ? 1 : 0,
    planned: missed,
    delivered: status === 'ok'
      ? [{
          key: 'prose_meta_clean',
          label: '正文元信息扫描',
          text: '标题行以外无工程词/作者视角元信息',
          expected: '标题行以外无工程词/作者视角元信息',
          delivered: true,
          status: 'ok',
        }]
      : [],
    missed,
    next_actions: status === 'ok'
      ? ['保持正文元信息清洁：标题行以外不要出现上一章、本章、前文、后文、伏笔、细纲、读者等工程词。']
      : [
          '下一章必须修正文元信息：把“上一章/本章/前文/后文/伏笔/细纲/读者/第X章”等改成角色当下能感知的事件锚点或相对时间。',
          '只有角色在故事世界内真实讨论文本、章节或读者身份时才保留相关词。',
        ],
  }
}

