function compactBriefText(value: any, fallback = '') {
  return String(value || fallback || '').replace(/\s+/g, ' ').trim()
}

function buildPreviousChapterHandoff(contextPackage: any) {
  const target = contextPackage?.chapter_target || {}
  const explicitValue = target.previous_handoff
    || target.previousHandoff
    || target.chapter_handoff_contract?.previous_handoff
    || target.chapter_handoff_contract?.previousHandoff
    || target.chapterHandoffContract?.previous_handoff
    || target.chapterHandoffContract?.previousHandoff
    || contextPackage?.previous_handoff
    || contextPackage?.previousHandoff
    || contextPackage?.chapter_handoff_contract?.previous_handoff
    || contextPackage?.chapter_handoff_contract?.previousHandoff
    || contextPackage?.chapterHandoffContract?.previous_handoff
    || contextPackage?.chapterHandoffContract?.previousHandoff
    || contextPackage?.batch_preflight?.chapter_handoff_contract?.previous_handoff
    || contextPackage?.batch_preflight?.chapter_handoff_contract?.previousHandoff
    || contextPackage?.batch_preflight?.chapterHandoffContract?.previous_handoff
    || contextPackage?.batch_preflight?.chapterHandoffContract?.previousHandoff
    || contextPackage?.pre_draft_brief?.chapter_handoff_contract?.previous_handoff
    || contextPackage?.pre_draft_brief?.chapter_handoff_contract?.previousHandoff
    || contextPackage?.pre_draft_brief?.chapterHandoffContract?.previous_handoff
    || contextPackage?.pre_draft_brief?.chapterHandoffContract?.previousHandoff
    || contextPackage?.preDraftBrief?.chapter_handoff_contract?.previous_handoff
    || contextPackage?.preDraftBrief?.chapter_handoff_contract?.previousHandoff
    || contextPackage?.preDraftBrief?.chapterHandoffContract?.previous_handoff
    || contextPackage?.preDraftBrief?.chapterHandoffContract?.previousHandoff
    || contextPackage?.pre_draft_brief?.previous_handoff
    || contextPackage?.pre_draft_brief?.previousHandoff
    || contextPackage?.preDraftBrief?.previous_handoff
    || contextPackage?.preDraftBrief?.previousHandoff
  const explicit = Array.isArray(explicitValue) || (explicitValue && typeof explicitValue === 'object')
    ? handoffContractTextItems([
        explicitValue,
        explicitValue?.immediate_carry,
        explicitValue?.immediateCarry,
        explicitValue?.must_carry,
        explicitValue?.mustCarry,
        explicitValue?.opening_obligation,
        explicitValue?.openingObligation,
        explicitValue?.required_actions,
        explicitValue?.requiredActions,
      ].flat(), 10).join('；')
    : compactBriefText(explicitValue)
  if (explicit) return explicit

  const previous = contextPackage?.continuity?.previous_chapter || null
  if (!previous) return ''
  const label = previous.chapter_no
    ? `第${previous.chapter_no}章${previous.title ? `《${previous.title}》` : ''}`
    : '上一章'
  const endingHook = compactBriefText(previous.ending_hook)
  const endingExcerpt = compactBriefText(previous.ending_excerpt)
  const parts = [
    endingHook ? `章末钩子：${endingHook}` : '',
    endingExcerpt ? `最后一幕：${compactText(endingExcerpt, 180)}` : '',
  ].filter(Boolean)
  return parts.length ? `${label} ${parts.join('；')}` : ''
}

function handoffContractItemText(item: any) {
  if (typeof item === 'string') return compactBriefText(item)
  return compactBriefText(item?.text || item?.label || item?.name || item?.summary || item?.detail || item?.title || item?.issue)
}

function handoffContractTextItems(value: any, limit = 12) {
  const seen = new Set<string>()
  const result: string[] = []
  for (const item of asArray(value)) {
    const normalized = handoffContractItemText(item)
    if (!normalized || seen.has(normalized)) continue
    seen.add(normalized)
    result.push(normalized)
    if (result.length >= limit) break
  }
  return result
}

function normalizeGovernanceRecheckMemoryContext(value: any) {
  const raw = value?.governance_recheck_memory || value?.governanceRecheckMemory || value || null
  if (!raw || typeof raw !== 'object') return null
  const evidence = handoffContractTextItems([
    ...asArray(raw.evidence),
    ...asArray(raw.repaired_evidence),
    ...asArray(raw.repairedEvidence),
  ], 8)
  const failedEvidence = handoffContractTextItems([
    ...asArray(raw.failed_evidence),
    ...asArray(raw.failedEvidence),
  ], 8)
  const watchItems = handoffContractTextItems([
    ...asArray(raw.watch_items),
    ...asArray(raw.watchItems),
  ], 8)
  const rawStatus = compactBriefText(raw.status)
  const summary = compactBriefText(raw.summary)
  const sourceRunId = raw.source_run_id ?? raw.sourceRunId ?? null
  const storylineDecisionTaskCount = Math.max(0, Number(raw.storyline_decision_task_count ?? raw.storylineDecisionTaskCount ?? 0) || 0)
  const hasMemory = Boolean(
    rawStatus
      || compactBriefText(raw.label)
      || summary
      || sourceRunId
      || evidence.length
      || failedEvidence.length
      || watchItems.length
      || storylineDecisionTaskCount,
  )
  if (!hasMemory) return null

  const status = rawStatus === 'closed' && failedEvidence.length === 0 && storylineDecisionTaskCount === 0
    ? 'closed'
    : rawStatus === 'closed'
      ? 'needs_followup'
      : rawStatus === 'needs_followup'
        ? 'needs_followup'
        : failedEvidence.length > 0 || storylineDecisionTaskCount > 0
          ? 'needs_followup'
          : 'closed'

  return {
    source_run_id: sourceRunId,
    status,
    label: compactBriefText(raw.label, status === 'closed' ? '治理复查已记录' : '治理复查待处理'),
    summary: summary || (status === 'closed'
      ? '上一轮治理复查已闭环，本章继续继承修后证据和观察项。'
      : '上一轮治理复查仍有待处理项，本章必须先承接失效依据和观察项。'),
    evidence,
    failed_evidence: failedEvidence,
    watch_items: watchItems,
    storyline_decision_task_count: storylineDecisionTaskCount,
  }
}

function normalizeBatchChapterHandoffContract(value: any) {
  const raw = value?.chapter_handoff_contract || value?.chapterHandoffContract || value || {}
  const previousHandoff = compactBriefText(raw.previous_handoff || raw.previousHandoff)
  const openingObligations = handoffContractTextItems(raw.opening_obligations || raw.openingObligations)
  const expectationCarryOver = handoffContractTextItems(raw.expectation_carry_over || raw.expectationCarryOver)
  const mustDeliver = handoffContractTextItems(raw.must_deliver || raw.mustDeliver)
  const keepAlive = handoffContractTextItems(raw.keep_alive || raw.keepAlive)
  const overdue = handoffContractTextItems(raw.overdue || raw.overdue_items || raw.overdueItems)
  const hasContract = previousHandoff
    || openingObligations.length
    || expectationCarryOver.length
    || mustDeliver.length
    || keepAlive.length
    || overdue.length
  if (!hasContract) return null
  return {
    source: compactBriefText(raw.source, 'safe_batch_chapter_handoff_contract'),
    from_chapter_no: Number(raw.from_chapter_no || raw.fromChapterNo || 0) || null,
    apply_to_chapter_no: Number(raw.apply_to_chapter_no || raw.applyToChapterNo || 0) || null,
    previous_handoff: previousHandoff,
    opening_obligations: openingObligations,
    expectation_carry_over: expectationCarryOver,
    must_deliver: mustDeliver,
    keep_alive: keepAlive,
    overdue,
    policy: compactBriefText(raw.policy, '安全连写第一章必须先接住上一章最后一幕和读者期待债务。'),
  }
}

function sceneBriefFromCard(card: any, index: number) {
  return {
    scene_no: Number(card?.scene_no || index + 1),
    title: compactBriefText(card?.title, `场景${index + 1}`),
    purpose: compactBriefText(card?.purpose || card?.beat),
    conflict: compactBriefText(card?.conflict),
    opening_hook: compactBriefText(card?.opening_hook || card?.hook_opening),
    reader_payoff: compactBriefText(card?.reader_payoff || card?.payoff),
    fear_point: compactBriefText(card?.fear_point || card?.terror_point),
    rule_pressure: compactBriefText(card?.rule_pressure || card?.rule_trigger),
    information_gap: compactBriefText(card?.information_gap),
    reversal: compactBriefText(card?.reversal || card?.turning_point),
    ending_hook_seed: compactBriefText(card?.ending_hook_seed || card?.ending_hook || card?.exit_state),
    word_budget: compactBriefText(card?.word_budget || card?.description_budget),
    serial_risk_repairs: asArray(card?.serial_risk_repairs || card?.serialRiskRepairs || card?.risk_repairs || card?.riskRepairs).map((item: any) => compactBriefText(typeof item === 'string' ? item : JSON.stringify(item))).filter(Boolean),
    recent_fatigue_action: compactBriefText(card?.recent_fatigue_action || card?.recentFatigueAction || card?.fatigue_repair_action || card?.fatigueRepairAction),
    character_voice: compactBriefText(card?.character_voice || card?.characterVoice || card?.voice_focus || card?.voiceFocus),
    dialogue_goals: asArray(card?.dialogue_goals || card?.dialogueGoals || card?.dialogue_contract_goals || card?.dialogueContractGoals).map((item: any) => compactBriefText(item)).filter(Boolean),
    style_directives: asArray(card?.style_directives || card?.styleDirectives || card?.style_boundary_directives || card?.styleBoundaryDirectives).map((item: any) => compactBriefText(item)).filter(Boolean),
    benchmark_recall_directives: asArray(card?.benchmark_recall_directives || card?.benchmarkRecallDirectives || card?.benchmark_directives || card?.benchmarkDirectives).map((item: any) => compactBriefText(item)).filter(Boolean),
    concept_anchor_rules: asArray(card?.concept_anchor_rules || card?.conceptAnchorRules || card?.new_concept_anchor_rules || card?.newConceptAnchorRules).map((item: any) => compactBriefText(item)).filter(Boolean),
    prose_craft_directives: asArray(card?.prose_craft_directives || card?.proseCraftDirectives || card?.prose_craft_rules || card?.proseCraftRules).map((item: any) => compactBriefText(item)).filter(Boolean),
    emotional_tone: compactBriefText(card?.emotional_tone || card?.emotionalTone || card?.tone),
    key_dialogue: compactBriefText(card?.key_dialogue || card?.keyDialogue || card?.dialogue_focus || card?.dialogueFocus),
    dialogue_goal: compactBriefText(card?.dialogue_goal || card?.dialogueGoal),
  }
}

function buildReaderRetentionBrief(project: any, contextPackage: any, sceneBriefs: any[]) {
  const chapterTarget = contextPackage?.chapter_target || {}
  const writingBible = contextPackage?.writing_bible || project?.reference_config?.writing_bible || {}
  const retentionContract = writingBible?.reader_retention_contract
    || writingBible?.readerRetentionContract
    || project?.reference_config?.writing_bible?.reader_retention_contract
    || project?.reference_config?.writing_bible?.readerRetentionContract
    || {}
  const firstScene = sceneBriefs[0] || {}
  const lastScene = sceneBriefs[sceneBriefs.length - 1] || {}
  const readerPayoffs = sceneBriefs.map((item: any) => item.reader_payoff).filter(Boolean)
  const informationGaps = sceneBriefs.map((item: any) => item.information_gap).filter(Boolean)
  const reversals = sceneBriefs.map((item: any) => item.reversal).filter(Boolean)
  const retentionPillars = {
    upgrade: compactBriefText(firstDefined(
      readerPayoffs.join('；'),
      chapterTarget.upgrade_payoff,
      chapterTarget.upgradePayoff,
      chapterTarget.reader_payoff,
      chapterTarget.payoff,
      writingBible?.style_lock?.payoff_density,
      retentionContract.upgrade,
      retentionContract.retention_pillars?.upgrade,
      retentionContract.retentionPillars?.upgrade,
    )),
    resource_pressure: compactBriefText(firstDefined(
      chapterTarget.resource_pressure,
      chapterTarget.resourcePressure,
      firstScene.conflict,
      chapterTarget.conflict,
      informationGaps.join('；'),
      retentionContract.resource_pressure,
      retentionContract.resourcePressure,
      retentionContract.retention_pillars?.resource_pressure,
      retentionContract.retentionPillars?.resourcePressure,
    )),
    goal_stack: compactBriefText([
      '大目标 + 小目标 + 假目标',
      firstDefined(chapterTarget.summary, project?.synopsis),
      firstDefined(chapterTarget.conflict, firstScene.purpose),
      firstDefined(chapterTarget.ending_hook, lastScene.ending_hook_seed),
    ].filter(Boolean).join('：')),
    mystery_unlock: compactBriefText(firstDefined(
      informationGaps.join('；'),
      chapterTarget.information_gap,
      chapterTarget.ending_hook,
      lastScene.ending_hook_seed,
      retentionContract.mystery_unlock,
      retentionContract.mysteryUnlock,
      retentionContract.retention_pillars?.mystery_unlock,
      retentionContract.retentionPillars?.mysteryUnlock,
    )),
  }
  const retentionStrategy = firstDefined(
    writingBible?.commercial_positioning?.retention_strategy,
    writingBible?.retention_strategy,
    project?.reference_config?.writing_bible?.commercial_positioning?.retention_strategy,
  )
  return {
    opening_hook: compactBriefText(firstDefined(
      chapterTarget.opening_hook,
      firstScene.opening_hook,
      retentionContract.opening_hook_rule,
      retentionContract.openingHookRule,
      firstScene.purpose,
      chapterTarget.summary,
    )),
    payoff_promise: compactBriefText(firstDefined(
      readerPayoffs.join('；'),
      chapterTarget.reader_payoff,
      chapterTarget.payoff,
      writingBible?.style_lock?.payoff_density,
      retentionStrategy,
    )),
    information_gap: compactBriefText(firstDefined(
      informationGaps.join('；'),
      chapterTarget.information_gap,
      chapterTarget.conflict,
    )),
    emotional_reward: compactBriefText(firstDefined(
      writingBible?.promise,
      writingBible?.reader_promise,
      project?.reference_config?.writing_bible?.promise,
      project?.synopsis,
      readerPayoffs.join('；'),
    )),
    short_drama_scene: compactBriefText([
      firstScene.title,
      firstDefined(firstScene.conflict, firstScene.reversal, firstScene.reader_payoff, reversals[0], chapterTarget.conflict),
    ].filter(Boolean).join('：')),
    ending_question: compactBriefText(firstDefined(
      chapterTarget.ending_hook,
      retentionContract.ending_hook_rule,
      retentionContract.endingHookRule,
      lastScene.ending_hook_seed,
      lastScene.reversal,
    )),
    retention_double_engine: {
      emotion_engine: compactBriefText(firstDefined(
        chapterTarget.reader_emotion_engine,
        writingBible?.promise,
        writingBible?.reader_promise,
        project?.reference_config?.writing_bible?.promise,
        project?.synopsis,
        readerPayoffs.join('；'),
      )),
      hunger_engine: compactBriefText(firstDefined(
        chapterTarget.reader_hunger_engine,
        informationGaps.join('；'),
        chapterTarget.information_gap,
        chapterTarget.ending_hook,
        lastScene.ending_hook_seed,
      )),
      onion_layers: compactBriefText([
        '简介植入核心悬念',
        '章节开头植入小问号',
        firstDefined(chapterTarget.ending_hook, lastScene.ending_hook_seed, '章节末尾卡住关键信息'),
      ].filter(Boolean).join('；')),
      policy: '留存=情绪+饥饿：情绪负责快速代入和共鸣，饥饿负责用信息差植入问号。',
    },
    retention_pillars: retentionPillars,
    hook_addiction_model: {
      trigger: compactBriefText(firstDefined(
        chapterTarget.hook_trigger,
        chapterTarget.protagonist_goal,
        firstScene.opening_hook,
        chapterTarget.summary,
      )),
      action: compactBriefText(firstDefined(
        chapterTarget.simple_action,
        firstScene.purpose,
        firstScene.conflict,
        chapterTarget.conflict,
      )),
      reward: compactBriefText(firstDefined(
        chapterTarget.surprising_reward,
        readerPayoffs.join('；'),
        chapterTarget.reader_payoff,
        chapterTarget.payoff,
      )),
      investment: compactBriefText(firstDefined(
        chapterTarget.reader_investment,
        lastScene.ending_hook_seed,
        chapterTarget.ending_hook,
        reversals.join('；'),
      )),
      reward_randomness: '奖励不能只兑现预期，至少给一次出乎意料的额外收获、身份线索、资源、关系或地位变化。',
    },
    forbidden_cliches: Array.from(new Set([
      '只写环境氛围不推进目标',
      '用长篇背景解释替代现场危机',
      '章末用模板总结代替追读问题',
      '爽点只停留在旁白承诺不落成动作',
      ...asArray(chapterTarget.forbidden_cliches),
    ].map((item: any) => String(item || '').trim()).filter(Boolean))).slice(0, 8),
  }
}

function normalizeReaderRetentionBrief(value: any) {
  const raw = value?.reader_retention_brief || value?.readerRetentionBrief || value || {}
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null
  const retentionDoubleEngine = raw.retention_double_engine || raw.retentionDoubleEngine || {}
  const hookAddictionModel = raw.hook_addiction_model || raw.hookAddictionModel || {}
  const retentionPillars = raw.retention_pillars || raw.retentionPillars || {}
  const normalized = {
    opening_hook: compactBriefText(raw.opening_hook || raw.openingHook),
    payoff_promise: compactBriefText(raw.payoff_promise || raw.payoffPromise),
    information_gap: compactBriefText(raw.information_gap || raw.informationGap),
    emotional_reward: compactBriefText(raw.emotional_reward || raw.emotionalReward),
    short_drama_scene: compactBriefText(raw.short_drama_scene || raw.shortDramaScene),
    ending_question: compactBriefText(raw.ending_question || raw.endingQuestion),
    retention_double_engine: {
      emotion_engine: compactBriefText(retentionDoubleEngine.emotion_engine || retentionDoubleEngine.emotionEngine),
      hunger_engine: compactBriefText(retentionDoubleEngine.hunger_engine || retentionDoubleEngine.hungerEngine),
      onion_layers: compactBriefText(retentionDoubleEngine.onion_layers || retentionDoubleEngine.onionLayers),
      policy: compactBriefText(retentionDoubleEngine.policy),
    },
    retention_pillars: {
      upgrade: compactBriefText(retentionPillars.upgrade || retentionPillars.growth || retentionPillars.level_up || retentionPillars.levelUp),
      resource_pressure: compactBriefText(retentionPillars.resource_pressure || retentionPillars.resourcePressure || retentionPillars.resource_dilemma || retentionPillars.resourceDilemma),
      goal_stack: compactBriefText(retentionPillars.goal_stack || retentionPillars.goalStack || retentionPillars.goals),
      mystery_unlock: compactBriefText(retentionPillars.mystery_unlock || retentionPillars.mysteryUnlock || retentionPillars.decryption),
    },
    hook_addiction_model: {
      trigger: compactBriefText(hookAddictionModel.trigger),
      action: compactBriefText(hookAddictionModel.action),
      reward: compactBriefText(hookAddictionModel.reward),
      investment: compactBriefText(hookAddictionModel.investment),
      reward_randomness: compactBriefText(hookAddictionModel.reward_randomness || hookAddictionModel.rewardRandomness),
    },
    forbidden_cliches: uniqueBriefStrings(raw.forbidden_cliches || raw.forbiddenCliches || [], 8),
  }
  const hasNestedContent = Object.values(normalized.retention_double_engine).some(Boolean)
    || Object.values(normalized.hook_addiction_model).some(Boolean)
    || Object.values(normalized.retention_pillars).some(Boolean)
  const hasContent = Object.entries(normalized)
    .filter(([key]) => key !== 'retention_double_engine' && key !== 'hook_addiction_model' && key !== 'retention_pillars')
    .some(([, item]) => Array.isArray(item) ? item.length > 0 : Boolean(item))
  return hasContent || hasNestedContent ? normalized : null
}

function firstMatchingBrief(items: any[], pattern: RegExp) {
  return uniqueBriefStrings(items, 20).find(item => pattern.test(item)) || ''
}

function normalizeFirst30RetentionBrief(value: any) {
  const raw = value?.first30_retention_brief || value?.first30RetentionBrief || value || {}
  if (!raw || typeof raw !== 'object') return raw || null
  const flags = uniqueBriefStrings(raw.flags || raw.risk_flags || raw.riskFlags || [], 10)
  const risks = asArray(raw.risks || raw.segment_risks || raw.segmentRisks)
  const requiredActions = uniqueBriefStrings(raw.required_actions || raw.requiredActions || raw.next_actions || raw.nextActions || [], 10)
  const normalized = {
    report_score: Number(raw.report_score ?? raw.reportScore ?? 0) || null,
    report_status: compactBriefText(raw.report_status || raw.reportStatus || raw.status),
    report_summary: compactBriefText(raw.report_summary || raw.reportSummary || raw.summary),
    report_created_at: compactBriefText(raw.report_created_at || raw.reportCreatedAt || raw.created_at || raw.createdAt),
    promise_ready: Boolean(raw.promise_ready ?? raw.promiseReady ?? false),
    reader_promise: compactBriefText(raw.reader_promise || raw.readerPromise),
    chapter_no: Number(raw.chapter_no ?? raw.chapterNo ?? 0) || null,
    chapter_score: Number(raw.chapter_score ?? raw.chapterScore ?? 0) || null,
    chapter_title: compactBriefText(raw.chapter_title || raw.chapterTitle || raw.title),
    segment_key: compactBriefText(raw.segment_key || raw.segmentKey),
    segment_label: compactBriefText(raw.segment_label || raw.segmentLabel),
    segment_score: Number(raw.segment_score ?? raw.segmentScore ?? 0) || null,
    flags,
    risks,
    risk_level: compactBriefText(raw.risk_level || raw.riskLevel),
    repair_focus: compactBriefText(raw.repair_focus || raw.repairFocus),
    required_actions: requiredActions,
  }
  const hasContent = Object.values(normalized).some(item => Array.isArray(item) ? item.length > 0 : Boolean(item))
  return hasContent ? normalized : null
}

function first30RetentionBriefFromContext(contextPackage: any = {}, preDraftBrief: any = null) {
  const chapterTarget = contextPackage?.chapter_target || {}
  const brief = preDraftBrief || contextPackage?.pre_draft_brief || contextPackage?.preDraftBrief || {}
  return normalizeFirst30RetentionBrief(chapterTarget.first30_retention_brief
    || chapterTarget.first30RetentionBrief
    || brief.first30_retention_brief
    || brief.first30RetentionBrief
    || contextPackage?.first30_retention_context
    || contextPackage?.first30RetentionContext
    || contextPackage?.first30_retention_brief
    || contextPackage?.first30RetentionBrief
    || null)
}

function normalizeReaderDropRiskBrief(value: any, readerRetentionBrief: any = null, first30RetentionBrief: any = null) {
  const raw = value?.reader_drop_risk_brief || value?.readerDropRiskBrief || value || {}
  const dropPoints = uniqueBriefStrings(raw.drop_points || raw.dropPoints || raw.risks || [], 10)
  const pullPoints = uniqueBriefStrings(raw.pull_points || raw.pullPoints || raw.reader_pull || raw.readerPull || [], 8)
  const repairActions = uniqueBriefStrings(raw.repair_actions || raw.repairActions || raw.required_actions || raw.requiredActions || [], 10)
  const first30Flags = uniqueBriefStrings(first30RetentionBrief?.flags || [], 6)
  const first30Actions = uniqueBriefStrings(first30RetentionBrief?.required_actions || first30RetentionBrief?.requiredActions || [], 6)
  const openingGuardrail = compactBriefText(
    raw.opening_guardrail
    || raw.openingGuardrail
    || firstMatchingBrief([...repairActions, ...dropPoints, ...first30Actions, ...first30Flags], /开篇|开场|前\s*300|前三章|第1章|第一章|起手/)
    || (readerRetentionBrief?.opening_hook ? `开篇 300 字必须落地：${readerRetentionBrief.opening_hook}` : ''),
  )
  const middleGuardrail = compactBriefText(
    raw.middle_guardrail
    || raw.middleGuardrail
    || firstMatchingBrief([...repairActions, ...dropPoints, ...first30Actions, ...first30Flags], /中段|解释|设定|节奏|场景|试读十章|第4-10|掉速|水/)
    || repairActions.find((item: string) => item !== openingGuardrail && !/章末|钩子|结尾|翻页/.test(item))
    || '',
  )
  const endingGuardrail = compactBriefText(
    raw.ending_guardrail
    || raw.endingGuardrail
    || firstMatchingBrief([...repairActions, ...dropPoints, ...first30Actions, ...first30Flags], /章末|钩子|结尾|翻页|未解|下一章|最后/)
    || (readerRetentionBrief?.ending_question ? `章末必须压出追读问题：${readerRetentionBrief.ending_question}` : ''),
  )
  const status = compactBriefText(raw.status, dropPoints.length || repairActions.length || first30Flags.length ? 'needs_repair' : 'ready')
  const qualityBar = compactBriefText(raw.quality_bar || raw.qualityBar || raw.quality_bar_label || raw.qualityBarLabel, '起点1万均订试读基准')
  const score = Number.isFinite(Number(raw.score)) ? Number(raw.score) : null
  if (!dropPoints.length && !pullPoints.length && !repairActions.length && !openingGuardrail && !middleGuardrail && !endingGuardrail) return null
  return {
    status,
    score,
    quality_bar: qualityBar,
    drop_points: dropPoints,
    pull_points: pullPoints,
    repair_actions: repairActions,
    opening_guardrail: openingGuardrail,
    middle_guardrail: middleGuardrail,
    ending_guardrail: endingGuardrail,
  }
}

function goldenThreePhaseLabel(chapterNo: number) {
  if (chapterNo === 1) return '第一章启动'
  if (chapterNo === 2) return '第二章升级'
  return '第三章追读'
}

function normalizeGoldenThreeBrief(value: any, chapterNo = 0) {
  const raw = value?.golden_three_brief || value?.goldenThreeBrief || value || null
  if (!raw || typeof raw !== 'object') return null
  const targetChapterNo = Number(raw.chapter_no || raw.chapterNo || chapterNo || 0)
  if (targetChapterNo < 1 || targetChapterNo > 3) return null
  return {
    version: compactBriefText(raw.version, 'oh_story_golden_three_v1'),
    source: compactBriefText(raw.source, 'oh_story_quality_checklist'),
    chapter_no: targetChapterNo,
    phase_label: compactBriefText(raw.phase_label || raw.phaseLabel, goldenThreePhaseLabel(targetChapterNo)),
    hard_requirements: uniqueBriefStrings(raw.hard_requirements || raw.hardRequirements || [], 12),
    opening_requirements: uniqueBriefStrings(raw.opening_requirements || raw.openingRequirements || [], 8),
    middle_requirements: uniqueBriefStrings(raw.middle_requirements || raw.middleRequirements || [], 8),
    ending_requirements: uniqueBriefStrings(raw.ending_requirements || raw.endingRequirements || [], 8),
    payoff_target_count: Math.max(2, Number(raw.payoff_target_count || raw.payoffTargetCount || 2) || 2),
    current_chapter_payoffs: uniqueBriefStrings(raw.current_chapter_payoffs || raw.currentChapterPayoffs || [], 8),
    forbidden_patterns: uniqueBriefStrings(raw.forbidden_patterns || raw.forbiddenPatterns || [], 8),
    quality_checks: uniqueBriefStrings(raw.quality_checks || raw.qualityChecks || [], 12),
  }
}

function buildGoldenThreeBrief(project: any, contextPackage: any, sceneBriefs: any[] = []) {
  const chapterTarget = contextPackage?.chapter_target || {}
  const chapterNo = Number(chapterTarget.chapter_no || contextPackage?.chapter_no || 0)
  const explicit = normalizeGoldenThreeBrief(
    chapterTarget.golden_three_brief
    || chapterTarget.goldenThreeBrief
    || contextPackage?.golden_three_brief
    || contextPackage?.goldenThreeBrief
    || contextPackage?.pre_draft_brief?.golden_three_brief
    || contextPackage?.preDraftBrief?.goldenThreeBrief,
    chapterNo,
  )
  if (explicit) return explicit
  if (chapterNo < 1 || chapterNo > 3) return null

  const sceneCards = asArray(chapterTarget.scene_cards)
  const scenes = sceneBriefs.length ? sceneBriefs : sceneCards.map(sceneBriefFromCard)
  const firstScene = scenes[0] || sceneCards[0] || {}
  const lastScene = scenes[scenes.length - 1] || sceneCards[sceneCards.length - 1] || firstScene
  const currentChapterPayoffs = uniqueBriefStrings([
    ...scenes.map((scene: any) => scene.reader_payoff || scene.payoff),
    ...scenes.map((scene: any) => scene.reversal || scene.turning_point),
    chapterTarget.reader_payoff,
    chapterTarget.payoff,
    contextPackage?.writing_bible?.promise,
    project?.synopsis,
  ], 8)
  const openingHook = compactBriefText(chapterTarget.opening_hook || firstScene.opening_hook || firstScene.purpose || chapterTarget.summary)
  const endingHook = compactBriefText(chapterTarget.ending_hook || lastScene.ending_hook_seed || lastScene.reversal)

  const chapterSpecific = chapterNo === 1
    ? ['主角第一章就出场', '第一章有事件，不得纯铺垫', '第一章前 500 字有钩子']
    : chapterNo === 2
      ? ['第二章有升级（矛盾加深）', '第二章必须把第一章危机推高或改变局势']
      : ['第三章有追读理由', '第三章必须给读者继续追下去的新问题、新回报或新代价']

  return {
    version: 'oh_story_golden_three_v1',
    source: 'oh_story_quality_checklist',
    chapter_no: chapterNo,
    phase_label: goldenThreePhaseLabel(chapterNo),
    hard_requirements: uniqueBriefStrings([
      ...chapterSpecific,
      '前三章至少两个爽点',
      '世界观没有大段说明文',
      '每章结尾有悬念',
    ], 12),
    opening_requirements: uniqueBriefStrings([
      chapterNo === 1 ? '前 500 字有钩子：事故、异常、危险、欲望或反常信息必须可见' : '开篇 300 字承接上一章钩子并升级压力',
      openingHook ? `本章开篇钩子候选：${openingHook}` : '',
      '不得从天气、风景、设定百科或日常闲聊慢热开局',
    ], 8),
    middle_requirements: uniqueBriefStrings([
      chapterNo === 2 ? '中段必须出现矛盾升级或新阻碍' : '中段必须有真实事件推进，不得只解释世界观',
      '至少一次把读者回报写成可见行动、反转、打脸、发现或关系变化',
      currentChapterPayoffs.length ? `本章可用爽点：${currentChapterPayoffs.join('；')}` : '',
    ], 8),
    ending_requirements: uniqueBriefStrings([
      '章末必须留下悬念、危机、发现、决定或反转之一',
      endingHook ? `本章章末钩子候选：${endingHook}` : '',
      '结尾不得用“这只是开始”“拉开序幕”等总结句替代现场问题',
    ], 8),
    payoff_target_count: 2,
    current_chapter_payoffs: currentChapterPayoffs,
    forbidden_patterns: [
      '纯背景铺垫',
      '大段世界观说明',
      '无事件开篇',
      '总结式结尾',
    ],
    quality_checks: [
      '第一章前 500 字是否有钩子',
      '主角是否第一章就出场',
      '第一章是否有事件而不是纯铺垫',
      '第二章是否矛盾加深',
      '第三章是否有追读理由',
      '前三章是否至少 2 个爽点',
      '世界观是否避免大段说明文',
      '每章结尾是否有悬念',
    ],
  }
}

function normalizeStoryPressureSignal(value: any) {
  const key = compactBriefText(value?.key || value?.field || value?.type)
  const label = compactBriefText(value?.label || value?.title || key)
  const status = compactBriefText(value?.status || value?.state, 'ok').toLowerCase()
  const detail = compactBriefText(value?.detail || value?.reason || value?.summary || value?.text)
  if (!key && !label && !detail) return null
  return {
    key: key || label,
    label: label || key || '故事压力',
    status,
    detail,
  }
}

function normalizeStoryPressureBrief(value: any) {
  const raw = value?.story_pressure_brief
    || value?.storyPressureBrief
    || value?.story_pressure_ladder
    || value?.storyPressureLadder
    || value
    || {}
  const signals = asArray(raw.signals || raw.pressure_signals || raw.pressureSignals)
    .map((item: any) => normalizeStoryPressureSignal(item))
    .filter(Boolean)
    .slice(0, 8)
  const weakSignals = signals
    .filter((signal: any) => !['ok', 'ready', 'pass', 'passed'].includes(String(signal.status || '').toLowerCase()))
    .slice(0, 6)
  const pressureSourceRows = asArray(raw.pressure_sources || raw.pressureSources || raw.sources)
  const pressureSources = uniqueBriefStrings(
    pressureSourceRows.map((item: any) => typeof item === 'string' ? item : item?.label || item?.name || item?.summary || item?.detail),
    8,
  )
  const requiredActions = uniqueBriefStrings(raw.required_actions || raw.requiredActions || raw.next_actions || raw.nextActions || [], 8)
  const signalDetail = (key: string) => compactBriefText(signals.find((signal: any) => signal.key === key)?.detail)
  const conflictEscalationGuardrail = compactBriefText(
    raw.conflict_escalation_guardrail
    || raw.conflictEscalationGuardrail
    || signalDetail('conflict_escalation'),
  )
  const stakesGrowthGuardrail = compactBriefText(
    raw.stakes_growth_guardrail
    || raw.stakesGrowthGuardrail
    || signalDetail('stakes_growth'),
  )
  const reversalPressureGuardrail = compactBriefText(
    raw.reversal_pressure_guardrail
    || raw.reversalPressureGuardrail
    || signalDetail('reversal_pressure'),
  )
  const pressureSourceGuardrail = compactBriefText(
    raw.pressure_source_guardrail
    || raw.pressureSourceGuardrail
    || signalDetail('pressure_source'),
  )
  const status = compactBriefText(raw.status, weakSignals.length ? 'needs_attention' : (signals.length || pressureSources.length ? 'ready' : ''))
  const score = Number.isFinite(Number(raw.score)) ? Number(raw.score) : null
  const rangeLabel = compactBriefText(raw.chapter_range_label || raw.chapterRangeLabel || raw.range_label || raw.rangeLabel)
  if (!status && !pressureSources.length && !signals.length && !requiredActions.length && !conflictEscalationGuardrail && !stakesGrowthGuardrail && !reversalPressureGuardrail && !pressureSourceGuardrail) return null
  return {
    status,
    score,
    range_label: rangeLabel,
    pressure_sources: pressureSources,
    weak_signals: weakSignals,
    required_actions: requiredActions,
    pressure_source_guardrail: pressureSourceGuardrail,
    conflict_escalation_guardrail: conflictEscalationGuardrail,
    stakes_growth_guardrail: stakesGrowthGuardrail,
    reversal_pressure_guardrail: reversalPressureGuardrail,
  }
}

function normalizeStoryDriveBrief(value: any, sceneCards: any[] = []) {
  const raw = value?.story_drive_brief || value?.storyDriveBrief || value || {}
  const target = value?.chapter_target || value?.chapterTarget || value || {}
  const protagonistChoice = firstCompactText(
    raw.protagonist_choice,
    raw.protagonistChoice,
    raw.active_choice,
    raw.activeChoice,
    target.protagonist_choice,
    target.protagonistChoice,
    target.active_choice,
    target.activeChoice,
    target.main_character_choice,
    firstSceneCardText(sceneCards, ['protagonist_choice', 'active_choice', 'turning_point', 'turn', 'reversal']),
  )
  const choiceCost = firstCompactText(
    raw.choice_cost,
    raw.choiceCost,
    raw.cost,
    raw.consequence,
    raw.stakes,
    target.choice_cost,
    target.choiceCost,
    target.cost,
    target.consequence,
    target.stakes,
    firstSceneCardText(sceneCards, ['choice_cost', 'cost', 'consequence', 'stakes', 'risk']),
  )
  const stateChange = firstCompactText(
    raw.state_change,
    raw.stateChange,
    raw.exit_state,
    raw.exitState,
    target.state_change,
    target.stateChange,
    target.exit_state,
    target.exitState,
    target.chapter_state_change,
    firstSceneCardText(sceneCards, ['exit_state', 'state_change', 'result', 'scene_result']),
  )
  const obstacle = firstCompactText(
    raw.obstacle,
    raw.conflict,
    raw.core_conflict,
    raw.coreConflict,
    target.core_conflict,
    target.coreConflict,
    target.conflict,
    firstSceneCardText(sceneCards, ['conflict', 'obstacle', 'pressure']),
  )
  const causalNextStep = firstCompactText(
    raw.causal_next_step,
    raw.causalNextStep,
    raw.next_step,
    raw.nextStep,
    raw.ending_hook,
    raw.endingHook,
    target.causal_next_step,
    target.causalNextStep,
    target.next_step,
    target.nextStep,
    target.ending_hook,
    target.endingHook,
    firstSceneCardText(sceneCards, ['causal_next_step', 'next_step', 'ending_hook', 'exit_hook']),
  )
  const requiredActions = uniqueBriefStrings(
    raw.required_actions
    || raw.requiredActions
    || [
      '把主角主动选择、明确阻碍、选择代价、状态变化和下一步因果写成可见事件。',
    ],
    6,
  )
  if (!protagonistChoice && !choiceCost && !stateChange && !obstacle && !causalNextStep) return null
  return {
    protagonist_choice: protagonistChoice,
    choice_cost: choiceCost,
    state_change: stateChange,
    obstacle,
    causal_next_step: causalNextStep,
    required_actions: requiredActions,
  }
}

