function proseQualityFiveDimensionRisks(payload: any) {
  const selfCheck = payload?.self_check || payload?.selfCheck || payload || {}
  const review = selfCheck?.review || selfCheck?.initial_review || payload?.review || payload || {}
  const scores = normalizeFiveDimensionQualityScores(
    review?.five_dimension_scores
    || review?.fiveDimensionScores
    || review?.five_dimensions
    || review?.fiveDimensions
    || review?.quality_audit_scores
    || review?.qualityAuditScores
    || selfCheck?.five_dimension_scores
    || selfCheck?.fiveDimensionScores
    || payload?.five_dimension_scores
    || payload?.fiveDimensionScores,
  )
  return asArray(scores?.below_threshold)
    .map((dimension: any) => {
      const label = compactBriefText(dimension?.label || dimension?.key, '五维评分')
      const evidence = compactBriefText(dimension?.evidence || `${label} ${dimension?.score} 分，低于 ${scores.threshold}。`)
      const fix = compactBriefText(dimension?.fix || (
        dimension?.strategy === 'de_ai'
          ? `下一章必须修复 ${label} 暴露的 AI 腔、解释腔或可读性问题。`
          : dimension?.strategy === 'rewrite'
            ? `下一章必须围绕 ${label} 重建核心冲突、因果或角色动机。`
            : `下一章必须补强 ${label} 的节奏、格式和信息衔接。`
      ))
      return { key: dimension?.key, label, evidence, fix, score: Number(dimension?.score || 0), strategy: dimension?.strategy }
    })
    .filter((item: any) => item.label || item.evidence || item.fix)
}

function readabilityAiSmellRisks(payload: any) {
  const aiSmell = payload?.ai_smell || payload?.aiSmell || {}
  const level = compactBriefText(aiSmell?.level || payload?.ai_smell_level || payload?.aiSmellLevel)
  const normalizedLevel = level.toLowerCase()
  if (['', '无', 'none', 'no', 'n/a', 'null', 'false', '0'].includes(normalizedLevel)) return null
  const patternHits = asArray(aiSmell?.pattern_hits || aiSmell?.patternHits)
  const tactics = asArray(aiSmell?.rewrite_tactics || aiSmell?.rewriteTactics)
    .map(deliveryRiskItemText)
    .filter(Boolean)
  const evidence = patternHits
    .map((item: any) => deliveryRiskItemText(item?.evidence || item?.type || item))
    .filter(Boolean)
  const count = patternHits.length || tactics.length
  if (count <= 0) return null
  return {
    count,
    item: `去AI味：AI味${level} ${count}`,
    priorityLabel: '优先去AI味',
    evidence: [...tactics, ...evidence].slice(0, 6),
  }
}

function makeDeliveryRiskItem(prefix: string, payload: any, count: number) {
  const label = compactBriefText(payload?.label || payload?.summary, `${prefix} ${count}`)
  return `${prefix}：${label}`
}

function genericSyncRiskStagedActions(reviewType: string, evidence: string[]) {
  const firstEvidence = evidence[0] || '同步风险缺少可见承接。'
  const evidenceText = evidence.join('；')
  if (reviewType === 'benchmark_recall_sync' && /benchmark_anchor_excerpt_copy_risk|原文锚点复制|锚点原句|anchor_excerpts|copied_anchor/i.test(evidenceText)) {
    const anchorEvidence = evidence.find((item: string) => /删除|改写|锚点原句|信息释放手法|anchor_excerpts|原文锚点/i.test(item)) || firstEvidence
    return {
      openingActions: [
        `文风召回开篇修复：前300字先清理上一章 benchmark_anchor_excerpt_copy_risk，不得延续或复述锚点原句；${anchorEvidence}`,
      ],
      middleActions: [
        `文风召回中段修复：只保留锚点的句长、停顿、潜台词和信息释放手法，全部换成本书人物、事件、设定和措辞；${anchorEvidence}`,
      ],
      endingActions: [
        `文风召回章尾复核：章尾检查锚点复制风险是否清零，保留抽象技法但不得出现原文锚点句、桥段、角色名或专名；${anchorEvidence}`,
      ],
    }
  }
  return {
    openingActions: [
      `同步风险开篇承接：前300字先回应 ${reviewType} 的上一章缺口，把它转成当前场景目标、阻碍、证据或状态压力；${firstEvidence}`,
    ],
    middleActions: [
      `同步风险中段兑现：中段必须按 ${reviewType} 的 missed/next_actions 写出可见行动、信息变化、关系变化或状态变化，不能只在旁白里声明已处理；${firstEvidence}`,
    ],
    endingActions: [
      `同步风险章尾复核：章尾复核 ${reviewType} 的缺口是否闭环，并把处理结果转成新状态、新风险或下一章钩子；${firstEvidence}`,
    ],
  }
}

function inferDeliveryRiskStagedActions(actions: any[]) {
  const openingActions: string[] = []
  const middleActions: string[] = []
  const endingActions: string[] = []
  for (const action of actions.map(deliveryRiskItemText).filter(Boolean)) {
    const normalized = action.replace(/\s+/g, '')
    if (normalized.includes('交稿风险必须在本章开篇、场景推进或章末钩子中得到可见承接')) continue
    let matched = false
    if (/(开篇|章首|开场|起笔|第一幕|前300|前三百)/.test(normalized)) {
      openingActions.push(action)
      matched = true
    }
    if (/(章末|章尾|结尾|收束|翻页|钩子|最后300|后三百|下一章|悬念)/.test(normalized)) {
      endingActions.push(action)
      matched = true
    }
    if (/(中段|场景|推进|冲突|反制|追查|证据|边界|关系|资产|伏笔|时间线|状态|恢复|同步|承接|兑现|回报|对白|动作)/.test(normalized)) {
      middleActions.push(action)
      matched = true
    }
    if (!matched) middleActions.push(action)
  }
  return {
    openingActions: uniqueBriefStrings(openingActions, 12),
    middleActions: uniqueBriefStrings(middleActions, 12),
    endingActions: uniqueBriefStrings(endingActions, 12),
  }
}

function normalizeCreationContractCarryOverContext(value: any) {
  if (!value || typeof value !== 'object') return null
  const items = asArray(value.items || value.risk_items || value.riskItems || value.risks)
    .map(deliveryRiskItemText)
    .filter(Boolean)
  const requiredActions = asArray(value.required_actions || value.requiredActions || value.next_actions || value.nextActions)
    .map(deliveryRiskItemText)
    .filter(Boolean)
  const checklist = uniqueBriefStrings(
    asArray(value.checklist || value.creation_contract_checklist || value.creationContractChecklist)
      .map(deliveryRiskItemText)
      .filter(Boolean),
    8,
  )
  const policy = compactBriefText(value.policy)
  if (items.length === 0 && requiredActions.length === 0 && checklist.length === 0 && !policy) return null
  return {
    priority_label: compactBriefText(value.priority_label || value.priorityLabel, '优先修创作契约'),
    items: items.slice(0, 12),
    checklist,
    required_actions: requiredActions.slice(0, 16),
    policy,
  }
}

export function normalizeDeliveryRiskCarryOverContext(value: any) {
  if (!value || typeof value !== 'object') return null
  const creationContractCarryOver = normalizeCreationContractCarryOverContext(
    value.creation_contract_carry_over
    || value.creationContractCarryOver,
  )
  const items = asArray(value.items || value.risk_items || value.riskItems || value.risks)
    .map(deliveryRiskItemText)
    .filter(Boolean)
  const requiredActions = asArray(value.required_actions || value.requiredActions || value.next_actions || value.nextActions)
    .map(deliveryRiskItemText)
    .filter(Boolean)
  const inferredActions = inferDeliveryRiskStagedActions(requiredActions)
  const openingActions = uniqueBriefStrings([
    ...asArray(value.opening_actions || value.openingActions)
      .map(deliveryRiskItemText)
      .filter(Boolean),
    ...inferredActions.openingActions,
  ], 12)
  const middleActions = uniqueBriefStrings([
    ...asArray(value.middle_actions || value.middleActions)
      .map(deliveryRiskItemText)
      .filter(Boolean),
    ...inferredActions.middleActions,
  ], 12)
  const endingActions = uniqueBriefStrings([
    ...asArray(value.ending_actions || value.endingActions)
      .map(deliveryRiskItemText)
      .filter(Boolean),
    ...inferredActions.endingActions,
  ], 12)
  const forbiddenRepeats = uniqueBriefStrings(
    asArray(value.forbidden_repeats || value.forbiddenRepeats)
      .map(deliveryRiskItemText)
      .filter(Boolean),
    12,
  )
  const totalCount = Number(value.total_count ?? value.totalCount ?? value.count ?? items.length)
  const stagedCount = openingActions.length + middleActions.length + endingActions.length
  const creationContractCount = creationContractCarryOver
    ? Math.max(
      creationContractCarryOver.items.length,
      creationContractCarryOver.required_actions.length,
      creationContractCarryOver.checklist.length,
    )
    : 0
  const safeTotal = Number.isFinite(totalCount) && totalCount > 0
    ? totalCount
    : Math.max(items.length, requiredActions.length, stagedCount, creationContractCount, forbiddenRepeats.length)
  if (safeTotal <= 0 && items.length === 0 && requiredActions.length === 0 && stagedCount === 0 && forbiddenRepeats.length === 0 && !creationContractCarryOver) return null
  const sourceChapterNo = Number(value.source_chapter_no ?? value.sourceChapterNo ?? 0) || null
  return {
    source_chapter_no: sourceChapterNo,
    apply_to_chapter_no: Number(value.apply_to_chapter_no ?? value.applyToChapterNo ?? 0) || null,
    total_count: safeTotal,
    label: compactBriefText(value.label, `待修复 ${safeTotal}`),
    priority_label: compactBriefText(value.priority_label || value.priorityLabel, '优先复盘上一章'),
    items: items.slice(0, 12),
    required_actions: requiredActions.slice(0, 12),
    opening_actions: openingActions.slice(0, 12),
    middle_actions: middleActions.slice(0, 12),
    ending_actions: endingActions.slice(0, 12),
    forbidden_repeats: forbiddenRepeats.slice(0, 12),
    evidence: asArray(value.evidence).map(deliveryRiskItemText).filter(Boolean).slice(0, 12),
    source_review_ids: asArray(value.source_review_ids || value.sourceReviewIds).filter(Boolean).slice(0, 12),
    ...(creationContractCarryOver ? { creation_contract_carry_over: creationContractCarryOver } : {}),
  }
}

function deliveryRiskCarryOverFromContext(contextPackage: any = {}) {
  return deliveryRiskCarryOversFromContext(contextPackage)[0] || null
}

function deliveryRiskCarryOversFromContext(contextPackage: any = {}) {
  return [
    contextPackage?.chapter_target?.delivery_risk_carry_over
    || contextPackage?.chapter_target?.deliveryRiskCarryOver,
    contextPackage?.chapterTarget?.delivery_risk_carry_over
    || contextPackage?.chapterTarget?.deliveryRiskCarryOver,
    contextPackage?.batch_preflight?.delivery_risk_carry_over
    || contextPackage?.batch_preflight?.deliveryRiskCarryOver,
    contextPackage?.batchPreflight?.delivery_risk_carry_over
    || contextPackage?.batchPreflight?.deliveryRiskCarryOver,
    contextPackage?.delivery_risk_carry_over
    || contextPackage?.deliveryRiskCarryOver,
  ]
    .map(value => normalizeDeliveryRiskCarryOverContext(value))
    .filter(Boolean)
}

function normalizeDeliveryRiskReceiptDelivered(value: any) {
  if (value === true) return true
  const normalized = String(value || '').trim().toLowerCase()
  return ['true', 'yes', 'ok', 'pass', 'passed', 'delivered'].includes(normalized)
}

function deliveryRiskEvidenceSearchText(value: any) {
  return String(value || '')
    .replace(/[\s"'“”‘’《》【】()[\]{}，。！？、；：,.!?;:|｜\-_/\\]+/g, '')
    .toLowerCase()
}

