function normalizeConflictNextSeedCheck(values: any[], chapterText: string) {
  const planned = conflictStructureArray(values)
  if (!planned.length) return null
  const anchor = conflictStructureAnchorScore(planned, chapterText, 18)
  const tail = String(chapterText || '').slice(-1200)
  const hasSeed = /第二份封单|医院设备|协会会长|亲自追责|下一冲突|指向|章尾|账本|追责/.test(tail)
  const deferred = /下一章再安排新的冲突|之后再说|暂且不提/.test(tail)
  const delivered = !deferred && (anchor.missed.length === 0 || hasSeed)
  return {
    key: 'next_conflict_seeds',
    label: '下一冲突',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? Math.max(84, anchor.score) : Math.min(anchor.score, deferred ? 18 : 50),
    evidence: uniqueBriefStrings([...anchor.evidence, hasSeed ? '下一冲突种子可见' : '', deferred ? '下一冲突被推迟' : ''], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : anchor.missed.map(item => item.text),
    issue: delivered ? '' : '解决当前冲突后没有埋下下一冲突种子，或只说下一章再安排。',
    repair_instruction: delivered ? '' : '补下一冲突种子：在当前胜负结果中自然引出新的阻力、追责、目标或未解证据。',
  }
}

function normalizeConflictNetworkLayersContract(value: any) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null
  const verticalConflict = compactBriefText(value.vertical_conflict || value.verticalConflict || value.vertical || value.authority_conflict || value.authorityConflict)
  const horizontalConflict = compactBriefText(value.horizontal_conflict || value.horizontalConflict || value.horizontal || value.peer_conflict || value.peerConflict)
  const crossConflict = compactBriefText(value.cross_conflict || value.crossConflict || value.cross || value.interlocking_conflict || value.interlockingConflict)
  const weavingOrder = uniqueBriefStrings(asArray(value.weaving_order || value.weavingOrder || value.order || value.steps).map((item: any) => compactBriefText(item)).filter(Boolean), 8)
  if (!verticalConflict && !horizontalConflict && !crossConflict && !weavingOrder.length) return null
  return {
    vertical_conflict: verticalConflict,
    horizontal_conflict: horizontalConflict,
    cross_conflict: crossConflict,
    weaving_order: weavingOrder,
  }
}

function normalizeConflictNetworkLayersCheck(value: any, chapterText: string) {
  const contract = normalizeConflictNetworkLayersContract(value)
  if (!contract) return null
  const text = String(chapterText || '')
  const planned = uniqueBriefStrings([
    contract.vertical_conflict ? `纵向矛盾：${contract.vertical_conflict}` : '',
    contract.horizontal_conflict ? `横向矛盾：${contract.horizontal_conflict}` : '',
    contract.cross_conflict ? `交叉矛盾：${contract.cross_conflict}` : '',
    contract.weaving_order?.length ? `编织顺序：${contract.weaving_order.join(' -> ')}` : '',
  ], 8)
  const hasWeaving = /定地图|定阵营|定角色|地图[^。！？\n]{0,30}阵营|阵营[^。！？\n]{0,30}角色|三层矛盾|同时运作/.test(text)
  const explicitBreak = /只有[^。！？\n]{0,20}一条冲突|其他阵营暂时没有关联|没有竞争|没有被牵连|没有交叉|没有纵向|没有横向|没有关联|没有激活新矛盾/.test(text)
  const negatesVertical = /没有纵向|缺纵向|无纵向/.test(text)
  const negatesHorizontal = /没有横向|缺横向|无横向|没有竞争|没有同业/.test(text)
  const negatesCross = /没有交叉|缺交叉|无交叉|没有被牵连|没有牵连/.test(text)
  const hasVertical = !negatesVertical && /纵向矛盾|上下级|上级权限|下级|服从|压制|反抗|宗主|师徒|君臣|领导[^。！？\n]{0,24}(压|卡|拦|要求|服从)|会长[^。！？\n]{0,24}(上级|权限|要求|压|服从)|规则[^。！？\n]{0,24}(压|卡|拦)|权限[^。！？\n]{0,24}(压|卡|拦|要求)/.test(text)
  const hasHorizontal = !negatesHorizontal && /横向矛盾|理念冲突|资源争夺|同行|同业|情敌|竞争对手|抢单|争夺[^。！？\n]{0,24}(订单|资源|客户|名额|授权)|同层竞争/.test(text)
  const hasCross = !negatesCross && /交叉矛盾|牵连|互相牵连|连锁|因果[^。！？\n]{0,24}牵|A-B|B-C|A-C|解决[^。！？\n]{0,40}(激活|加深|牵动|追责)|会让[^。！？\n]{0,40}(追责|失去|牵连)|一条[^。！？\n]{0,30}另一条/.test(text)
  const delivered = !explicitBreak && hasVertical && hasHorizontal && hasCross
  return {
    key: 'conflict_network_layers',
    label: '三层矛盾网',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 88 : explicitBreak ? 16 : Math.max(24, [hasVertical, hasHorizontal, hasCross, hasWeaving].filter(Boolean).length * 22),
    evidence: uniqueBriefStrings([
      hasVertical ? '纵向矛盾可见' : '',
      hasHorizontal ? '横向矛盾可见' : '',
      hasCross ? '交叉矛盾可见' : '',
      hasWeaving ? '定地图/定阵营/定角色编织顺序可见' : '',
      explicitBreak ? '正文显式写成单线或无牵连' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      !hasVertical ? '缺纵向矛盾' : '',
      !hasHorizontal ? '缺横向矛盾' : '',
      !hasCross ? '缺交叉矛盾' : '',
      explicitBreak ? '正文把三层矛盾写成单线/无牵连' : '',
    ], 8),
    issue: delivered ? '' : '三层矛盾网没有成立：长篇冲突缺少纵向压制、横向竞争或交叉牵连，容易变成单场争执。',
    repair_instruction: delivered ? '' : '补三层矛盾网：先定地图、定阵营、定角色，再同时写纵向矛盾、横向矛盾和交叉矛盾，让一条解决时牵动另一条。',
  }
}

function normalizeConflictWebContract(value: any) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null
  const activeLines = uniqueBriefStrings(asArray(value.active_lines || value.activeLines || value.lines).map((item: any) => compactBriefText(item)).filter(Boolean), 8)
  const linkRules = uniqueBriefStrings(asArray(value.link_rules || value.linkRules || value.links).map((item: any) => compactBriefText(item)).filter(Boolean), 8)
  const activationRules = uniqueBriefStrings(asArray(value.activation_rules || value.activationRules || value.activations).map((item: any) => compactBriefText(item)).filter(Boolean), 8)
  if (!activeLines.length && !linkRules.length && !activationRules.length) return null
  return {
    active_lines: activeLines,
    link_rules: linkRules,
    activation_rules: activationRules,
  }
}

function conflictWebLineMentioned(line: string, chapterText: string) {
  const text = String(chapterText || '')
  const rawLine = compactBriefText(line)
  const lineCore = rawLine.replace(/[线支脉]$/g, '')
  if (!rawLine) return false
  if (text.includes(rawLine) || (lineCore && text.includes(lineCore))) return true
  return anchorMatchScore(rawLine, text).score >= 16 || (lineCore ? anchorMatchScore(lineCore, text).score >= 18 : false)
}

function normalizeConflictWebCheck(value: any, chapterText: string) {
  const contract = normalizeConflictWebContract(value)
  if (!contract) return null
  const text = String(chapterText || '')
  const mentionedLines = contract.active_lines.filter((line: string) => conflictWebLineMentioned(line, text))
  const linkText = contract.link_rules.join('；')
  const activationText = contract.activation_rules.join('；')
  const planned = uniqueBriefStrings([
    contract.active_lines.length ? `活跃矛盾线：${contract.active_lines.join('、')}` : '',
    linkText ? `关联规则：${linkText}` : '',
    activationText ? `激活规则：${activationText}` : '',
  ], 8)
  const hasLink = /因果|利益冲突|信息差|牵连|导致|背后|指向|担保|追责|责任|篡改|互相/.test(text)
  const hasActivation = /解决|阶段解决|但|却|立刻升级|马上升级|激活|加深|追责|继续施压|新矛盾|新危机|更大/.test(text)
  const explicitBreak = /没有关联|没有新的利益冲突|没有激活新矛盾|没有新矛盾|都没有继续施压|各自无关|互不相干|麻烦(?:彻底|全部|都)?消失了/.test(text)
  const enoughLines = contract.active_lines.length ? mentionedLines.length >= Math.min(2, contract.active_lines.length) : /两条矛盾|三条矛盾|2-3条矛盾|两线|三线/.test(text)
  const delivered = !explicitBreak && enoughLines && hasLink && hasActivation
  return {
    key: 'conflict_web',
    label: '矛盾网',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 88 : explicitBreak ? 18 : Math.max(32, [enoughLines, hasLink, hasActivation].filter(Boolean).length * 24),
    evidence: uniqueBriefStrings([
      mentionedLines.length ? `命中矛盾线：${mentionedLines.join('、')}` : '',
      hasLink ? '矛盾线关联可见' : '',
      hasActivation ? '解决后激活/加深信号可见' : '',
      explicitBreak ? '正文显式切断矛盾网' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      !enoughLines ? '同一时刻缺少2-3条活跃矛盾线' : '',
      !hasLink ? '矛盾线之间缺少因果/利益冲突/信息差关联' : '',
      !hasActivation ? '解决一条后没有激活或加深另一条' : '',
      explicitBreak ? '正文把矛盾线写成无关联/无后续压力' : '',
    ], 8),
    issue: delivered ? '' : '矛盾网没有成立：活跃矛盾线不足，或矛盾线之间缺少关联，或解决一条后没有激活/加深另一条。',
    repair_instruction: delivered ? '' : '补矛盾网：同一时刻保持2-3条矛盾线互相牵连，解决一条时必须激活或加深另一条。',
  }
}

function normalizeConflictNoExitCheck(values: any[], chapterText: string) {
  const planned = conflictStructureArray(values)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const looseExit = /可以转身离开|随时能撤|随时退出|可以随时退出|可以随时离开|没有工作职责|没有场所封锁|没有亲友遇险|失败没有代价|身份资格不会受影响|普通争吵/.test(text)
  const negatedGlue = /没有工作职责|没有场所封锁|没有亲友遇险|没有任何[^。！？\n]*(黏住|束缚|理由|职责|责任|场所)/.test(text)
  const forceEntry = !negatedGlue && /非踏入不可|必须[^。！？\n]*(踏入|进入|处理|破局|完成|留下|当场)|不能撤|不能离开|无法袖手旁观|不得不|被迫|值班|接案|任务|工作职责|道德责任|亲人遇险|全楼停电/.test(text)
  const deathStake = /死亡赌注|肉体死亡|身份\/职场死亡|身份死亡|职场死亡|事业死亡|心理死亡|资格归零|一切归零|失败[^。！？\n]*(归零|失去|吊销|退婚|崩塌|完了|没有以后)|退出代价|代价[^。！？\n]*(归零|失去|吊销|停电|遇险)/.test(text)
  const glue = !negatedGlue && /黏结剂|杀人理由|工作职责|道德责任|实体场所|副本|密室|锁死|困在|场所[^。！？\n]*(锁|困|封)|亲人遇险|值班维修师|封单|会长亲自|职责/.test(text)
  const antagonistBound = /对方也退不了|反派[^。！？\n]*(不能退|退不了|必须|职责)|协会成员也退不了|对立双方|双方[^。！？\n]*(无法|不能|退不了|困)|会长亲自下|封单[^。！？\n]*(职责|命令|失证)/.test(text)
  const delivered = !looseExit && forceEntry && deathStake && glue && antagonistBound
  return {
    key: 'no_exit_rules',
    label: '有进无出',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 88 : looseExit ? 12 : Math.max(16, [forceEntry, deathStake, glue, antagonistBound].filter(Boolean).length * 22),
    evidence: uniqueBriefStrings([
      forceEntry ? '主角非踏入不可' : '',
      deathStake ? '死亡赌注/退出代价可见' : '',
      glue ? '黏结剂可见' : '',
      antagonistBound ? '对立方也无法轻易脱身' : '',
      looseExit ? '正文写成可以随时退出/无代价' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      !forceEntry ? '缺强迫性入局理由' : '',
      !deathStake ? '缺死亡赌注/退出代价' : '',
      !glue ? '缺黏结剂' : '',
      !antagonistBound ? '缺对立方无法脱身理由' : '',
      looseExit ? '正文让人物可以随时退出' : '',
    ], 8),
    issue: delivered ? '' : '冲突缺少有进无出：读者会觉得主角或对手可以随时脱离困境，张力无法成立。',
    repair_instruction: delivered ? '' : '补有进无出：给主角非踏入不可的强迫性理由，明确肉体/身份职场/心理死亡赌注，并用杀人理由、工作职责、道德责任或实体场所作为黏结剂，让对立双方都无法轻易脱身。',
  }
}

function buildConflictStructureDeterministicCheck(chapterText: string) {
  const text = String(chapterText || '')
  const risks = [
    /争执了一会儿|大家争执|吵了一会儿/.test(text) ? {
      key: 'summarized_argument',
      label: '争执概括',
      evidence: '正文用争执概括替代冲突阶梯。',
      fix: '拆成言语压力、行动阻碍、激烈对抗和胜负结果。',
    } : null,
    /解释了很多背景|听完觉得有道理|说了很多背景/.test(text) ? {
      key: 'background_solves_conflict',
      label: '背景解释解题',
      evidence: '正文靠解释背景解决冲突，缺少行动阻碍和破局。',
      fix: '把解释改成现场行动、证据核验、规则反制或代价反馈。',
    } : null,
    /没有真正阻力|毫无阻力|没有阻力/.test(text) ? {
      key: 'no_real_obstacle',
      label: '缺真实阻力',
      evidence: '正文直接承认没有真正阻力。',
      fix: '设置有人/规则/资源真实阻止主角得到目标。',
    } : null,
    /没有明确胜负|没有结果/.test(text) ? {
      key: 'no_clear_result',
      label: '胜负不清',
      evidence: '正文直接承认没有明确胜负。',
      fix: '补资格、资源、信息、关系或局势的可见变化。',
    } : null,
    /本章只是过渡|下一章再安排新的冲突|事情很快解决了/.test(text) ? {
      key: 'transition_without_conflict',
      label: '过渡章空转',
      evidence: '正文把冲突推迟或快速抹平。',
      fix: '本章必须有阻止者、升级、胜负变化和下一冲突种子。',
    } : null,
  ].filter(Boolean)
  if (!risks.length) return null
  return {
    key: 'conflict_structure_forbidden',
    label: '冲突结构硬伤',
    text: '冲突结构不得写成争执概括、背景解释解题、没有真实阻力、没有明确胜负或过渡章空转。',
    expected: '冲突结构不得写成争执概括、背景解释解题、没有真实阻力、没有明确胜负或过渡章空转。',
    score: Math.max(0, 100 - risks.length * 24),
    evidence: risks.map((item: any) => compactBriefText(item.evidence || item.fix || item.label)).filter(Boolean).slice(0, 8),
    delivered: false,
    status: 'warn',
    missed_items: risks.map((item: any) => compactBriefText(item.label || item.key)).filter(Boolean).slice(0, 8),
    issue: `正文触发 ${risks.length} 项冲突结构确定性风险。`,
    repair_instruction: '按 oh-story 冲突结构修复：补阻止者、冲突升级阶梯、主角主动破局、明确胜负结果和下一冲突种子。',
  }
}

function conflictStructurePriority(missed: any[]) {
  if (missed.some(item => item.key === 'conflict_structure_forbidden')) return '优先清冲突硬伤'
  if (missed.some(item => item.key === 'conflict_network_layers')) return '优先补三层矛盾网'
  if (missed.some(item => item.key === 'no_exit_rules')) return '优先补有进无出'
  if (missed.some(item => item.key === 'conflict_ladder')) return '优先补冲突阶梯'
  if (missed.some(item => item.key === 'conflict_web')) return '优先补矛盾网'
  if (missed.some(item => item.key === 'protagonist_agency_rules')) return '优先补主角破局'
  if (missed.some(item => item.key === 'event_value_changes')) return '优先补胜负变化'
  if (missed.some(item => item.key === 'antagonist_pressure_rules')) return '优先补压势规则'
  if (missed.some(item => item.key === 'next_conflict_seeds')) return '优先补下一冲突'
  if (missed.some(item => item.key === 'motivation_sources')) return '优先补动机来源'
  return ''
}

export function buildConflictStructureSyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const contract = conflictStructureContractForSync(project, contextPackage, chapter)
  const checks = [
    normalizeConflictLadderCheck(contract.conflict_ladder || contract.conflictLadder, chapterText),
    normalizeConflictMotivationCheck(contract.motivation_sources || contract.motivationSources, chapterText),
    normalizeConflictPressureCheck(contract.antagonist_pressure_rules || contract.antagonistPressureRules, chapterText),
    normalizeConflictAgencyCheck(contract.protagonist_agency_rules || contract.protagonistAgencyRules, chapterText),
    normalizeConflictEventValueCheck(contract.event_value_changes || contract.eventValueChanges, chapterText),
    normalizeConflictNextSeedCheck(contract.next_conflict_seeds || contract.nextConflictSeeds, chapterText),
    normalizeConflictNetworkLayersCheck(contract.conflict_network_layers || contract.conflictNetworkLayers, chapterText),
    normalizeConflictWebCheck(contract.conflict_web || contract.conflictWeb, chapterText),
    normalizeConflictNoExitCheck(contract.no_exit_rules || contract.noExitRules, chapterText),
    buildConflictStructureDeterministicCheck(chapterText),
  ].filter(Boolean)
  const delivered = checks.filter((item: any) => item.delivered)
  const missed = checks.filter((item: any) => !item.delivered)
  const missedCount = missed.length
  const score = Math.max(0, Math.min(100, Math.round(
    checks.length ? checks.reduce((sum: number, item: any) => sum + Number(item.score || 0), 0) / checks.length : 82,
  )))
  const status = missedCount > 0 || score < 78 ? 'warn' : 'ok'
  const priorityRepair = conflictStructurePriority(missed)
  const hasConflictWebMiss = missed.some((item: any) => item.key === 'conflict_web')
  const hasConflictNetworkLayerMiss = missed.some((item: any) => item.key === 'conflict_network_layers')

  return {
    report_id: `conflict-structure-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: checks.length === 0 ? '冲突结构未配置' : status === 'ok' ? '冲突结构 OK' : `冲突结构缺口 ${missedCount}`,
    summary: checks.length === 0
      ? '本章没有配置 conflict_structure_contract，建议补充冲突阶梯、动机来源、压势规则、主角行动力、胜负变化和下一冲突。'
      : status === 'ok'
        ? '正文已基本兑现冲突阶梯、动机来源、压势规则、主角行动力、胜负变化和下一冲突种子。'
        : `正文有 ${missedCount} 项冲突结构缺口，${priorityRepair || '优先补阻止者、冲突阶梯和胜负变化'}。`,
    missed_count: missedCount,
    priority_repair: priorityRepair,
    quality_checks: asArray(contract.quality_checks || contract.qualityChecks).map((item: any) => compactBriefText(item)).filter(Boolean).slice(0, 8),
    planned: checks,
    delivered,
    missed,
    next_actions: status === 'ok'
      ? ['保持冲突结构：继续让阻止者、升级阶梯、主角破局、胜负变化、矛盾网和下一冲突种子可见。']
      : [
          '下一章必须补冲突结构：先设置真实阻止者，再把言语压力升级成行动阻碍、激烈对抗和明确胜负。',
          missed.some((item: any) => item.key === 'no_exit_rules')
            ? '补有进无出：让读者相信主角非踏入不可，明确死亡赌注/退出代价，并用杀人理由、工作职责、道德责任或实体场所把对立双方黏住。'
            : '',
          hasConflictNetworkLayerMiss ? '补三层矛盾网：同时写清纵向/横向/交叉矛盾，按定地图→定阵营→定角色编织，让解决一层时牵动另一层。' : '',
          '让主角主动破局，补清资格/资源/信息/关系/局势变化，并从结果里自然埋下下一冲突种子。',
          hasConflictWebMiss ? '补矛盾网：同一时刻保持2-3条矛盾线互相牵连，解决一条后必须激活或加深另一条。' : '',
      ].filter(Boolean),
  }
}

function upgradeRhythmContractForSync(project: any = {}, contextPackage: any = {}, chapter: any = {}) {
  return buildUpgradeRhythmContract(project, contextWithChapterRawPreDraftForSync(contextPackage, chapter)) || {}
}

function upgradeRhythmArray(...values: any[]) {
  return uniqueBriefStrings(values.flatMap(value => asArray(value)).map((item: any) => assetText(item) || compactBriefText(item)).filter(Boolean), 24)
}

function upgradeRhythmAnchorScore(values: string[], chapterText: string, threshold = 22) {
  const checked = values.map(text => {
    const match = anchorMatchScore(text, chapterText)
    return {
      text,
      score: match.score,
      evidence: match.matched,
      delivered: match.score >= threshold,
    }
  })
  return {
    checked,
    missed: checked.filter(item => !item.delivered),
    score: checked.length ? Math.round(checked.reduce((sum, item) => sum + Number(item.score || 0), 0) / checked.length) : 82,
    evidence: checked.flatMap(item => item.evidence).filter(Boolean).slice(0, 8),
  }
}

function normalizeUpgradeGapCheck(values: any[], chapterText: string) {
  const planned = upgradeRhythmArray(values)
  if (!planned.length) return null
  const anchor = upgradeRhythmAnchorScore(planned, chapterText, 18)
  const text = String(chapterText || '')
  const hasGap = /升级前缺口|质疑[^。！？!?]{0,20}资格|没有资格|权限[^。！？!?]{0,12}卡住|被[^。！？!?]{0,16}看不起|资源获取难度|升级前/.test(text)
  const sudden = /突然升级|直接升级|毫无铺垫/.test(text)
  const delivered = !sudden && (anchor.missed.length === 0 || hasGap)
  return {
    key: 'upgrade_gap',
    label: '升级前缺口',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? Math.max(84, anchor.score) : Math.min(anchor.score, sudden ? 16 : 50),
    evidence: uniqueBriefStrings([...anchor.evidence, hasGap ? '升级前缺口可见' : '', sudden ? '升级突然发生' : ''], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : anchor.missed.map(item => item.text),
    issue: delivered ? '' : '升级前缺口、待遇差距、资源难度或情绪压力没有铺垫，升级显得突然。',
    repair_instruction: delivered ? '' : '补升级前缺口：先写清主角缺什么、被什么卡住、读者为什么期待升级。',
  }
}

function normalizeUpgradeGainCheck(values: any[], chapterText: string) {
  const planned = upgradeRhythmArray(values)
  if (!planned.length) return null
  const anchor = upgradeRhythmAnchorScore(planned, chapterText, 18)
  const text = String(chapterText || '')
  const hasGain = /解锁|隐藏工具箱|客户主动加价|恢复授权|获得|新能力|新技能|权限|称号|奖励/.test(text)
  const rewardOnly = /奖励到账|大家都点头|觉得不错/.test(text) && !/隐藏工具箱|新能力|以前做不到|识别|修复/.test(text)
  const delivered = !rewardOnly && (anchor.missed.length === 0 || hasGain)
  return {
    key: 'upgrade_gain_plan',
    label: '升级收获',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? Math.max(84, anchor.score) : Math.min(anchor.score, rewardOnly ? 20 : 52),
    evidence: uniqueBriefStrings([...anchor.evidence, hasGain ? '升级收获可见' : '', rewardOnly ? '只有奖励到账' : ''], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : anchor.missed.map(item => item.text),
    issue: delivered ? '' : '升级收获只写成奖励到账或众人认可，没有变成能力、权限、资源、地位或目标推进。',
    repair_instruction: delivered ? '' : '补升级收获：写清主角获得了什么能力/权限/资源，以及它如何改变当前局势。',
  }
}

function normalizeUpgradeFeedbackCheck(values: any[], chapterText: string) {
  const planned = upgradeRhythmArray(values)
  if (!planned.length) return null
  const anchor = upgradeRhythmAnchorScore(planned, chapterText, 18)
  const text = String(chapterText || '')
  const hasImmediate = /即时反馈|系统提示|熟练度\s*[+＋]\s*\d+|当场识别|第一次|一眼|直接看见|当场修复/.test(text)
  const hasNewEffect = /以前做不到|新能力|看见隐藏|识别出|修复|反制|压制|第一次/.test(text)
  const hasDelayed = /延迟反馈|第二份封单|医院设备|红色警报|更高门槛|新门槛|下一目标|新的危机/.test(text)
  const deterministicRisks = scanUpgradeAftermathRisks(chapterText)
  const explicitNoEffect = /没有展示新能力|没有以前做不到的事|没有新门槛|事情到这里结束/.test(text)
  const delivered = deterministicRisks.length === 0 && !explicitNoEffect && hasImmediate && hasNewEffect && hasDelayed
  return {
    key: 'feedback_loop',
    label: '反馈闭环',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? Math.max(84, anchor.score) : Math.min(anchor.score, explicitNoEffect ? 12 : 48),
    evidence: uniqueBriefStrings([
      ...anchor.evidence,
      hasImmediate ? '即时反馈可见' : '',
      hasNewEffect ? '新能力/以前做不到的事可见' : '',
      hasDelayed ? '延迟反馈/新门槛可见' : '',
      explicitNoEffect ? '显式缺少升级后果' : '',
      ...deterministicRisks.map((item: any) => item.evidence),
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      !hasImmediate ? '缺即时反馈' : '',
      !hasNewEffect ? '缺新能力展示' : '',
      !hasDelayed ? '缺延迟反馈/新门槛' : '',
      ...deterministicRisks.map((item: any) => item.label),
    ], 8),
    issue: delivered ? '' : '升级后果闭环不完整：缺即时反馈、新能力展示、以前做不到的事或更高门槛。',
    repair_instruction: delivered ? '' : '补反馈闭环：升级后必须马上展示新能力威力，并引入更高门槛、延迟奖励或下一目标。',
  }
}

function normalizeUpgradeEmotionModuleCheck(values: any[], chapterText: string) {
  const planned = upgradeRhythmArray(values)
  if (!planned.length) return null
  const anchor = upgradeRhythmAnchorScore(planned, chapterText, 18)
  const text = String(chapterText || '')
  const hasEmotion = /被质疑|展示能力|打造落差|旁观者震惊|震惊|改口|装逼|爽点|从被质疑转成/.test(text)
  const bland = /大家都点头|觉得不错|很满意|没有波澜/.test(text)
  const delivered = !bland && (anchor.missed.length === 0 || hasEmotion)
  return {
    key: 'emotion_modules',
    label: '情绪模块',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? Math.max(84, anchor.score) : Math.min(anchor.score, bland ? 24 : 52),
    evidence: uniqueBriefStrings([...anchor.evidence, hasEmotion ? '情绪模块/爽点落差可见' : '', bland ? '情绪反馈平淡' : ''], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : anchor.missed.map(item => item.text),
    issue: delivered ? '' : '升级没有形成明确情绪模块，爽点落差、展示能力或旁观者反应不足。',
    repair_instruction: delivered ? '' : '补情绪模块：按被质疑、展示能力、打造落差、旁观者反应释放爽感。',
  }
}

function normalizeUpgradeBridgeRhythmCheck(values: any[], chapterText: string) {
  const planned = upgradeRhythmArray(values)
  if (!planned.length) return null
  const anchor = upgradeRhythmAnchorScore(planned, chapterText, 18)
  const text = String(chapterText || '')
  const hasBridge = /桥段|兑现爽感|承上启下|医院设备|第二份封单|红色警报|下一目标|更高门槛/.test(text)
  const closed = /事情到这里结束|没有新门槛|到此结束|没有下一目标/.test(text)
  const delivered = !closed && (anchor.missed.length === 0 || hasBridge)
  return {
    key: 'bridge_rhythm',
    label: '桥段节奏',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? Math.max(84, anchor.score) : Math.min(anchor.score, closed ? 18 : 50),
    evidence: uniqueBriefStrings([...anchor.evidence, hasBridge ? '桥段承接/新门槛可见' : '', closed ? '升级后闭合无承接' : ''], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : anchor.missed.map(item => item.text),
    issue: delivered ? '' : '本章升级没有接到桥段功能位、承上启下或下一门槛。',
    repair_instruction: delivered ? '' : '补桥段节奏：兑现爽感后必须承上启下，把升级结果接到更高挑战或下一目标。',
  }
}

function normalizeGoldfingerEvolutionContract(value: any) {
  const raw = typeof value === 'object' && value ? value : {}
  const coreFunction = compactBriefText(raw.core_function || raw.coreFunction || raw.core || raw.function || raw.summary || (typeof value === 'string' ? value : ''))
  const allowedExtensions = uniqueBriefStrings(raw.allowed_extensions || raw.allowedExtensions || raw.extensions || raw.development_paths || raw.developmentPaths || [], 8)
  const forbiddenDrifts = uniqueBriefStrings(raw.forbidden_drifts || raw.forbiddenDrifts || raw.red_lines || raw.redLines || [], 8)
  const currentStage = compactBriefText(raw.current_stage || raw.currentStage || raw.stage)
  const foreshadowing = uniqueBriefStrings(raw.foreshadowing || raw.setup || raw.prior_setup || raw.priorSetup || [], 8)
  if (!coreFunction && !allowedExtensions.length && !forbiddenDrifts.length && !currentStage && !foreshadowing.length) return null
  return {
    core_function: coreFunction,
    current_stage: currentStage,
    allowed_extensions: allowedExtensions,
    forbidden_drifts: forbiddenDrifts,
    foreshadowing,
  }
}

function normalizeGoldfingerEvolutionCheck(contractValue: any, chapterText: string) {
  const contract = normalizeGoldfingerEvolutionContract(contractValue)
  if (!contract) return null
  const text = String(chapterText || '')
  const coreMatch = contract.core_function ? anchorMatchScore(contract.core_function, text) : { score: 0, matched: [] }
  const hasCoreFunction = !contract.core_function || coreMatch.score >= 18 || anchorTerms(contract.core_function).some(term => term.length >= 2 && text.includes(term))
  const allowedMatches = contract.allowed_extensions
    .map(item => ({ text: item, match: anchorMatchScore(item, text) }))
    .filter(item => item.match.score >= 18 || anchorTerms(item.text).some(term => term.length >= 2 && text.includes(term)))
  const hasAllowedExtension = contract.allowed_extensions.length === 0 || allowedMatches.length > 0
  const touchedForbidden = contract.forbidden_drifts.filter(item => {
    const phrase = compactBriefText(item)
    return phrase && (text.includes(phrase) || anchorTerms(phrase).some(term => term.length >= 2 && text.includes(term)))
  })
  const hasWorldScaleJump = /掌控天道|成为世界规则|改写天道|万物可签|人人信仰|世界规则都(?:跪伏|臣服|改写)|天道层级/.test(text)
  const hasForeshadowing = contract.foreshadowing.length > 0
    ? contract.foreshadowing.some(item => anchorMatchScore(item, text).score >= 18)
    : /伏笔|此前铺垫|早已埋下|上一章|前文|规则源头|地脉|世界规则/.test(text)
  const hasNoForeshadowing = /没有任何伏笔|此前没有伏笔|毫无伏笔/.test(text)
  const delivered = hasCoreFunction && hasAllowedExtension && touchedForbidden.length === 0 && (!hasWorldScaleJump || (hasForeshadowing && !hasNoForeshadowing))
  return {
    key: 'goldfinger_evolution_drift',
    label: '金手指演进',
    text: contract.core_function || contract.allowed_extensions.join('；') || '金手指核心作用必须持续。',
    expected: '金手指核心作用可发展但不能换赛道；升华到世界/规则层级必须有伏笔。',
    score: delivered ? 88 : Math.max(12, [hasCoreFunction, hasAllowedExtension, touchedForbidden.length === 0, !hasWorldScaleJump || hasForeshadowing].filter(Boolean).length * 22),
    evidence: uniqueBriefStrings([
      ...asArray(coreMatch.matched),
      ...allowedMatches.flatMap(item => item.match.matched),
      hasCoreFunction ? '核心作用仍在' : '',
      hasAllowedExtension ? '允许扩展可见' : '',
      touchedForbidden.length ? `触碰禁漂移：${touchedForbidden.join('、')}` : '',
      hasWorldScaleJump && !hasForeshadowing ? '世界/天道层级跳跃缺少伏笔' : '',
      hasNoForeshadowing ? '正文承认没有伏笔' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      !hasCoreFunction ? '核心作用丢失' : '',
      !hasAllowedExtension ? '缺少允许的发展方向' : '',
      ...touchedForbidden,
      hasWorldScaleJump && (!hasForeshadowing || hasNoForeshadowing) ? '升华缺少伏笔' : '',
    ], 8),
    issue: delivered ? '' : '金手指演进偏离核心作用、触碰禁漂移，或在缺少伏笔时突然升华到世界/规则层级。',
    repair_instruction: delivered ? '' : '校准金手指演进：保留核心作用，只增加新的使用方式；如果要升华到世界/规则层级，先补足伏笔和阶段递增。',
  }
}

function normalizeGoldfingerConflictBalanceCheck(values: any, chapterText: string) {
  const planned = asArray(values).map((item: any) => compactBriefText(item)).filter(Boolean)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const hasGoldfinger = /金手指|系统|面板|能力|技能|隐藏工具箱|维修系统|超人力量|规则漏洞|底牌/.test(text)
  const hasCurrentConflict = /质疑|没有资格|权限|阻碍|卡住|危机|矛盾|对手|协会|客户|规则|封锁|门槛/.test(text)
  const changesSituation = /刚好|识别|拆解|修好|反制|改变局势|阶段收益|熟练度|加价|授权|震惊|压制|拿到|发现|打开/.test(text)
  const exposesBiggerConflict = /更大矛盾|更高门槛|新门槛|下一目标|下一章|新危机|红色警报|医院设备|新封单|延迟反馈|代价|风险|暴露/.test(text)
  const overpoweredText = text.replace(/没有一键清场|不是一键清场|并非一键清场/g, '')
  const overpowered = /一键解决所有问题|一键清场|全部自动(?:修好|解决)|所有问题都(?:解决|消失)|所有对手全部认输|矛盾彻底消失|没有更大矛盾|没有新门槛|事情到这里结束/.test(overpoweredText)
  const tooWeak = /毫无作用|没有任何作用|无法改变局势|完全没用|读者焦虑/.test(text)
  const delivered = hasGoldfinger && hasCurrentConflict && changesSituation && exposesBiggerConflict && !overpowered && !tooWeak
  return {
    key: 'goldfinger_conflict_balance',
    label: '金手指矛盾匹配',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 88 : Math.max(12, [hasGoldfinger, hasCurrentConflict, changesSituation, exposesBiggerConflict, !overpowered, !tooWeak].filter(Boolean).length * 14),
    evidence: uniqueBriefStrings([
      hasGoldfinger ? '金手指/能力进入正文' : '',
      hasCurrentConflict ? '当前矛盾可见' : '',
      changesSituation ? '能力改变局势或拿到阶段收益' : '',
      exposesBiggerConflict ? '解决后暴露更大矛盾/新门槛' : '',
      overpowered ? '金手指过强或一键清场' : '',
      tooWeak ? '金手指过弱无法改变局势' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      !hasGoldfinger ? '缺金手指/能力使用' : '',
      !hasCurrentConflict ? '缺当前矛盾' : '',
      !changesSituation ? '能力没有改变局势' : '',
      !exposesBiggerConflict ? '缺更大矛盾/新门槛' : '',
      overpowered ? '金手指太强导致无聊' : '',
      tooWeak ? '金手指太弱导致焦虑' : '',
    ], 8),
    issue: delivered ? '' : '金手指与当前矛盾强弱不匹配，可能一键清场、无法改变局势，或解决后没有暴露更大矛盾。',
    repair_instruction: delivered ? '' : '按 oh-story 金手指 + 矛盾法修复：让金手指刚好解决当前矛盾，拿到阶段收益，同时暴露更大矛盾、更高门槛或下一目标。',
  }
}

function normalizeGoldfingerSimplicityCheck(values: any, chapterText: string) {
  const planned = asArray(values).map((item: any) => compactBriefText(item)).filter(Boolean)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const hasSimpleCore = /金手指简单|简单清晰|一眼就懂|面板只显示|只展示一种核心用法|仍然围绕|同一套(?:维修)?逻辑|核心作用/.test(text)
  const hasFunction = /功能|核心用法|错误码|拆解路线|识别|检测|修复|反证|面板/.test(text)
  const hasTrigger = /触发条件|接触设备|接触|靠近|扫描|检测到|启动条件|当场识别|识别[^。！？!?]{0,16}(?:设备|错误码|错误链)/.test(text)
  const hasReward = /奖励反馈|熟练度\+?10|经验值|阶段收益|奖励|反馈|收益/.test(text)
  const hasUpgradeRule = /升级规则|下一门槛|新门槛|熟练度|升级|门槛/.test(text)
  const manualText = text.replace(/不是说明书|不能写成说明书|避免.*说明书|删掉说明书/g, '')
  const hasOverloadedSystem = /十几种模块|天赋|羁绊|规则树|隐藏权限|没人知道触发条件|没人知道.*升级规则|说明书|万能外挂/.test(manualText)
  const delivered = hasSimpleCore && hasFunction && hasTrigger && hasReward && hasUpgradeRule && !hasOverloadedSystem
  return {
    key: 'goldfinger_simplicity_rules',
    label: '金手指简单清晰',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 88 : Math.max(12, [hasSimpleCore, hasFunction, hasTrigger, hasReward, hasUpgradeRule, !hasOverloadedSystem].filter(Boolean).length * 14),
    evidence: uniqueBriefStrings([
      hasSimpleCore ? '金手指简单清晰/一眼就懂' : '',
      hasFunction ? '功能可见' : '',
      hasTrigger ? '触发条件可见' : '',
      hasReward ? '奖励反馈可见' : '',
      hasUpgradeRule ? '升级规则/下一门槛可见' : '',
      hasOverloadedSystem ? '规则过载或说明书式系统' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      !hasSimpleCore ? '缺一眼就懂的简单核心' : '',
      !hasFunction ? '缺功能说明' : '',
      !hasTrigger ? '缺触发条件' : '',
      !hasReward ? '缺奖励反馈' : '',
      !hasUpgradeRule ? '缺升级规则/下一门槛' : '',
      hasOverloadedSystem ? '系统写成说明书、规则树或万能外挂' : '',
    ], 8),
    issue: delivered ? '' : '金手指不够简单清晰，功能、触发条件、奖励反馈或升级规则缺少正文证据，或系统规则过载。',
    repair_instruction: delivered ? '' : '简化金手指：功能、触发条件、奖励反馈和升级规则必须一眼就懂；本章只展示一种核心用法，删掉说明书式规则树和万能外挂。',
  }
}

function normalizeGoldfingerMultiDimensionGrowthCheck(values: any, chapterText: string) {
  const planned = asArray(values).map((item: any) => compactBriefText(item)).filter(Boolean)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const hasTermLine = /词条|标签|特性|属性|静音校准|掠夺词条|词条可融合/.test(text)
  const hasFunctionLine = /功能|新功能|子能力|工具箱|解锁|联动|应用场景|使用方式|识别隐藏|隐藏错误链|拆解路线/.test(text)
  const hasQualityLine = /品质|品阶|A档|S档|SS|质量|装备|零件|资源|加价|授权|报废/.test(text)
  const hasProgressionLine = /熟练度|经验值|等级|进度条|不倒退|不会衰减|重复提升|阶段|升级|发展/.test(text)
  const hasConditionFeedbackLine = /条件-反馈|条件|反馈|完成[^。！？!?]{0,18}(?:订单|任务|维修)|做[^。！？!?]{0,12}获得|触发|阶段反馈|条件升级|概率性反馈|延迟反馈/.test(text)
  const oneDimensionTrap = /只(?:把|剩|靠)?[^。！？!?]{0,18}(?:品质|数值|等级)[^。！？!?]{0,24}(?:提升|升到|升级)|只剩[^。！？!?]{0,18}(?:品质|数值|等级)[^。！？!?]{0,18}(?:一个维度|单一维度)|单一维度|其他词条、功能、条件反馈都没有变化|词条、功能、条件反馈都没有变化/.test(text)
  const dimensionCount = [hasTermLine, hasFunctionLine, hasQualityLine, hasProgressionLine, hasConditionFeedbackLine].filter(Boolean).length
  const delivered = dimensionCount >= 2 && !oneDimensionTrap
  return {
    key: 'goldfinger_multi_dimension_growth_rules',
    label: '金手指多维成长',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 88 : Math.max(12, dimensionCount * 18 - (oneDimensionTrap ? 20 : 0)),
    evidence: uniqueBriefStrings([
      hasTermLine ? '词条/特性成长可见' : '',
      hasFunctionLine ? '功能/子能力成长可见' : '',
      hasQualityLine ? '品质/资源成长可见' : '',
      hasProgressionLine ? '熟练度/等级/阶段成长可见' : '',
      hasConditionFeedbackLine ? '条件-反馈链可见' : '',
      oneDimensionTrap ? '升级只剩单一维度' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      dimensionCount < 2 ? '金手指成长维度不足' : '',
      !hasTermLine ? '缺词条/特性线' : '',
      !hasFunctionLine ? '缺功能/子能力线' : '',
      !hasConditionFeedbackLine ? '缺条件-反馈链' : '',
      oneDimensionTrap ? '只靠品质/数值/等级单线提升' : '',
    ], 8),
    issue: delivered ? '' : '金手指成长缺少多维度，可能只剩品质、数值或等级提升，后期提升感会消失。',
    repair_instruction: delivered ? '' : '补金手指多维成长：至少让词条、功能、品质、熟练度或条件-反馈中的两条线同步变化；条件升级后，反馈可解锁新功能、子能力或新的应用场景。',
  }
}

function normalizeUpgradeRankingLadderCheck(values: any, chapterText: string) {
  const planned = asArray(values).map((item: any) => compactBriefText(item)).filter(Boolean)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const hasRankingContext = /排行榜|榜单|排名|名次|维修榜|战力榜|榜外|入榜|冲榜|升到第|第[一二三四五六七八九十百千万\d]+名/.test(text)
  if (!hasRankingContext) return null
  const hasRankMotion = /(?:排名|名次|榜单|维修榜)[^。！？!?]{0,40}(?:提升|上升|刷新|提高|变化|升到|入榜)|从榜外升到|榜外[^。！？!?]{0,24}第[一二三四五六七八九十百千万\d]+名|冲(?:榜|第[一二三四五六七八九十百千万\d]+名)|下一(?:名|名次|目标)|期待[^。！？!?]{0,24}(?:下一名|名次|冲榜)/.test(text)
  const hasNewOpponent = /新对手|同榜竞争者|下一(?:名|位)|前一(?:名|位)|上一(?:名|位)|第[一二三四五六七八九十百千万\d]+名[^。！？!?]{0,40}(?:名字|对手|师|敌|高手|竞争者|接下|亮出|出现)|榜单[^。！？!?]{0,48}(?:介绍|亮出|露出|出现)[^。！？!?]{0,40}(?:对手|名字|竞争者|下一名)|排名碰撞|榜单碰撞/.test(text)
  const hasAftershock = /余震|传开|重新(?:报价|评估|排队)|客户群|订单[^。！？!?]{0,20}(?:上涨|增加|重新)|态度[^。！？!?]{0,20}(?:转变|变化|改口)|资源[^。！？!?]{0,20}(?:倾斜|增加|到手)|权限[^。！？!?]{0,20}(?:变化|开放|提高)|规则评价[^。！？!?]{0,20}(?:改写|改变|重评)|协会[^。！？!?]{0,40}(?:重评|改写|重新评价)|声望|名望|后续挑战|下一章[^。！？!?]{0,32}(?:排名|碰撞|榜单)/.test(text)
  const hollowRanking = /排名提升[^。！？!?]{0,30}(?:事情结束|到此结束)|榜单[^。！？!?]{0,30}事情结束|只写(?:排名|名次)|只是(?:排名|名次)|没有(?:新对手|余震|后续挑战)/.test(text)
  const delivered = hasRankMotion && hasNewOpponent && hasAftershock && !hollowRanking
  return {
    key: 'ranking_ladder_rules',
    label: '榜单升级动力',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 88 : Math.max(18, [hasRankMotion, hasNewOpponent, hasAftershock, !hollowRanking].filter(Boolean).length * 22),
    evidence: uniqueBriefStrings([
      hasRankMotion ? '排名/名次变化可见' : '',
      hasNewOpponent ? '榜单带出新对手/下一名' : '',
      hasAftershock ? '装逼余震影响态度/资源/规则评价' : '',
      hollowRanking ? '榜单只做数字结算' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      !hasRankMotion ? '缺排名提升带来的升级动力' : '',
      !hasNewOpponent ? '缺新对手/下一名碰撞期待' : '',
      !hasAftershock ? '缺榜单余震对态度、资源、权限或规则评价的影响' : '',
      hollowRanking ? '榜单只写成结算数字' : '',
    ], 8),
    issue: delivered ? '' : '榜单没有发挥升级动力：排名变化缺新对手、后续碰撞或装逼余震。',
    repair_instruction: delivered ? '' : '补榜单升级动力：排名提升后立刻给下一名次/下一目标；通过排行榜介绍新对手；让榜单余震改变他人态度、报价、资源、权限或规则评价。',
  }
}

function buildUpgradeRhythmDeterministicCheck(chapterText: string) {
  const text = String(chapterText || '')
  const risks = [
    /突然升级|直接升级|毫无铺垫/.test(text) ? {
      key: 'sudden_upgrade',
      label: '突然升级',
      evidence: '升级前缺少情绪缺口、资源难度或待遇差距铺垫。',
      fix: '先补升级前缺口，再给即时反馈和升级后变化。',
    } : null,
    /奖励到账|大家都点头|客户觉得不错/.test(text) && !/新能力|以前做不到|识别|修复|反制|更高门槛/.test(text) ? {
      key: 'reward_only',
      label: '只有奖励',
      evidence: '升级只写成奖励到账或众人认可。',
      fix: '补新能力威力、以前做不到的事和阶段收益。',
    } : null,
    /没有展示新能力|没有以前做不到的事/.test(text) ? {
      key: 'no_new_effect',
      label: '缺新能力展示',
      evidence: '正文直接承认没有展示新能力或以前做不到的事。',
      fix: '让升级后能力改变现场判断、行动、结果或门槛。',
    } : null,
    /没有新门槛|事情到这里结束|没有下一目标/.test(text) ? {
      key: 'no_next_threshold',
      label: '缺新门槛',
      evidence: '升级后没有更高门槛、延迟反馈或下一目标。',
      fix: '升级后立刻引入更高挑战、新危机、延迟奖励或下一任务。',
    } : null,
  ].filter(Boolean)
  if (!risks.length) return null
  return {
    key: 'upgrade_rhythm_forbidden',
    label: '升级节奏硬伤',
    text: '升级节奏不得突然升级、只奖励到账、缺新能力展示或缺下一门槛。',
    expected: '升级节奏不得突然升级、只奖励到账、缺新能力展示或缺下一门槛。',
    score: Math.max(0, 100 - risks.length * 24),
    evidence: risks.map((item: any) => compactBriefText(item.evidence || item.fix || item.label)).filter(Boolean).slice(0, 8),
    delivered: false,
    status: 'warn',
    missed_items: risks.map((item: any) => compactBriefText(item.label || item.key)).filter(Boolean).slice(0, 8),
    issue: `正文触发 ${risks.length} 项升级节奏确定性风险。`,
    repair_instruction: '按 oh-story 升级感三步法修复：补升级前缺口、即时反馈、新能力展示、延迟反馈和更高门槛。',
  }
}

function upgradeRhythmPriority(missed: any[]) {
  if (missed.some(item => item.key === 'ranking_ladder_rules')) return '优先补榜单升级动力'
  if (missed.some(item => item.key === 'goldfinger_evolution_drift')) return '优先校准金手指演进'
  if (missed.some(item => item.key === 'goldfinger_conflict_balance')) return '优先校准金手指矛盾'
  if (missed.some(item => item.key === 'goldfinger_simplicity_rules')) return '优先简化金手指'
  if (missed.some(item => item.key === 'goldfinger_multi_dimension_growth_rules')) return '优先扩展金手指成长维度'
  if (missed.some(item => item.key === 'upgrade_rhythm_forbidden')) return '优先清升级硬伤'
  if (missed.some(item => item.key === 'feedback_loop')) return '优先补反馈闭环'
  if (missed.some(item => item.key === 'upgrade_gap')) return '优先补升级前缺口'
  if (missed.some(item => item.key === 'upgrade_gain_plan')) return '优先补升级收获'
  if (missed.some(item => item.key === 'bridge_rhythm')) return '优先补桥段承接'
  if (missed.some(item => item.key === 'emotion_modules')) return '优先补情绪模块'
  return ''
}

export function buildUpgradeRhythmSyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const contract = upgradeRhythmContractForSync(project, contextPackage, chapter)
  const checks = [
    normalizeUpgradeGapCheck(contract.upgrade_gap || contract.upgradeGap, chapterText),
    normalizeUpgradeGainCheck(contract.upgrade_gain_plan || contract.upgradeGainPlan, chapterText),
    normalizeUpgradeFeedbackCheck(contract.feedback_loop || contract.feedbackLoop, chapterText),
    normalizeUpgradeEmotionModuleCheck(contract.emotion_modules || contract.emotionModules, chapterText),
    normalizeUpgradeBridgeRhythmCheck(contract.bridge_rhythm || contract.bridgeRhythm, chapterText),
    normalizeGoldfingerEvolutionCheck(contract.goldfinger_evolution || contract.goldfingerEvolution, chapterText),
    normalizeGoldfingerConflictBalanceCheck(contract.goldfinger_conflict_balance_rules || contract.goldfingerConflictBalanceRules, chapterText),
    normalizeGoldfingerSimplicityCheck(contract.goldfinger_simplicity_rules || contract.goldfingerSimplicityRules, chapterText),
    normalizeGoldfingerMultiDimensionGrowthCheck(contract.goldfinger_multi_dimension_growth_rules || contract.goldfingerMultiDimensionGrowthRules, chapterText),
    normalizeUpgradeRankingLadderCheck(contract.ranking_ladder_rules || contract.rankingLadderRules, chapterText),
    buildUpgradeRhythmDeterministicCheck(chapterText),
  ].filter(Boolean)
  const delivered = checks.filter((item: any) => item.delivered)
  const missed = checks.filter((item: any) => !item.delivered)
  const missedCount = missed.length
  const score = Math.max(0, Math.min(100, Math.round(
    checks.length ? checks.reduce((sum: number, item: any) => sum + Number(item.score || 0), 0) / checks.length : 82,
  )))
  const status = missedCount > 0 || score < 78 ? 'warn' : 'ok'
  const priorityRepair = upgradeRhythmPriority(missed)

  return {
    report_id: `upgrade-rhythm-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: checks.length === 0 ? '升级节奏未配置' : status === 'ok' ? '升级节奏 OK' : `升级节奏缺口 ${missedCount}`,
    summary: checks.length === 0
      ? '本章没有配置 upgrade_rhythm_contract，建议补充升级前缺口、升级收获、反馈闭环、情绪模块、桥段节奏和榜单升级动力。'
      : status === 'ok'
        ? '正文已基本兑现升级前缺口、升级收获、即时/延迟反馈、情绪模块、桥段承接和榜单升级动力。'
        : `正文有 ${missedCount} 项升级节奏缺口，${priorityRepair || '优先补升级前缺口、反馈闭环、榜单升级动力和下一门槛'}。`,
    missed_count: missedCount,
    priority_repair: priorityRepair,
    quality_checks: asArray(contract.quality_checks || contract.qualityChecks).map((item: any) => compactBriefText(item)).filter(Boolean).slice(0, 8),
    planned: checks,
    delivered,
    missed,
    next_actions: status === 'ok'
      ? ['保持升级节奏：升级前缺口、即时反馈、新能力展示、延迟反馈、榜单升级动力和下一门槛都要可见。']
      : [
          '下一章必须补升级节奏：先补升级前缺口，再展示新能力或以前做不到的事。',
          '升级后立刻给即时反馈和阶段收益，同时引入更高门槛、延迟奖励或下一目标，避免奖励到账后事情结束。',
          missed.some((item: any) => item.key === 'ranking_ladder_rules')
            ? '补榜单升级动力：排名提升后挂出下一名次或下一目标，通过排行榜介绍新对手，并写出装逼余震如何改变态度、报价、资源、权限或规则评价。'
            : '',
          missed.some((item: any) => item.key === 'goldfinger_conflict_balance')
            ? '金手指必须刚好解决当前矛盾，不能一键清场或完全没用；解决后必须暴露更大矛盾、更高门槛或下一目标。'
            : '',
          missed.some((item: any) => item.key === 'goldfinger_simplicity_rules')
            ? '简化金手指：功能、触发条件、奖励反馈和升级规则必须一眼就懂，删掉说明书式规则树和万能外挂。'
            : '',
          missed.some((item: any) => item.key === 'goldfinger_multi_dimension_growth_rules')
            ? '补金手指多维成长：至少让词条、功能、品质、熟练度或条件-反馈中的两条线同步变化，避免只剩品质/数值单线提升。'
            : '',
          missed.some((item: any) => item.key === 'goldfinger_evolution_drift')
            ? '金手指演进必须保留核心作用，只增加新的使用方式；升华到世界/规则层级前先补伏笔。'
            : '',
      ].filter(Boolean),
  }
}

function targetReaderContractForSync(project: any, contextPackage: any, chapter: any = {}) {
  return buildTargetReaderContract(project, contextWithChapterRawPreDraftForSync(contextPackage, chapter))
}

function targetReaderArray(values: any) {
  return asArray(values).map((item: any) => compactBriefText(item)).filter(Boolean)
}

function countTargetReaderSignals(chapterText: string, patterns: RegExp[]) {
  const text = String(chapterText || '')
  return patterns.reduce((count, pattern) => count + (pattern.test(text) ? 1 : 0), 0)
}

function normalizeTargetReaderProfileCheck(value: any, chapterText: string) {
  const expected = compactBriefText(value)
  if (!expected) return null
  const match = anchorMatchScore(expected, chapterText)
  const signalCount = countTargetReaderSignals(chapterText, [
    /番茄|男频|女频|平台|类型读者|目标读者/,
    /碎片|追更|短平快|快节奏/,
    /快速反馈|即时反馈|当场反馈/,
    /爽感|掌控感|尊严|补偿/,
  ])
  const hollowReaderClaim = /读者会喜欢|大家会喜欢/.test(String(chapterText || ''))
  const delivered = !hollowReaderClaim && (match.score >= 36 || signalCount >= 2)
  return {
    key: 'reader_profile',
    label: '读者画像',
    text: expected,
    expected,
    score: delivered ? Math.max(84, match.score) : Math.min(match.score, hollowReaderClaim ? 24 : 52),
    evidence: uniqueBriefStrings([
      ...match.matched,
      signalCount >= 2 ? '目标读者画像代理信号可见' : '',
      hollowReaderClaim ? '空泛读者判断' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : ['缺少可见目标读者画像或只写空泛读者判断'],
    issue: delivered ? '' : '目标读者画像没有转成正文可见的口味、平台、追更节奏或情绪需求。',
    repair_instruction: delivered ? '' : '补目标读者画像：用追更节奏、平台口味、爽感/掌控感/快速反馈等信号校准本章表达。',
  }
}

function normalizeTargetReaderDesireCheck(values: any[], chapterText: string) {
  const planned = targetReaderArray(values)
  if (!planned.length) return null
  const scored = planned.map(item => ({ text: item, match: anchorMatchScore(item, chapterText) }))
  const text = String(chapterText || '')
  const desireSignals = countTargetReaderSignals(text, [
    /规则反制|反制|规则边界/,
    /智斗|信息差|破局/,
    /不公平|拿掉|反打|压迫/,
    /爽点|爽感|掌控感/,
    /升级|即时反馈|快速反馈/,
  ])
  const deliveredItems = scored.filter(item => item.match.score >= 32).length
  const delivered = deliveredItems >= Math.max(1, Math.ceil(planned.length * 0.4)) || desireSignals >= 3
  return {
    key: 'reader_desires',
    label: '读者欲望',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? Math.max(84, Math.round((deliveredItems / Math.max(1, planned.length)) * 100)) : Math.max(18, desireSignals * 16),
    evidence: uniqueBriefStrings([
      ...scored.flatMap(item => item.match.matched),
      desireSignals >= 3 ? '读者欲望代理信号可见' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : planned.filter(item => anchorMatchScore(item, chapterText).score < 32).slice(0, 8),
    issue: delivered ? '' : '目标读者想看的规则反制、信息差、不公平移除、爽点或即时反馈没有落成正文事件。',
    repair_instruction: delivered ? '' : '补读者欲望：把目标读者想看的内容写成主角行动、现场反制、即时反馈和可见结果。',
  }
}

function normalizeTargetReaderEmotionalGapCheck(values: any[], chapterText: string) {
  const planned = targetReaderArray(values)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const scored = planned.map(item => ({ text: item, match: anchorMatchScore(item, chapterText) }))
  const gapSignals = countTargetReaderSignals(text, [
    /情绪缺口|核心痛苦|深层情结|未满足需求/,
    /不甘|渴望|逃避|爱|恨/,
    /掌控感|安全感|尊严|补偿|解气/,
    /被规则压着走|被安排|不公平|被轻视|被否定/,
    /快速反馈|即时反馈|亲手反制|拿回/,
  ])
  const hollowReaderClaim = /读者会喜欢|大家会喜欢/.test(text) && !/核心痛苦|情绪缺口|不甘|掌控感|未满足需求/.test(text)
  const deliveredItems = scored.filter(item => item.match.score >= 30).length
  const delivered = !hollowReaderClaim && (deliveredItems >= Math.max(1, Math.ceil(planned.length * 0.35)) || gapSignals >= 3)
  return {
    key: 'emotional_gap_analysis',
    label: '情绪缺口',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? Math.max(84, Math.round((deliveredItems / Math.max(1, planned.length)) * 100)) : Math.max(18, gapSignals * 16),
    evidence: uniqueBriefStrings([
      ...scored.flatMap(item => item.match.matched),
      gapSignals >= 3 ? '情绪缺口代理信号可见' : '',
      hollowReaderClaim ? '空泛读者判断未触及核心痛苦' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : planned.filter(item => anchorMatchScore(item, chapterText).score < 30).slice(0, 8),
    issue: delivered ? '' : '目标读者的核心痛苦、深层情结、高频情绪关键词或未满足需求没有落成正文情绪缺口。',
    repair_instruction: delivered ? '' : '按 oh-story 情绪缺口分析修复：从目标读者画像推核心痛苦和深层情结，把不甘、渴望、掌控、安全感、尊严补偿等未满足需求写成冲突压力和读者回报。',
  }
}

function normalizeTargetReaderAttractionCheck(values: any[], chapterText: string) {
  const planned = targetReaderArray(values)
  if (!planned.length) return null
  const scored = planned.map(item => ({ text: item, match: anchorMatchScore(item, chapterText) }))
  const text = String(chapterText || '')
  const attractionSignals = countTargetReaderSignals(text, [
    /超人蛮力|规则反制|信息差/,
    /门外水声|旧钥匙缺口|可见线索/,
    /可见回报|回报|章尾期待|下一章/,
    /客户.*反应|退让|结果/,
  ])
  const deliveredItems = scored.filter(item => item.match.score >= 34).length
  const delivered = deliveredItems >= Math.max(1, Math.ceil(planned.length * 0.45)) || attractionSignals >= 2
  return {
    key: 'chapter_attractions',
    label: '本章吸引点',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? Math.max(84, Math.round((deliveredItems / Math.max(1, planned.length)) * 100)) : Math.max(18, attractionSignals * 18),
    evidence: uniqueBriefStrings([
      ...scored.flatMap(item => item.match.matched),
      attractionSignals >= 2 ? '本章吸引点代理信号可见' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : planned.filter(item => anchorMatchScore(item, chapterText).score < 34).slice(0, 8),
    issue: delivered ? '' : '本章吸引点没有写成可复述的场面、线索、反制结果或章尾期待。',
    repair_instruction: delivered ? '' : '补本章吸引点：把卖点落成具体场景，让读者看见线索、反应、结果和章尾问题。',
  }
}

function normalizeTargetReaderValidationCheck(values: any[], chapterText: string) {
  const planned = targetReaderArray(values)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const profileSignals = countTargetReaderSignals(text, [/目标读者|男频|女频|番茄|追更|碎片/, /爽感|掌控感|快速反馈/])
  const desireSignals = countTargetReaderSignals(text, [/规则反制|信息差|不公平|爽点|即时反馈/])
  const payoffSignals = countTargetReaderSignals(text, [/回报|结果|反应|章尾期待|可见线索|下一章/])
  const delivered = profileSignals >= 1 && desireSignals >= 1 && payoffSignals >= 1
  return {
    key: 'validation_questions',
    label: '三问验证',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 88 : Math.max(18, (profileSignals + desireSignals + payoffSignals) * 18),
    evidence: uniqueBriefStrings([
      profileSignals ? '写给谁可见' : '',
      desireSignals ? '想看什么可见' : '',
      payoffSignals ? '本章回报可见' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      !profileSignals ? '缺写给谁' : '',
      !desireSignals ? '缺目标读者想看什么' : '',
      !payoffSignals ? '缺本章可感知回报' : '',
    ], 8),
    issue: delivered ? '' : '目标读者三问缺少正文证据：写给谁、想看什么、本章给了什么回报。',
    repair_instruction: delivered ? '' : '补三问验证：明确读者画像、读者欲望和本章可感知回报，每项都必须有正文证据。',
  }
}

function normalizeTargetReaderCorrectionMethodCheck(values: any[], chapterText: string) {
  const planned = targetReaderArray(values)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const correctionSignals = countTargetReaderSignals(text, [
    /删掉|删除|没有停在|不再停在/,
    /自嗨|设定展示|展示设定/,
    /动作|反应|结果/,
    /章尾期待|可感知回报|卖点/,
  ])
  const selfIndulgent = /作者觉得|世界观很有意思|主要展示设定|只是介绍设定/.test(text) && !/动作|反应|结果|回报/.test(text)
  const delivered = !selfIndulgent && correctionSignals >= 3
  return {
    key: 'correction_methods',
    label: '修正方法',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 86 : Math.max(16, correctionSignals * 18),
    evidence: uniqueBriefStrings([
      correctionSignals >= 3 ? '修正方法已转成正文执行信号' : '',
      selfIndulgent ? '仍停留在作者自嗨/设定展示' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : ['缺少把设定展示改成动作、反应、结果和章尾期待的执行证据'],
    issue: delivered ? '' : '修正方法没有落地，正文仍可能停在作者自嗨设定展示。',
    repair_instruction: delivered ? '' : '按修正方法重写：删掉作者自嗨设定展示，把卖点落成动作、反应、结果和章尾期待。',
  }
}

function buildTargetReaderDeterministicCheck(chapterText: string) {
  const text = String(chapterText || '')
  const risks = [
    /读者会喜欢|大家会喜欢/.test(text) ? {
      key: 'hollow_reader_claim',
      label: '空泛读者判断',
      evidence: '正文用“读者会喜欢/大家会喜欢”替代目标读者证据。',
      fix: '改成具体读者画像、想看内容和可感知回报。',
    } : null,
    /作者觉得|我觉得|世界观很有意思/.test(text) ? {
      key: 'author_self_indulgence',
      label: '作者自嗨',
      evidence: '正文站在作者角度评价设定有趣，没有证明读者为什么追。',
      fix: '把作者判断改成读者能看见的冲突、反制、收益和期待。',
    } : null,
    /主要展示设定|没有明显回报|没有可感知回报|只是介绍设定/.test(text) ? {
      key: 'no_reader_payoff',
      label: '缺可感知回报',
      evidence: '正文直接承认本章只展示设定或没有明显回报。',
      fix: '补动作结果、角色反应、线索兑现和章尾期待。',
    } : null,
  ].filter(Boolean)
  if (!risks.length) return null
  return {
    key: 'target_reader_forbidden',
    label: '目标读者硬伤',
    text: '目标读者检查不得用空泛喜欢、作者自嗨或设定展示替代正文回报。',
    expected: '目标读者检查不得用空泛喜欢、作者自嗨或设定展示替代正文回报。',
    score: Math.max(0, 100 - risks.length * 28),
    evidence: risks.map((item: any) => compactBriefText(item.evidence || item.fix || item.label)).filter(Boolean).slice(0, 8),
    delivered: false,
    status: 'warn',
    missed_items: risks.map((item: any) => compactBriefText(item.label || item.key)).filter(Boolean).slice(0, 8),
    issue: `正文触发 ${risks.length} 项目标读者确定性风险。`,
    repair_instruction: '按 oh-story 自嗨判定法修复：写清给谁看、读者想看什么、本章给了什么可感知回报。',
  }
}

function targetReaderPriority(missed: any[]) {
  if (missed.some(item => item.key === 'target_reader_forbidden')) return '优先清目标读者硬伤'
  if (missed.some(item => item.key === 'emotional_gap_analysis')) return '优先补情绪缺口'
  if (missed.some(item => item.key === 'reader_desires')) return '优先补读者欲望'
  if (missed.some(item => item.key === 'chapter_attractions')) return '优先补本章吸引点'
  if (missed.some(item => item.key === 'validation_questions')) return '优先补目标读者三问'
  if (missed.some(item => item.key === 'reader_profile')) return '优先补读者画像'
  if (missed.some(item => item.key === 'correction_methods')) return '优先落修正方法'
  return ''
}

export function buildTargetReaderSyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const contract = targetReaderContractForSync(project, contextPackage, chapter)
  const checks = [
    normalizeTargetReaderProfileCheck(contract.reader_profile || contract.readerProfile, chapterText),
    normalizeTargetReaderDesireCheck(contract.reader_desires || contract.readerDesires || contract.desires, chapterText),
    normalizeTargetReaderEmotionalGapCheck(contract.emotional_gap_analysis || contract.emotionalGapAnalysis, chapterText),
    normalizeTargetReaderAttractionCheck(contract.chapter_attractions || contract.chapterAttractions || contract.attractions, chapterText),
    normalizeTargetReaderValidationCheck(contract.validation_questions || contract.validationQuestions, chapterText),
    normalizeTargetReaderCorrectionMethodCheck(contract.correction_methods || contract.correctionMethods, chapterText),
    buildTargetReaderDeterministicCheck(chapterText),
  ].filter(Boolean)
  const delivered = checks.filter((item: any) => item.delivered)
  const missed = checks.filter((item: any) => !item.delivered)
  const missedCount = missed.length
  const score = Math.max(0, Math.min(100, Math.round(
    checks.length ? checks.reduce((sum: number, item: any) => sum + Number(item.score || 0), 0) / checks.length : 82,
  )))
  const status = missedCount > 0 || score < 78 ? 'warn' : 'ok'
  const priorityRepair = targetReaderPriority(missed)

  return {
    report_id: `target-reader-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: checks.length === 0 ? '目标读者未配置' : status === 'ok' ? '目标读者 OK' : `目标读者缺口 ${missedCount}`,
    summary: checks.length === 0
      ? '本章没有配置 target_reader_contract，建议补充读者画像、读者欲望、本章吸引点、三问验证和修正方法。'
      : status === 'ok'
        ? '正文已基本兑现目标读者画像、读者欲望、情绪缺口、本章吸引点、三问验证和修正方法。'
        : `正文有 ${missedCount} 项目标读者缺口，${priorityRepair || '优先补目标读者三问和可感知回报'}。`,
    missed_count: missedCount,
    priority_repair: priorityRepair,
    quality_checks: asArray(contract.quality_checks || contract.qualityChecks).map((item: any) => compactBriefText(item)).filter(Boolean).slice(0, 8),
    planned: checks,
    delivered,
    missed,
    next_actions: status === 'ok'
      ? ['保持目标读者兑现：写给谁、想看什么、本章回报和章尾期待都要有正文证据。']
      : [
          '下一章必须补目标读者：先写清本章给谁看、目标读者想看什么，再把卖点写成现场行动。',
          '补情绪缺口：从核心痛苦、深层情结、高频情绪关键词和未满足需求里挑一项，写成角色当下压力和读者可见回报。',
          '把规则反制、信息差、不公平移除或升级反馈落成可感知回报，避免只说读者会喜欢或只展示设定。',
        ],
  }
}

function genrePositioningContractForSync(project: any, contextPackage: any, chapter: any = {}) {
  return buildGenrePositioningContract(project, contextWithChapterRawPreDraftForSync(contextPackage, chapter))
}

function genrePositioningArray(values: any) {
  return asArray(values).map((item: any) => compactBriefText(item)).filter(Boolean)
}

function countGenrePositioningSignals(chapterText: string, patterns: RegExp[]) {
  const text = String(chapterText || '')
  return patterns.reduce((count, pattern) => count + (pattern.test(text) ? 1 : 0), 0)
}

function normalizeGenreLabelCheck(value: any, chapterText: string) {
  const expected = compactBriefText(value)
  if (!expected) return null
  const match = anchorMatchScore(expected, chapterText)
  const text = String(chapterText || '')
  const labelSignals = countGenrePositioningSignals(text, [
    /都市|现代|职场|生活/,
    /系统|面板/,
    /逆袭|翻盘|反打|低谷/,
    /长篇|连载|追更/,
  ])
  const drift = /古风权谋|修仙秘境|玄幻宗门/.test(text) && /都市|系统|逆袭/.test(expected)
  const delivered = !drift && (match.score >= 36 || labelSignals >= 2)
  return {
    key: 'genre_label',
    label: '题材标签',
    text: expected,
    expected,
    score: delivered ? Math.max(84, match.score) : Math.min(match.score, drift ? 14 : 52),
    evidence: uniqueBriefStrings([
      ...match.matched,
      labelSignals >= 2 ? '题材标签代理信号可见' : '',
      drift ? '题材漂移到其他类型' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : ['题材标签没有在正文场景中兑现'],
    issue: delivered ? '' : '题材标签没有落成正文场景，或从都市系统逆袭漂移到其他类型。',
    repair_instruction: delivered ? '' : '补题材标签：把正文拉回既定题材，让类型标签在场景、能力、冲突和回报里可见。',
  }
}

