function normalizeGenreLongboardFocusCheck(values: any[], chapterText: string) {
  const planned = genrePositioningArray(values)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const scored = planned.map(item => ({ text: item, match: anchorMatchScore(item, chapterText) }))
  const longboardSignals = countGenrePositioningSignals(text, [
    /拉长(?:题材)?长板|拉长板|题材长板/,
    /核心卖点|目标情绪|最高频爽点/,
    /三个角度|3\s*个角度|中年危机翻盘|系统评价吐槽|新手奖励立刻见效/,
    /没有为补短板|不为补短板|不补短板|不稀释核心卖点/,
  ])
  const noDilutionGuard = /没有为补短板|不为补短板|不补短板|不新增[^。！？!?\n]{0,18}支线|不得[^。！？!?\n]{0,18}支线/.test(text)
  const dilutionRisk = !noDilutionGuard && /为了补[^。！？!?\n]{0,18}短板|新增[^。！？!?\n]{0,18}支线|稀释核心卖点|冲淡了核心卖点/.test(text)
  const deliveredItems = scored.filter(item => item.match.score >= 30).length
  const delivered = !dilutionRisk && (deliveredItems >= 1 || longboardSignals >= 2)
  return {
    key: 'longboard_focus_rules',
    label: '长板聚焦',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? Math.max(84, Math.round((deliveredItems / Math.max(1, planned.length)) * 100), longboardSignals * 22) : Math.min(Math.max(18, longboardSignals * 18), dilutionRisk ? 24 : 64),
    evidence: uniqueBriefStrings([
      ...scored.flatMap(item => item.match.matched),
      longboardSignals >= 2 ? '题材长板与核心卖点强化信号可见' : '',
      dilutionRisk ? '存在补短板支线稀释核心卖点风险' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : planned.filter(item => anchorMatchScore(item, chapterText).score < 30).slice(0, 8),
    issue: delivered ? '' : '正文没有优先拉题材长板，或为补短板新增支线导致核心卖点被稀释。',
    repair_instruction: delivered ? '' : '补长板聚焦：拉长题材长板和核心卖点，确认同一卖点至少 3 个展开角度，删除稀释核心卖点的补短板支线。',
  }
}

function buildGenrePositioningDeterministicCheck(chapterText: string) {
  const text = String(chapterText || '')
  const risks = [
    /古风权谋|修仙秘境|玄幻宗门/.test(text) && /都市系统|维修订单|设备维修|旧城设备师/.test(text) === false ? {
      key: 'genre_drift',
      label: '题材漂移',
      evidence: '正文出现古风权谋/修仙秘境等类型信号，偏离都市系统逆袭承诺。',
      fix: '把场景拉回现代生活、职业订单、系统反馈和现实收益。',
    } : null,
    /没有系统面板|没有维修订单/.test(text) ? {
      key: 'missing_core_promise',
      label: '核心承诺缺失',
      evidence: '正文直接承认没有系统面板或维修订单。',
      fix: '补系统面板、维修订单和现实任务反馈。',
    } : null,
    /血脉神通|天赋神通|秘境传承/.test(text) && /维修职业|设备订单|设备维修/.test(text) === false ? {
      key: 'detached_goldfinger',
      label: '金手指脱题',
      evidence: '金手指变成血脉/秘境能力，脱离主角职业和现实任务。',
      fix: '让能力重新贴回维修职业、设备订单和生活困境。',
    } : null,
    /主要展示宏大世界观|暂时没有现实回报|没有现实回报/.test(text) ? {
      key: 'no_real_world_payoff',
      label: '缺现实回报',
      evidence: '正文停在宏大设定展示，没有给现实收益或订单回报。',
      fix: '补订单结果、客户反应、收入/授权/能力变化和下一门槛。',
    } : null,
    /挂羊头卖狗肉/.test(text) ? {
      key: 'promise_mismatch',
      label: '挂羊头卖狗肉',
      evidence: '正文显式出现题材承诺错位。',
      fix: '统一书名、简介、题材标签和正文桥段。',
    } : null,
  ].filter(Boolean)
  if (!risks.length) return null
  return {
    key: 'genre_positioning_forbidden',
    label: '题材定位硬伤',
    text: '题材定位不得漂移、脱离核心机制、脱离主角职业或挂羊头卖狗肉。',
    expected: '题材定位不得漂移、脱离核心机制、脱离主角职业或挂羊头卖狗肉。',
    score: Math.max(0, 100 - risks.length * 24),
    evidence: risks.map((item: any) => compactBriefText(item.evidence || item.fix || item.label)).filter(Boolean).slice(0, 8),
    delivered: false,
    status: 'warn',
    missed_items: risks.map((item: any) => compactBriefText(item.label || item.key)).filter(Boolean).slice(0, 8),
    issue: `正文触发 ${risks.length} 项题材定位确定性风险。`,
    repair_instruction: '按 oh-story 题材定位修复：统一题材标签、核心梗、金手指、必备场景和平台口味，避免挂羊头卖狗肉。',
  }
}

function genrePositioningPriority(missed: any[]) {
  if (missed.some(item => item.key === 'genre_positioning_forbidden')) return '优先清题材硬伤'
  if (missed.some(item => item.key === 'longboard_focus_rules')) return '优先拉题材长板'
  if (missed.some(item => item.key === 'core_hook_rules')) return '优先补核心梗'
  if (missed.some(item => item.key === 'goldfinger_fit_rules')) return '优先补金手指贴合'
  if (missed.some(item => item.key === 'genre_label')) return '优先校题材标签'
  if (missed.some(item => item.key === 'genre_formula')) return '优先补类型公式'
  if (missed.some(item => item.key === 'must_have_scenes')) return '优先补必备场景'
  if (missed.some(item => item.key === 'platform_fit_rules')) return '优先补平台适配'
  if (missed.some(item => item.key === 'micro_innovation_rules')) return '优先收束微创新'
  if (missed.some(item => item.key === 'reader_psychology')) return '优先补读者心理'
  return ''
}

export function buildGenrePositioningSyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const contract = genrePositioningContractForSync(project, contextPackage, chapter)
  const checks = [
    normalizeGenreLabelCheck(contract.genre_label || contract.genreLabel, chapterText),
    normalizeGenrePsychologyCheck(contract.reader_psychology || contract.readerPsychology, chapterText),
    normalizeGenreFormulaCheck(contract.genre_formula || contract.genreFormula, chapterText),
    normalizeGenreCoreHookCheck(contract.core_hook_rules || contract.coreHookRules, chapterText),
    normalizeGoldfingerFitCheck(contract.goldfinger_fit_rules || contract.goldfingerFitRules, chapterText),
    normalizeMustHaveSceneCheck(contract.must_have_scenes || contract.mustHaveScenes, chapterText),
    normalizePlatformFitCheck(contract.platform_fit_rules || contract.platformFitRules, chapterText),
    normalizeMicroInnovationCheck(contract.micro_innovation_rules || contract.microInnovationRules, chapterText),
    normalizeGenreLongboardFocusCheck(contract.longboard_focus_rules || contract.longboardFocusRules, chapterText),
    buildGenrePositioningDeterministicCheck(chapterText),
  ].filter(Boolean)
  const delivered = checks.filter((item: any) => item.delivered)
  const missed = checks.filter((item: any) => !item.delivered)
  const missedCount = missed.length
  const score = Math.max(0, Math.min(100, Math.round(
    checks.length ? checks.reduce((sum: number, item: any) => sum + Number(item.score || 0), 0) / checks.length : 82,
  )))
  const status = missedCount > 0 || score < 78 ? 'warn' : 'ok'
  const priorityRepair = genrePositioningPriority(missed)

  return {
    report_id: `genre-positioning-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: checks.length === 0 ? '题材定位未配置' : status === 'ok' ? '题材定位 OK' : `题材定位缺口 ${missedCount}`,
    summary: checks.length === 0
      ? '本章没有配置 genre_positioning_contract，建议补充题材标签、读者心理、类型公式、核心梗、金手指贴合、必备场景、平台适配、微创新边界和题材长板。'
      : status === 'ok'
        ? '正文已基本兑现题材标签、读者心理、类型公式、核心梗、金手指贴合、必备场景、平台适配、微创新边界和题材长板。'
        : `正文有 ${missedCount} 项题材定位缺口，${priorityRepair || '优先统一题材承诺和正文桥段'}。`,
    missed_count: missedCount,
    priority_repair: priorityRepair,
    quality_checks: asArray(contract.quality_checks || contract.qualityChecks).map((item: any) => compactBriefText(item)).filter(Boolean).slice(0, 8),
    planned: checks,
    delivered,
    missed,
    next_actions: status === 'ok'
      ? ['保持题材定位：题材标签、核心梗、金手指、必备场景、题材长板和平台回报必须持续同一承诺。']
      : [
          '下一章必须补题材定位：先统一题材标签、核心梗和金手指贴合，再把必备场景写成正文桥段。',
          '拉题材长板：优先强化核心卖点、目标情绪和最高频爽点，删除会稀释核心卖点的补短板支线。',
          '避免挂羊头卖狗肉：书名简介承诺什么，正文就必须用场景、能力、订单结果和平台回报兑现什么。',
      ],
  }
}

function femaleAudienceContractForSync(project: any, contextPackage: any, chapter: any = {}) {
  return buildFemaleAudienceContract(project, contextWithChapterRawPreDraftForSync(contextPackage, chapter))
}

function femaleAudienceArray(values: any) {
  return asArray(values).map((item: any) => compactBriefText(item)).filter(Boolean)
}

function countFemaleAudienceSignals(chapterText: string, patterns: RegExp[]) {
  const text = String(chapterText || '')
  return patterns.reduce((count, pattern) => count + (pattern.test(text) ? 1 : 0), 0)
}

function normalizeFemaleCorePrinciplesCheck(values: any[], chapterText: string) {
  const planned = femaleAudienceArray(values)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const scored = planned.map(item => ({ text: item, match: anchorMatchScore(item, chapterText) }))
  const signalCount = countFemaleAudienceSignals(text, [
    /安全感|退路|能力|同盟|边界/,
    /代入|被轻视|处境|选择|反应/,
    /女主.*自己|亲自|主动|自己做决定|自己推进/,
    /主情绪|委屈|反击|成长|事业/,
  ])
  const hardPassive = /女主被安排着赢|关键选择都由男主安排|男主.*解决所有/.test(text)
  const deliveredItems = scored.filter(item => item.match.score >= 28).length
  const delivered = !hardPassive && (deliveredItems >= Math.max(1, Math.ceil(planned.length * 0.35)) || signalCount >= 3)
  return {
    key: 'core_principles',
    label: '核心原则',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? Math.max(84, Math.round((deliveredItems / Math.max(1, planned.length)) * 100)) : Math.min(Math.max(14, signalCount * 16), hardPassive ? 22 : 64),
    evidence: uniqueBriefStrings([
      ...scored.flatMap(item => item.match.matched),
      signalCount >= 3 ? '安全感/代入/主动性/主情绪信号可见' : '',
      hardPassive ? '女主主动性断裂' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : planned.filter(item => anchorMatchScore(item, chapterText).score < 28).slice(0, 8),
    issue: delivered ? '' : '女频核心原则没有落地：安全感、代入感、女主主动性或主情绪断裂。',
    repair_instruction: delivered ? '' : '补核心原则：给女主退路/能力/同盟锚点，让关键选择由女主自己做决定、自己推进。',
  }
}

