function buildFemaleAudienceDeterministicCheck(chapterText: string) {
  const text = String(chapterText || '')
  const risks = [
    /一直被虐|没有退路|没有安全感/.test(text) ? {
      key: 'safety_break',
      label: '安全感断裂',
      evidence: '正文让女主持续被虐，缺少退路、能力、同盟或安全感。',
      fix: '补退路、能力、同盟或边界，让安全感早给。',
    } : null,
    /关键选择都由男主安排|女主被安排着赢|男主.*解决所有/.test(text) ? {
      key: 'passive_heroine',
      label: '女主被安排着赢',
      evidence: '关键选择或胜利由男主安排，女主主动性断裂。',
      fix: '改成女主自己做决定、自己推进、自己承担后果并拿到结果。',
    } : null,
    /感情线脱离成长线|男主出面解决所有事业问题/.test(text) ? {
      key: 'romance_detached',
      label: '感情线脱离成长线',
      evidence: '感情线替代事业/成长线，没有踩在女主成长节点上。',
      fix: '让感情升温发生在女主完成事业进展或成长选择之后。',
    } : null,
    (/没有连续只虐|不连续只虐|避免连续只虐/.test(text) ? false : /连续只虐/.test(text)) || /没有反转或糖/.test(text) ? {
      key: 'abuse_overdose',
      label: '连续只虐',
      evidence: '正文连续只虐，没有反转、糖或安全感回补。',
      fix: '每段虐后立刻给反转、糖、退路或阶段性胜利。',
    } : null,
    /书名简介说.*正文却|货不对板/.test(text) ? {
      key: 'promise_mismatch',
      label: '货板不一致',
      evidence: '书名简介承诺与正文交付错位。',
      fix: '统一书名、简介、卖点和正文交付。',
    } : null,
  ].filter(Boolean)
  if (!risks.length) return null
  return {
    key: 'female_audience_forbidden',
    label: '女频长篇硬伤',
    text: '女频长篇不得安全感断裂、女主被安排着赢、感情线脱离成长线、连续只虐或货板不一致。',
    expected: '女频长篇不得安全感断裂、女主被安排着赢、感情线脱离成长线、连续只虐或货板不一致。',
    score: Math.max(0, 100 - risks.length * 24),
    evidence: risks.map((item: any) => compactBriefText(item.evidence || item.fix || item.label)).filter(Boolean).slice(0, 8),
    delivered: false,
    status: 'warn',
    missed_items: risks.map((item: any) => compactBriefText(item.label || item.key)).filter(Boolean).slice(0, 8),
    issue: `正文触发 ${risks.length} 项女频长篇确定性风险。`,
    repair_instruction: '按 oh-story 女频长篇口径修复：补安全感、女主主动选择、成长节点上的感情升级、虐后反转或糖，并修货板一致。',
  }
}

function femaleAudiencePriority(missed: any[]) {
  if (missed.some(item => item.key === 'female_audience_forbidden')) return '优先清女频硬伤'
  if (missed.some(item => item.key === 'core_principles')) return '优先补安全感和女主主动'
  if (missed.some(item => item.key === 'abuse_dosage_rules')) return '优先控虐戏剂量'
  if (missed.some(item => item.key === 'romance_axis_rules')) return '优先修感情线双轴'
  if (missed.some(item => item.key === 'copy_promise_rules')) return '优先补文案承诺'
  if (missed.some(item => item.key === 'reader_need_rules')) return '优先补深层需求'
  if (missed.some(item => item.key === 'platform_fit_rules')) return '优先补平台适配'
  if (missed.some(item => item.key === 'quality_checks')) return '优先修货板一致'
  if (missed.some(item => item.key === 'longform_genre_rules')) return '优先补长篇承接'
  return ''
}

export function buildFemaleAudienceSyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const contract = femaleAudienceContractForSync(project, contextPackage, chapter)
  const checks = contract ? [
    normalizeFemaleCorePrinciplesCheck(contract.core_principles || contract.corePrinciples, chapterText),
    normalizeFemaleReaderNeedCheck(contract.reader_need_rules || contract.readerNeedRules, chapterText),
    normalizeFemaleCopyPromiseCheck(contract.copy_promise_rules || contract.copyPromiseRules, chapterText),
    normalizeFemaleLongformGenreCheck(contract.longform_genre_rules || contract.longformGenreRules, chapterText),
    normalizeFemaleRomanceAxisCheck(contract.romance_axis_rules || contract.romanceAxisRules, chapterText),
    normalizeFemaleAbuseDosageCheck(contract.abuse_dosage_rules || contract.abuseDosageRules, chapterText),
    normalizeFemalePlatformFitCheck(contract.platform_fit_rules || contract.platformFitRules, chapterText),
    normalizeFemaleQualityCheck(contract.quality_checks || contract.qualityChecks, chapterText),
    buildFemaleAudienceDeterministicCheck(chapterText),
  ].filter(Boolean) : []
  const delivered = checks.filter((item: any) => item.delivered)
  const missed = checks.filter((item: any) => !item.delivered)
  const missedCount = missed.length
  const score = Math.max(0, Math.min(100, Math.round(
    checks.length ? checks.reduce((sum: number, item: any) => sum + Number(item.score || 0), 0) / checks.length : 82,
  )))
  const status = missedCount > 0 || score < 78 ? 'warn' : 'ok'
  const priorityRepair = femaleAudiencePriority(missed)

  return {
    report_id: `female-audience-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: checks.length === 0 ? '女频长篇未配置' : status === 'ok' ? '女频长篇 OK' : `女频长篇缺口 ${missedCount}`,
    summary: checks.length === 0
      ? '本章没有配置 female_audience_contract；只有女性向项目才需要该同步报告。'
      : status === 'ok'
        ? '正文已基本兑现安全感、代入感、女主主动性、深层需求、文案承诺、感情线双轴、虐戏剂量和平台适配。'
        : `正文有 ${missedCount} 项女频长篇缺口，${priorityRepair || '优先补安全感、女主主动性和虐后回补'}。`,
    missed_count: missedCount,
    priority_repair: priorityRepair,
    quality_checks: asArray(contract?.quality_checks || contract?.qualityChecks).map((item: any) => compactBriefText(item)).filter(Boolean).slice(0, 8),
    planned: checks,
    delivered,
    missed,
    next_actions: status === 'ok'
      ? ['保持女频长篇兑现：安全感、女主主动选择、成长节点上的感情升级和虐后回补都要可见。']
      : [
          '下一章必须补女频长篇：先补安全感锚点，再让女主亲自做决定、亲自推进、亲自承担结果。',
          '受委屈后必须立刻给反转、糖、退路或阶段胜利；感情升级要踩在女主事业/成长节点上。',
      ],
  }
}

function plotDynamicsContractForSync(contextPackage: any, chapter: any = {}) {
  return buildPlotDynamicsContract(contextWithChapterRawPreDraftForSync(contextPackage, chapter))
}

function plotDynamicsArray(values: any) {
  return asArray(values).map((item: any) => compactBriefText(item)).filter(Boolean)
}

function countPlotDynamicsSignals(chapterText: string, patterns: RegExp[]) {
  const text = String(chapterText || '')
  return patterns.reduce((count, pattern) => count + (pattern.test(text) ? 1 : 0), 0)
}

function normalizePlotLoopCheck(values: any[], chapterText: string) {
  const planned = plotDynamicsArray(values)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const scored = planned.map(item => ({ text: item, match: anchorMatchScore(item, chapterText) }))
  const loopSignals = countPlotDynamicsSignals(text, [
    /目标.*明确|目标很明确|必须.*找到|必须.*完成/,
    /阻碍|封锁|冻结|压上来|挡住/,
    /行动|拆开|核验|追查|没有等/,
    /代价\/反馈|代价|反馈|暴露|信任提高|追责升级/,
    /新期待|章末|指向|留下/,
  ])
  const flat = /没有明确目标|没有真正阻碍|一路顺利解决|没有代价反馈|没有新期待|事情自然结束/.test(text)
  const deliveredItems = scored.filter(item => item.match.score >= 30).length
  const delivered = !flat && (deliveredItems >= Math.max(2, Math.ceil(planned.length * 0.45)) || loopSignals >= 4)
  return {
    key: 'plot_loop',
    label: '剧情闭环',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? Math.max(84, Math.round((deliveredItems / Math.max(1, planned.length)) * 100)) : Math.min(Math.max(14, loopSignals * 16), flat ? 22 : 66),
    evidence: uniqueBriefStrings([
      ...scored.flatMap(item => item.match.matched),
      loopSignals >= 4 ? '目标-阻碍-行动-代价/反馈-新期待信号可见' : '',
      flat ? '剧情闭环显式缺失' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : planned.filter(item => anchorMatchScore(item, chapterText).score < 30).slice(0, 8),
    issue: delivered ? '' : '目标、阻碍、行动、代价/反馈、新期待没有形成剧情闭环。',
    repair_instruction: delivered ? '' : '补剧情闭环：先立目标，再压阻碍，让主角行动产生代价/反馈，并在章末留下新期待。',
  }
}

function normalizeClimaxFormulaCheck(values: any[], chapterText: string) {
  const planned = plotDynamicsArray(values)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const missingFormula = /没有假胜|没有.*崩解|没有.*交叉死磕|高潮没有/.test(text)
  const formulaSignals = countPlotDynamicsSignals(text, [
    /蓄能|倒计时|压低|蓄压/,
    /假胜|先显示|先.*恢复|小胜/,
    /崩解|下一秒|反向|烧红/,
    /交叉死磕|一边.*一边|死磕/,
    /悬置收尾|没有关门|留下新期待|章末/,
  ])
  const scored = planned.map(item => ({ text: item, match: anchorMatchScore(item, chapterText) }))
  const deliveredItems = scored.filter(item => item.match.score >= 32).length
  const delivered = !missingFormula && (deliveredItems >= Math.max(2, Math.ceil(planned.length * 0.45)) || formulaSignals >= 4)
  return {
    key: 'climax_formula',
    label: '高潮公式',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? Math.max(84, Math.round((deliveredItems / Math.max(1, planned.length)) * 100)) : Math.min(Math.max(12, formulaSignals * 16), missingFormula ? 18 : 64),
    evidence: uniqueBriefStrings([
      ...scored.flatMap(item => item.match.matched),
      formulaSignals >= 4 ? '高潮公式链路可见' : '',
      missingFormula ? '高潮公式显式缺失' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : planned.filter(item => anchorMatchScore(item, chapterText).score < 32).slice(0, 8),
    issue: delivered ? '' : '高潮缺少蓄能、假胜、崩解、交叉死磕或悬置收尾的情绪落差。',
    repair_instruction: delivered ? '' : '补高潮公式：蓄能后给假胜，再崩解，把主角推入交叉死磕，最后悬置收尾。',
  }
}

function normalizePlotAbOutlineCheck(values: any[], chapterText: string) {
  const planned = plotDynamicsArray(values)
  if (!planned.length) return null
  const scored = planned.map(item => ({ text: item, match: anchorMatchScore(item, chapterText) }))
  const signalCount = countPlotDynamicsSignals(chapterText, [
    /A\s*蓄压|A\s*蓄能|蓄压/,
    /B\s*抬情绪|B\s*抬|小反转|抬情绪/,
    /交替|交错/,
    /阻碍.*反转|压.*回报/,
  ])
  const deliveredItems = scored.filter(item => item.match.score >= 30).length
  const delivered = deliveredItems >= 1 || signalCount >= 2
  return {
    key: 'ab_outline',
    label: 'A/B节奏',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? Math.max(84, Math.round((deliveredItems / Math.max(1, planned.length)) * 100)) : Math.max(18, signalCount * 18),
    evidence: uniqueBriefStrings([
      ...scored.flatMap(item => item.match.matched),
      signalCount >= 2 ? 'A/B蓄压抬情绪信号可见' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : planned.filter(item => anchorMatchScore(item, chapterText).score < 30).slice(0, 8),
    issue: delivered ? '' : 'A/B蓄压和抬情绪没有形成交替，剧情容易变成均匀流水账。',
    repair_instruction: delivered ? '' : '补A/B节奏：一段蓄压提高阻碍，一段抬情绪给小反转或阶段回报。',
  }
}

function normalizePlotScenePurposeCheck(values: any[], chapterText: string) {
  const planned = plotDynamicsArray(values)
  if (!planned.length) return null
  const scored = planned.map(item => ({ text: item, match: anchorMatchScore(item, chapterText) }))
  const signalCount = countPlotDynamicsSignals(chapterText, [
    /场景|红色阀门|账本线索|账本编号/,
    /暴露|指向|留下/,
    /功能|推进|交付/,
  ])
  const deliveredItems = scored.filter(item => item.match.score >= 30).length
  const delivered = deliveredItems >= 1 || signalCount >= 2
  return {
    key: 'scene_purpose_map',
    label: '场景功能',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? Math.max(84, Math.round((deliveredItems / Math.max(1, planned.length)) * 100)) : Math.max(18, signalCount * 18),
    evidence: uniqueBriefStrings([
      ...scored.flatMap(item => item.match.matched),
      signalCount >= 2 ? '场景功能/信息交付可见' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : planned.filter(item => anchorMatchScore(item, chapterText).score < 30).slice(0, 8),
    issue: delivered ? '' : '场景没有交付明确功能、信息变化或读者回报。',
    repair_instruction: delivered ? '' : '补场景功能：每个场景都要写清它推进了什么、暴露了什么、改变了什么。',
  }
}

function normalizePlotDriveModeRulesCheck(values: any[], chapterText: string) {
  const planned = plotDynamicsArray(values)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const explicitMixedMode = /混合模式|主线用事件|每\s*3-5\s*章|情感停顿/.test(text)
  const explicitEmotionMode = !explicitMixedMode && /追妻|虐心|世情|情感驱动|人物驱动/.test(text)
  const explicitEventMode = !explicitMixedMode && !explicitEmotionMode && (/番茄|爽文|打脸|事件驱动/.test(text) || planned.some(item => /番茄|爽文|打脸|事件驱动/.test(item)))
  const negatedOutcome = /没有赢|没有升级|没有对手栽|没有任何外部结果|只有内心独白|坐着闲谈/.test(text)
  const eventOutcome = !negatedOutcome && /外部结果|赢下|赢了|阶段胜利|升级|解锁|对手栽|栽了一回|当众失败|资格到手|拿到|客户信任提高|处置权|反制成功/.test(text)
  const emotionalHook = /人物心结|后悔了没|原谅了没|心结|关系裂缝|独处|回忆|试探|误会|亏欠|情感停顿/.test(text)
  const eventDelivered = !explicitEventMode || eventOutcome
  const emotionDelivered = !explicitEmotionMode || emotionalHook
  const mixedDelivered = !explicitMixedMode || (eventOutcome && emotionalHook)
  const delivered = eventDelivered && emotionDelivered && mixedDelivered
  return {
    key: 'drive_mode_rules',
    label: '驱动方式',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 88 : Math.max(12, [eventDelivered, emotionDelivered, mixedDelivered].filter(Boolean).length * 28),
    evidence: [
      explicitEventMode ? '事件驱动/番茄爽文规则' : '',
      eventOutcome ? '外部结果可见' : '',
      explicitEmotionMode || explicitMixedMode ? '情感/混合驱动规则' : '',
      emotionalHook ? '人物心结或情感停顿可见' : '',
      negatedOutcome ? '缺外部结果或只有闲谈内心' : '',
    ].filter(Boolean),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      !eventDelivered ? '番茄爽文/打脸文每章必须给外部结果：赢了、升级了、对手栽了至少一项' : '',
      !emotionDelivered ? '情感驱动必须保留人物心结，不能只闲谈或内心独白' : '',
      !mixedDelivered ? '混合模式必须主线事件推进，并用情感停顿透出人物心结' : '',
    ], 8),
    issue: delivered ? '' : '驱动方式与题材不匹配：事件驱动章节缺外部结果，或情感/混合章节缺人物心结。',
    repair_instruction: delivered ? '' : '按 oh-story 驱动方式修复：番茄爽文/打脸文补一个外部结果（赢、升级、对手栽）；追妻/虐心/世情保留人物心结；混合模式主线用事件往前推，每 3-5 章插情感停顿。',
  }
}

function normalizeLineStaggerRulesCheck(values: any[], chapterText: string) {
  const planned = plotDynamicsArray(values)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const scored = planned.map(item => ({ text: item, match: anchorMatchScore(item, chapterText) }))
  const deliveredItems = scored.filter(item => item.match.score >= 28).length
  const lineTypes = [
    /主线|核心线|主任务/.test(text) ? '主线' : '',
    /支线|副线|侧线/.test(text) ? '支线' : '',
    /战力|升级|实力|能力/.test(text) ? '战力提升线' : '',
    /装备|道具|工具箱|技能|收获/.test(text) ? '装备收获线' : '',
    /情感|关系|女性角色|感情线/.test(text) ? '情感线' : '',
    /声望|客户信任|旁观者|认可|名声/.test(text) ? '声望线' : '',
  ].filter(Boolean)
  const staggerSignals = [
    /多线错峰|错峰推进|错开节奏|不同步推进|线.*错开/.test(text) ? '多线错峰' : '',
    /没有同时爆|没有同时空转|避免同质化|保留.*燃料|待推进/.test(text) ? '非同时爆/非同时空转' : '',
    lineTypes.length >= 2 ? `${lineTypes.slice(0, 4).join('、')}可见` : '',
  ].filter(Boolean)
  const flatText = text
    .replace(/没有同时(?:爆|爆完|爆发|空转)/g, '')
    .replace(/不能同时(?:爆|爆完|爆发|空转)/g, '')
  const flat = /(?:主线|支线|情感线|声望线|战力线|装备线)[^。！？!?]{0,36}(?:同时|一起)(?:爆完|爆掉|爆发|空转)|(?:同时|一起)(?:爆完|爆掉|爆发|空转)|全部空转/.test(flatText)
  const delivered = !flat && (deliveredItems >= 1 || staggerSignals.length >= 2)
  return {
    key: 'line_stagger_rules',
    label: '多线错峰',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? Math.max(84, Math.round((deliveredItems / Math.max(1, planned.length)) * 100)) : Math.max(18, staggerSignals.length * 20),
    evidence: uniqueBriefStrings([
      ...scored.flatMap(item => item.match.matched),
      ...staggerSignals,
      flat ? '多线同时爆或同时空转' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : planned.filter(item => anchorMatchScore(item, chapterText).score < 28).slice(0, 8),
    issue: delivered ? '' : '主线和支线没有错开节奏推进，容易同时爆完或一起空转。',
    repair_instruction: delivered ? '' : '按 oh-story 多线穿插节奏修复：主线、支线、战力提升线、装备收获线、情感线、声望线要错峰推进；本章至少推进一条线，保留另一条线做下一段燃料，避免同时爆完或同时空转。',
  }
}

function buildPlotDynamicsDeterministicCheck(chapterText: string) {
  const text = String(chapterText || '')
  const risks = [
    /没有明确目标/.test(text) ? {
      key: 'no_goal',
      label: '缺目标',
      evidence: '正文直接承认没有明确目标。',
      fix: '补本章可见目标，并让目标约束主角行动。',
    } : null,
    /没有真正阻碍|一路顺利解决/.test(text) ? {
      key: 'no_obstacle',
      label: '缺阻碍',
      evidence: '正文缺少真正阻碍，主角一路顺利解决。',
      fix: '补外部阻碍、规则压制、资源限制或对手行动。',
    } : null,
    /没有代价反馈|事情自然结束/.test(text) ? {
      key: 'no_cost_feedback',
      label: '缺代价反馈',
      evidence: '行动后没有代价、信息反馈、关系变化或局势变化。',
      fix: '让行动带来代价、反馈或新的压力。',
    } : null,
    /没有新期待|事情到这里结束/.test(text) ? {
      key: 'no_next_expectation',
      label: '缺新期待',
      evidence: '章末没有新期待，事情直接关闭。',
      fix: '章末留下新问题、新线索、新危机或下一目标。',
    } : null,
    /高潮没有|没有假胜|没有.*崩解|没有.*交叉死磕/.test(text) ? {
      key: 'flat_climax',
      label: '高潮平滑',
      evidence: '高潮缺少假胜、崩解和交叉死磕。',
      fix: '按蓄能、假胜、崩解、交叉死磕、悬置收尾重构高潮。',
    } : null,
  ].filter(Boolean)
  if (!risks.length) return null
  return {
    key: 'plot_dynamics_forbidden',
    label: '剧情动力硬伤',
    text: '剧情动力不得缺目标、缺阻碍、缺代价反馈、缺新期待或高潮平滑结束。',
    expected: '剧情动力不得缺目标、缺阻碍、缺代价反馈、缺新期待或高潮平滑结束。',
    score: Math.max(0, 100 - risks.length * 22),
    evidence: risks.map((item: any) => compactBriefText(item.evidence || item.fix || item.label)).filter(Boolean).slice(0, 8),
    delivered: false,
    status: 'warn',
    missed_items: risks.map((item: any) => compactBriefText(item.label || item.key)).filter(Boolean).slice(0, 8),
    issue: `正文触发 ${risks.length} 项剧情动力确定性风险。`,
    repair_instruction: '按 oh-story 剧情动力法修复：补目标、阻碍、行动、代价/反馈、新期待，并重构高潮情绪落差。',
  }
}

function plotDynamicsPriority(missed: any[]) {
  if (missed.some(item => item.key === 'plot_dynamics_forbidden')) return '优先清剧情硬伤'
  if (missed.some(item => item.key === 'drive_mode_rules')) return '优先修驱动方式'
  if (missed.some(item => item.key === 'plot_loop')) return '优先补剧情闭环'
  if (missed.some(item => item.key === 'climax_formula')) return '优先补高潮公式'
  if (missed.some(item => item.key === 'line_stagger_rules')) return '优先补多线错峰'
  if (missed.some(item => item.key === 'ab_outline')) return '优先补A/B节奏'
  if (missed.some(item => item.key === 'scene_purpose_map')) return '优先补场景功能'
  return ''
}

export function buildPlotDynamicsSyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const contract = plotDynamicsContractForSync(contextPackage, chapter)
  const checks = [
    normalizePlotLoopCheck(contract.plot_loop || contract.plotLoop, chapterText),
    normalizeClimaxFormulaCheck(contract.climax_formula || contract.climaxFormula, chapterText),
    normalizePlotAbOutlineCheck(contract.ab_outline || contract.abOutline, chapterText),
    normalizePlotScenePurposeCheck(contract.scene_purpose_map || contract.scenePurposeMap, chapterText),
    normalizePlotDriveModeRulesCheck(contract.drive_mode_rules || contract.driveModeRules, chapterText),
    normalizeLineStaggerRulesCheck(contract.line_stagger_rules || contract.lineStaggerRules, chapterText),
    buildPlotDynamicsDeterministicCheck(chapterText),
  ].filter(Boolean)
  const delivered = checks.filter((item: any) => item.delivered)
  const missed = checks.filter((item: any) => !item.delivered)
  const missedCount = missed.length
  const score = Math.max(0, Math.min(100, Math.round(
    checks.length ? checks.reduce((sum: number, item: any) => sum + Number(item.score || 0), 0) / checks.length : 82,
  )))
  const status = missedCount > 0 || score < 78 ? 'warn' : 'ok'
  const priorityRepair = plotDynamicsPriority(missed)

  return {
    report_id: `plot-dynamics-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: checks.length === 0 ? '剧情动力未配置' : status === 'ok' ? '剧情动力 OK' : `剧情动力缺口 ${missedCount}`,
    summary: checks.length === 0
      ? '本章没有配置 plot_dynamics_contract，建议补充目标、阻碍、行动、代价/反馈、新期待、高潮公式、驱动方式和多线错峰。'
      : status === 'ok'
        ? '正文已基本兑现目标、阻碍、行动、代价/反馈、新期待、高潮公式、A/B节奏、场景功能、驱动方式和多线错峰。'
        : `正文有 ${missedCount} 项剧情动力缺口，${priorityRepair || '优先补剧情闭环和高潮落差'}。`,
    missed_count: missedCount,
    priority_repair: priorityRepair,
    quality_checks: asArray(contract.quality_checks || contract.qualityChecks).map((item: any) => compactBriefText(item)).filter(Boolean).slice(0, 8),
    planned: checks,
    delivered,
    missed,
    next_actions: status === 'ok'
      ? ['保持剧情动力：目标、阻碍、行动、代价/反馈、新期待、高潮情绪落差、题材匹配的驱动方式和主线/支线错峰推进都要可见。']
      : [
          '下一章必须补剧情动力：先立清目标和阻碍，再写主角行动、代价/反馈和新的章末期待，并让主线和支线错开节奏推进。',
          '按题材修驱动方式：番茄爽文/打脸文每章给一个外部结果（赢、升级、对手栽）；情感驱动保留人物心结；混合模式主线事件推进，每 3-5 章插情感停顿。',
          '高潮必须有蓄能、假胜、崩解、交叉死磕和悬置收尾，避免顺滑解决后直接结束。',
        ],
  }
}

function normalizeAttractionDimension(key: string, label: string, expected: any, chapterText: string, options: { tailOnly?: boolean; openingOnly?: boolean; threshold?: number } = {}) {
  const expectedText = compactText(expected, 240)
  const scopeText = options.openingOnly ? chapterText.slice(0, 900) : chapterText
  const match = anchorMatchScore(expectedText, scopeText, { tailOnly: options.tailOnly })
  const threshold = Number(options.threshold || 50)
  const status = !expectedText || match.score >= threshold ? 'ok' : 'warn'
  return {
    key,
    label,
    status,
    score: expectedText ? match.score : 82,
    expected: expectedText,
    evidence: match.matched,
    issue: status === 'ok' ? '' : `${label}未充分兑现：${expectedText}`,
    repair_instruction: status === 'ok' ? '' : attractionRepairInstruction(key),
  }
}

function attractionRepairInstruction(key: string) {
  if (key === 'opening_hook') return '重写或补写前300字，先给异常、危险、欲望或反常信息。'
  if (key === 'scene_drive') return '补齐场景目标、阻碍、转折、回报，把说明改成现场行动链。'
  if (key === 'payoff_density') return '补出可见反制结果、信息增量、能力展示或情绪回报。'
  if (key === 'page_turn') return '重做最后300字，留下下一章非看不可的危险、选择、反转或未解答案。'
  if (key === 'spread_scene') return '补成可视化传播场面，让读者能复述画面、机制反差或公开反转。'
  return '把缺口写成可见冲突、行动结果、信息增量或章末问题。'
}

function sceneDriveExpectation(contextPackage: any, chapter: any = {}) {
  const sceneCards = storyDriveSceneCards(contextPackage, chapter)
  const card = sceneCards.find((item: any) => compactText(
    item?.goal
    || item?.purpose
    || item?.conflict
    || item?.turning_point
    || item?.turningPoint
    || item?.reader_payoff
    || item?.readerPayoff,
    80,
  )) || {}
  return [
    card?.goal || card?.purpose,
    card?.conflict,
    card?.turning_point || card?.turningPoint || card?.turn || card?.reversal,
    card?.reader_payoff || card?.readerPayoff,
  ].filter(Boolean).join('；')
}

function chapterAttractionPriority(dimensions: any[]) {
  const weak = dimensions.filter(item => item.status === 'warn')
  if (weak.some(item => item.key === 'page_turn')) return '优先修章末翻页'
  if (weak.some(item => item.key === 'opening_hook')) return '优先修开篇钩子'
  if (weak.some(item => item.key === 'payoff_density')) return '优先补爽点密度'
  if (weak.some(item => item.key === 'scene_drive')) return '优先修场景推进'
  if (weak.some(item => item.key === 'spread_scene')) return '优先补传播场面'
  return ''
}

function storyDriveSceneCards(contextPackage: any, chapter: any = {}) {
  const syncContextPackage = contextWithChapterRawPreDraftForSync(contextPackage, chapter)
  const target = syncContextPackage?.chapter_target || {}
  const brief = syncContextPackage?.pre_draft_brief || syncContextPackage?.preDraftBrief || {}
  return [
    ...asArray(target.scene_cards || target.sceneCards),
    ...asArray(syncContextPackage?.scene_cards || syncContextPackage?.sceneCards),
    ...asArray(brief.scene_briefs || brief.sceneBriefs),
    ...asArray(brief.scene_cards || brief.sceneCards),
  ]
}

function firstCompactText(...values: any[]) {
  for (const value of values) {
    const text = compactText(value, 220)
    if (text) return text
  }
  return ''
}

function firstSceneCardText(sceneCards: any[], keys: string[]) {
  for (const card of sceneCards) {
    for (const key of keys) {
      const text = compactText(card?.[key], 220)
      if (text) return text
    }
  }
  return ''
}

function storyDriveRepairInstruction(key: string) {
  if (key === 'protagonist_choice') return '补出主角在压力下做出的主动选择，必须写成现场行动或对话交锋。'
  if (key === 'choice_cost') return '补出选择带来的即时代价、暴露风险、资源消耗或关系变化。'
  if (key === 'state_change') return '补出本章结束时主角处境、信息、关系或目标状态的明确变化。'
  if (key === 'obstacle') return '补出外部阻碍和冲突压力，让主角不是顺滑完成事件。'
  if (key === 'causal_next_step') return '补出下一步因果，把章末问题、危险或新目标接到下一章。'
  if (key === 'chapter_goal') return '补出本章目标的可见达成、失败或阶段性结果。'
  return '把缺口写成主角选择、冲突阻碍、代价反馈、状态变化和下一步因果。'
}

function normalizeStoryDriveDimension(key: string, label: string, expected: any, chapterText: string, threshold = 44) {
  const text = compactText(expected, 240)
  if (!text) return null
  const match = anchorMatchScore(text, chapterText)
  const delivered = match.score >= threshold
  return {
    key,
    label,
    text,
    expected: text,
    score: match.score,
    evidence: match.matched,
    delivered,
    status: delivered ? 'ok' : 'warn',
    issue: delivered ? '' : `${label}未充分兑现：${text}`,
    repair_instruction: delivered ? '' : storyDriveRepairInstruction(key),
  }
}

function storyDrivePriority(missed: any[]) {
  if (missed.some(item => item.key === 'protagonist_choice')) return '优先补主角选择'
  if (missed.some(item => item.key === 'choice_cost')) return '优先补选择代价'
  if (missed.some(item => item.key === 'state_change')) return '优先补状态变化'
  if (missed.some(item => item.key === 'obstacle')) return '优先补明确阻碍'
  if (missed.some(item => item.key === 'causal_next_step')) return '优先补下一步因果'
  if (missed.some(item => item.key === 'chapter_goal')) return '优先补本章目标'
  return ''
}

export function buildStoryDriveSyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const syncContextPackage = contextWithChapterRawPreDraftForSync(contextPackage, chapter)
  const target = syncContextPackage?.chapter_target || {}
  const brief = syncContextPackage?.pre_draft_brief || syncContextPackage?.preDraftBrief || {}
  const sceneCards = storyDriveSceneCards(syncContextPackage, chapter)
  const dimensions = [
    normalizeStoryDriveDimension(
      'chapter_goal',
      '本章目标',
      firstCompactText(
        target.chapter_goal,
        target.chapterGoal,
        target.goal,
        target.objective,
        brief.chapter_goal,
        brief.chapterGoal,
        brief.chapter_objective,
        brief.chapterObjective,
        firstSceneCardText(sceneCards, ['goal', 'purpose', 'reader_payoff', 'payoff']),
      ),
      chapterText,
      42,
    ),
    normalizeStoryDriveDimension(
      'obstacle',
      '明确阻碍',
      firstCompactText(
        target.core_conflict,
        target.coreConflict,
        target.conflict,
        brief.core_conflict,
        brief.coreConflict,
        brief.conflict,
        firstSceneCardText(sceneCards, ['conflict', 'obstacle', 'pressure']),
      ),
      chapterText,
      40,
    ),
    normalizeStoryDriveDimension(
      'protagonist_choice',
      '主角选择',
      firstCompactText(
        target.protagonist_choice,
        target.protagonistChoice,
        target.active_choice,
        target.activeChoice,
        target.main_character_choice,
        target.mainCharacterChoice,
        brief.protagonist_choice,
        brief.protagonistChoice,
        firstSceneCardText(sceneCards, ['protagonist_choice', 'protagonistChoice', 'active_choice', 'activeChoice', 'turning_point', 'turningPoint', 'turn', 'reversal']),
      ),
      chapterText,
      42,
    ),
    normalizeStoryDriveDimension(
      'choice_cost',
      '选择代价',
      firstCompactText(
        target.choice_cost,
        target.choiceCost,
        target.cost,
        target.consequence,
        target.stakes,
        brief.choice_cost,
        brief.choiceCost,
        brief.cost,
        firstSceneCardText(sceneCards, ['choice_cost', 'cost', 'consequence', 'stakes', 'risk']),
      ),
      chapterText,
      42,
    ),
    normalizeStoryDriveDimension(
      'state_change',
      '状态变化',
      firstCompactText(
        target.state_change,
        target.stateChange,
        target.exit_state,
        target.exitState,
        target.chapter_state_change,
        target.chapterStateChange,
        brief.state_change,
        brief.stateChange,
        firstSceneCardText(sceneCards, ['exit_state', 'exitState', 'state_change', 'stateChange', 'result', 'scene_result', 'sceneResult']),
      ),
      chapterText,
      42,
    ),
    normalizeStoryDriveDimension(
      'causal_next_step',
      '下一步因果',
      firstCompactText(
        target.causal_next_step,
        target.causalNextStep,
        target.next_step,
        target.nextStep,
        target.ending_hook,
        target.endingHook,
        brief.causal_next_step,
        brief.causalNextStep,
        brief.ending_hook,
        brief.endingHook,
        firstSceneCardText(sceneCards, ['causal_next_step', 'causalNextStep', 'next_step', 'nextStep', 'ending_hook', 'endingHook', 'exit_hook', 'exitHook']),
      ),
      chapterText,
      42,
    ),
  ].filter(Boolean)

  const delivered = dimensions.filter((item: any) => item.delivered)
  const missed = dimensions.filter((item: any) => !item.delivered)
  const score = Math.max(0, Math.min(100, Math.round(
    dimensions.length ? dimensions.reduce((sum: number, item: any) => sum + Number(item.score || 0), 0) / dimensions.length : 82,
  )))
  const status = missed.length > 0 || score < 78 ? 'warn' : 'ok'
  const priorityRepair = storyDrivePriority(missed)

  return {
    report_id: `story-drive-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: dimensions.length === 0 ? '故事力未配置' : status === 'ok' ? '故事力 OK' : `故事力缺口 ${missed.length}`,
    summary: dimensions.length === 0
      ? '本章没有明确的故事驱动力任务书，建议补充主角选择、阻碍、代价和状态变化。'
      : status === 'ok'
        ? '本章目标、阻碍、主角选择、选择代价、状态变化和下一步因果已形成可追踪行动链。'
        : `本章有 ${missed.length} 项故事驱动力缺口，${priorityRepair || '优先补主角主动选择和代价反馈'}。`,
    missed_count: missed.length,
    priority_repair: priorityRepair,
    dimensions,
    planned: dimensions,
    delivered,
    missed,
    next_actions: status === 'ok'
      ? ['保持本章主角主动选择、外部阻碍、选择代价、状态变化和下一步因果的连续执行。']
      : [
          '下一次修订必须补出主角主动选择、明确阻碍、选择代价、局面变化和下一步因果。',
          '不能只用旁白解释剧情推进；缺口必须写成现场行动、对话交锋、代价反馈或状态变化。',
          '如果本章原本只是过场，至少让主角做一个不可逆的小选择，并让下一章承接其后果。',
        ],
  }
}

function storyLoopContractFromContext(contextPackage: any = {}, chapter: any = {}) {
  const target = contextPackage?.chapter_target || {}
  const brief = {
    ...(target?.pre_draft_brief || {}),
    ...(target?.preDraftBrief || {}),
    ...(contextPackage?.pre_draft_brief || {}),
    ...(contextPackage?.preDraftBrief || {}),
    ...(chapter?.raw_payload?.pre_draft_brief || {}),
    ...(chapter?.raw_payload?.preDraftBrief || {}),
  }
  return target.story_loop_contract
    || target.storyLoopContract
    || brief.story_loop_contract
    || brief.storyLoopContract
    || contextPackage?.story_loop_contract
    || contextPackage?.storyLoopContract
    || {}
}

function normalizeStoryLoopBeat(key: string, label: string, expected: any, chapterText: string, threshold = 38) {
  const text = compactText(expected, 240)
  if (!text) return null
  const match = anchorMatchScore(text, chapterText)
  const delivered = match.score >= threshold
  return {
    key,
    label,
    text,
    expected: text,
    score: match.score,
    evidence: match.matched,
    delivered,
    status: delivered ? 'ok' : 'warn',
    issue: delivered ? '' : `${label}未充分兑现：${text}`,
    repair_instruction: delivered ? '' : '按 oh-story 最小剧情循环补成 setup -> escalation -> payoff -> carry_over，不要让本章变成孤立事件或解释性过场。',
  }
}

function normalizeStoryLoopNestedLoopCheck(values: any, chapterText: string) {
  const planned = asArray(values).map((item: any) => compactBriefText(item)).filter(Boolean)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const hasLoopLevels = /小循环|中循环|大循环|次级目标|卷目标/.test(text)
  const hasBigExpectation = /大循环期待|大目标|卷目标|长期期待|更大问题|更大谜团|世界观扩展|资源黑幕|背后/.test(text)
  const hasVariation = /不同角度|不同矛盾|换成|三种角度|新地图|新势力|新规则|证人、印章和账册|世界观扩展/.test(text)
  const repeatedTrap = /反复用同一个梗换对象|核心不扩展|一直打脸不同反派|收不同小弟|本质没新东西|只反复|只是反复/.test(text)
  const delivered = hasLoopLevels && hasBigExpectation && hasVariation && !repeatedTrap
  return {
    key: 'nested_loop_rules',
    label: '循环嵌套期待',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 88 : Math.max(12, [hasLoopLevels, hasBigExpectation, hasVariation, !repeatedTrap].filter(Boolean).length * 22),
    evidence: uniqueBriefStrings([
      hasLoopLevels ? '小/中/大循环层级可见' : '',
      hasBigExpectation ? '大循环/长期期待可见' : '',
      hasVariation ? '同一核心卖点换角度或矛盾' : '',
      repeatedTrap ? '只反复用同一个梗换对象' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      !hasLoopLevels ? '缺小循环/中循环/大循环层级' : '',
      !hasBigExpectation ? '缺大循环期待/卷目标铺垫' : '',
      !hasVariation ? '缺同一核心卖点的不同角度/不同矛盾' : '',
      repeatedTrap ? '核心不扩展，只换对象重复' : '',
    ], 8),
    issue: delivered ? '' : '故事循环没有形成小循环 -> 中循环 -> 大循环嵌套，或只是在同一个梗上换对象重复。',
    repair_instruction: delivered ? '' : '补循环嵌套：本章小循环必须完成局部反馈，同时铺垫中循环次级目标和大循环卷目标；同一核心卖点要换不同角度/不同矛盾推进。',
  }
}

function normalizeStoryLoopMapTransitionCheck(values: any, chapterText: string) {
  const planned = asArray(values).map((item: any) => compactBriefText(item)).filter(Boolean)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const oldConflictSettled = /阶段性解决|阶段性收束|告一段落|已阶段性|旧地图[^。；\n]*(阶段性|解决|收束|告一段落)|旧[^。；\n]*(冲突|案|账|仇|目标)[^。；\n]*(阶段性|解决|收束|告一段落)|核心冲突[^。；\n]*(阶段性|解决|收束|告一段落)/.test(text)
  const droppedOldLines = /旧角色[^。；\n]*(一刀切|全部抛弃|全抛|消失)|旧[^。；\n]*(人和事|目标|关系线)[^。；\n]*(全部不再提|不再提|结束了)|一刀切[^。；\n]*抛弃/.test(text)
  const infodump = /新设定[^。；\n]*(一次性|全部倒出|全部介绍|全倒)|设定很多[^。；\n]*(所有|全部)|作者介绍了所有|一次性[^。；\n]*(倒出|讲完|介绍完)|所有[^。；\n]*(宗门|矿脉|历史|规则)[^。；\n]*(介绍|讲完)/.test(text)
  const fivePieceSignals = [
    /新环境|新地图|新地方|陌生|赤炉城|炉烟|矿车|城门|街巷|山门|宗门|地貌|市集|训练场|武馆|药行|商贩|边城|海港|学院/.test(text),
    /新角色|新势力|掌炉人|地头蛇|外来者|管事|执事|守门|同窗|上级|城主|堂主/.test(text),
    /新规则|规矩|法度|城规|门槛|要求|炼炉保|炉牌|通行|试炼|审核|禁令/.test(text),
    /新目标|目标是|要得到|查清|拿到|进入|夺回|争取|换到|寻找|查出/.test(text),
    /新冲突|冲突是|挡路|扣住|阻止|压到|逼|卡住|对手|敌人|破坏者|抢走|拦住/.test(text),
  ]
  const fivePieceCount = fivePieceSignals.filter(Boolean).length
  const hasNewMapFivePieces = fivePieceCount >= 4
  const hasFirstFiveExpectation = /前\s*5\s*章|前五章|五章内|代入感|期待感|期待|让读者[^。；\n]*盼|目标[^。；\n]*明确|第一块|第一场|试炼|门槛[^。；\n]*眼前|压到眼前/.test(text)
  const hasCarryOverMainline = !droppedOldLines && /贯穿主线|主线继续|跨地图|旧日关系线|老角色|带人走|跟来|仍然|继续牵住|未完成|旧[^。；\n]*(目标|关系|角色|账|税契|黑账|证人)[^。；\n]*(继续|牵住|跟来|作证|跨地图|保留)/.test(text)
  const hasEscalation = /更大规模|更高门槛|更强对手|循环[^。；\n]*升级|危险度|规则复杂度|对手层级|上层|更复杂|更高层级|更强[^。；\n]*对手/.test(text)
  const hasBridge = /过渡人物|新旧地图联动|带人走|旧日关系|老角色|跟来|证人|税契|主线继续|跨地图|旧势力[^。；\n]*上级/.test(text)
  const hasRelationshipFirst = /人际关系[^。；\n]*(先|动|推动)|关系线[^。；\n]*(先动|先|触发|牵动|推动)|旧日关系[^。；\n]*(先|动|触发|牵动|带出)|旧关系[^。；\n]*(先|动|触发|牵动|带出)|(?:证人|阿洛|老角色|旧友|同门|旧部|师承)[^。；\n]*(来信|求援|作证|带路|牵线|跟来|先动)|先[^。；\n]*(收到|联系|求援|来信|作证|牵线)[^。；\n]*(主角|沈砚)[^。；\n]*(才|决定|动身|进入)|人际关系动了\s*->\s*主角再动/.test(text)
  const delivered = oldConflictSettled
    && hasNewMapFivePieces
    && hasFirstFiveExpectation
    && hasCarryOverMainline
    && hasEscalation
    && hasBridge
    && hasRelationshipFirst
    && !infodump
    && !droppedOldLines
  const checks = [oldConflictSettled, hasNewMapFivePieces, hasFirstFiveExpectation, hasCarryOverMainline, hasEscalation, hasBridge, hasRelationshipFirst, !infodump, !droppedOldLines]
  return {
    key: 'map_transition_rules',
    label: '换地图承接',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 88 : Math.max(10, checks.filter(Boolean).length * 11),
    evidence: uniqueBriefStrings([
      oldConflictSettled ? '旧地图核心冲突已阶段性解决' : '',
      hasNewMapFivePieces ? `新地图五件套可见(${fivePieceCount}/5)` : '',
      hasFirstFiveExpectation ? '前5章代入感/期待感已有目标或门槛' : '',
      hasCarryOverMainline ? '贯穿主线或旧关系承接可见' : '',
      hasEscalation ? '循环升级/更高门槛可见' : '',
      hasBridge ? '过渡人物或新旧联动可见' : '',
      hasRelationshipFirst ? '人际关系先行动，主角再动' : '',
      infodump ? '新设定一次性倒出' : '',
      droppedOldLines ? '旧角色/旧线被一刀切抛弃' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      !oldConflictSettled ? '旧地图核心冲突未阶段性解决' : '',
      !hasNewMapFivePieces ? '新地图五件套不足' : '',
      !hasFirstFiveExpectation ? '前5章代入感和期待感未建立' : '',
      !hasCarryOverMainline ? '缺贯穿主线或旧关系承接' : '',
      !hasEscalation ? '缺循环升级或更高门槛' : '',
      !hasBridge ? '缺过渡人物或新旧地图联动' : '',
      !hasRelationshipFirst ? '缺人际关系先行铺垫' : '',
      infodump ? '新设定一次性全部倒出' : '',
      droppedOldLines ? '旧角色或旧线一刀切抛弃' : '',
    ], 8),
    issue: delivered ? '' : '换地图/换阶段没有完成旧地图收束、新地图五件套、前5章期待、贯穿主线、人际关系先行和循环升级的承接。',
    repair_instruction: delivered ? '' : '补换地图承接：先让旧地图核心冲突阶段性解决，再让旧关系、过渡人物、求援、来信、作证或利益牵线先动起来，推动主角进入新环境、新角色、新规则、新目标、新冲突；前5章只铺必要门槛和期待，保留贯穿主线，避免旧线全抛或新设定一次性倒完。',
  }
}

function storyLoopPriority(missed: any[]) {
  if (missed.some(item => item.key === 'payoff')) return '优先补兑现反馈'
  if (missed.some(item => item.key === 'carry_over')) return '优先补承接期待'
  if (missed.some(item => item.key === 'map_transition_rules')) return '优先补换地图承接'
  if (missed.some(item => item.key === 'nested_loop_rules')) return '优先补循环嵌套期待'
  if (missed.some(item => item.key === 'escalation')) return '优先补升级阻碍'
  if (missed.some(item => item.key === 'setup')) return '优先补铺垫入局'
  return ''
}

export function buildStoryLoopSyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const contract = storyLoopContractFromContext(contextPackage, chapter)
  const beats = [
    normalizeStoryLoopBeat('setup', '铺垫入局', firstCompactText(contract.setup, contract.opening_setup, contract.openingSetup), chapterText, 36),
    normalizeStoryLoopBeat('escalation', '升级阻碍', firstCompactText(contract.escalation, contract.obstacle_escalation, contract.obstacleEscalation), chapterText, 36),
    normalizeStoryLoopBeat('payoff', '兑现反馈', firstCompactText(contract.payoff, contract.feedback, contract.result), chapterText, 36),
    normalizeStoryLoopBeat('carry_over', '承接期待', firstCompactText(contract.carry_over, contract.carryOver, contract.next_expectation, contract.nextExpectation), chapterText, 36),
    normalizeStoryLoopMapTransitionCheck(contract.map_transition_rules || contract.mapTransitionRules, chapterText),
    normalizeStoryLoopNestedLoopCheck(contract.nested_loop_rules || contract.nestedLoopRules, chapterText),
  ].filter(Boolean)
  const delivered = beats.filter((item: any) => item.delivered)
  const missed = beats.filter((item: any) => !item.delivered)
  const missedCount = missed.length
  const score = Math.max(0, Math.min(100, Math.round(
    beats.length ? beats.reduce((sum: number, item: any) => sum + Number(item.score || 0), 0) / beats.length : 82,
  )))
  const status = missedCount > 0 || score < 78 ? 'warn' : 'ok'
  const priorityRepair = storyLoopPriority(missed)

  return {
    report_id: `story-loop-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: beats.length === 0 ? '故事循环未配置' : status === 'ok' ? '故事循环 OK' : `故事循环缺口 ${missedCount}`,
    summary: beats.length === 0
      ? '本章没有配置 story_loop_contract，建议补充 setup、escalation、payoff 和 carry_over。'
      : status === 'ok'
        ? '本章已形成 setup -> escalation -> payoff -> carry_over 的故事循环闭环。'
        : `正文有 ${missedCount} 项故事循环缺口，${priorityRepair || '优先补兑现反馈和承接期待'}。`,
    missed_count: missedCount,
    priority_repair: priorityRepair,
    quality_checks: asArray(contract.quality_checks || contract.qualityChecks).map((item: any) => compactBriefText(item)).filter(Boolean).slice(0, 8),
    planned: beats,
    delivered,
    missed,
    next_actions: status === 'ok'
      ? ['保持 setup -> escalation -> payoff -> carry_over：每章既完成本章反馈，也把下一章期待接上。']
      : [
          '下一次修订必须补足 setup -> escalation -> payoff -> carry_over，把铺垫、阻碍升级、兑现反馈和承接期待写成正文可见事件。',
          '不能只用“事情进入下一阶段”或旁白总结替代承接；章尾必须留下由本章反馈触发的新目标、新风险、新线索或新期待。',
          missed.some((item: any) => item.key === 'map_transition_rules')
            ? '补换地图承接：旧地图核心冲突先阶段性解决，再用过渡人物/旧关系/贯穿主线带出新地图五件套；必须先让人际关系动了 -> 主角再动，前5章建立代入感和期待感，避免旧线全抛和新设定一次性倒出。'
            : '',
          missed.some((item: any) => item.key === 'nested_loop_rules')
            ? '补故事循环嵌套：小循环 -> 中循环 -> 大循环必须同时可见，小循环中必须铺垫大循环的期待，并把同一核心卖点换不同角度/不同矛盾推进。'
            : '',
        ],
  }
}

function informationFlowContractForSync(contextPackage: any = {}, chapter: any = {}) {
  const target = contextPackage?.chapter_target || {}
  const brief = {
    ...(target?.pre_draft_brief || {}),
    ...(target?.preDraftBrief || {}),
    ...(contextPackage?.pre_draft_brief || {}),
    ...(contextPackage?.preDraftBrief || {}),
    ...(chapter?.raw_payload?.pre_draft_brief || {}),
    ...(chapter?.raw_payload?.preDraftBrief || {}),
  }
  return target?.information_flow_contract
    || target?.informationFlowContract
    || contextPackage?.information_flow_contract
    || contextPackage?.informationFlowContract
    || brief?.information_flow_contract
    || brief?.informationFlowContract
    || {}
}

function informationFlowArray(...values: any[]) {
  return uniqueBriefStrings(values.flatMap(value => asArray(value)).map((item: any) => compactBriefText(item)).filter(Boolean), 20)
}

function normalizeInformationFlowCheck(key: string, label: string, values: any[], chapterText: string, fix: string, threshold = 34) {
  const planned = informationFlowArray(values)
  if (!planned.length) return null
  const checked = planned.map(text => {
    const match = anchorMatchScore(text, chapterText)
    return {
      text,
      score: match.score,
      evidence: match.matched,
      delivered: match.score >= threshold,
    }
  })
  const missed = checked.filter(item => !item.delivered)
  return {
    key,
    label,
    text: planned.join('；'),
    expected: planned.join('；'),
    score: Math.round(checked.reduce((sum, item) => sum + Number(item.score || 0), 0) / Math.max(1, checked.length)),
    evidence: checked.flatMap(item => item.evidence).filter(Boolean).slice(0, 8),
    delivered: missed.length === 0,
    status: missed.length === 0 ? 'ok' : 'warn',
    missed_items: missed.map(item => item.text),
    issue: missed.length === 0 ? '' : `${label}未充分落地：${missed.map(item => item.text).join('；')}`,
    repair_instruction: missed.length === 0 ? '' : fix,
  }
}

function buildInformationFlowInfodumpCheck(contract: any, chapterText: string) {
  const guardrails = informationFlowArray(
    contract.no_infodump_guardrails,
    contract.noInfodumpGuardrails,
    contract.water_risk_guards,
    contract.waterRiskGuards,
  )
  const infodumpRisks: any[] = [
    ...scanInfodumpRisks(chapterText),
    ...scanDialogueInfodumpRisks(chapterText),
  ]
  if (
    /解释了很多(?:背景|规则|设定|制度)|制度分为|体系分为|漫长历史|大家终于明白规则|事情进入下一阶段/.test(String(chapterText || ''))
  ) {
    infodumpRisks.push({
      key: 'information_flow_summary_infodump',
      label: '短水文说明扫描',
      evidence: '正文用解释背景、制度分层或“事情进入下一阶段”概括信息推进。',
      fix: '把背景说明改成审问、证据、规则触发、代价反馈或角色判断中的可见信息释放。',
    })
  }
  if (!guardrails.length && !infodumpRisks.length) return null
  return {
    key: 'no_infodump_guardrails',
    label: '背景说明书',
    text: guardrails.join('；') || '信息必须随冲突释放，不写背景说明书。',
    expected: guardrails.join('；') || '信息必须随冲突释放，不写背景说明书。',
    score: infodumpRisks.length ? Math.max(0, 100 - infodumpRisks.length * 28) : 92,
    evidence: infodumpRisks.map((item: any) => compactBriefText(item.evidence || item.fix)).filter(Boolean).slice(0, 8),
    delivered: infodumpRisks.length === 0,
    status: infodumpRisks.length === 0 ? 'ok' : 'warn',
    missed_items: infodumpRisks.map((item: any) => compactBriefText(item.evidence || item.label)).filter(Boolean).slice(0, 8),
    issue: infodumpRisks.length === 0 ? '' : `正文存在 ${infodumpRisks.length} 处背景说明书/设定说明风险。`,
    repair_instruction: infodumpRisks.length === 0 ? '' : '把设定信息拆进冲突、动作、对话、规则触发、代价反馈或角色判断里；删掉不影响当前选择的背景说明。',
  }
}

function buildInformationFlowTransitionCompressionCheck(contract: any, chapterText: string) {
  const planned = informationFlowArray(
    contract.transition_compression_rules,
    contract.transitionCompressionRules,
  )
  if (!planned.length) return null
  const text = String(chapterText || '')
  const fillerRisks = [
    /走过(?:长廊|街道|路口|院子|走廊)|穿过(?:长廊|街道|院子|人群)/.test(text) ? '纯移动过渡' : '',
    /寒暄(?:了几句|片刻|一番)|互相寒暄|闲聊(?:了几句|片刻|一番)/.test(text) ? '寒暄过渡' : '',
    /看了窗外(?:天气|雨|天色)|望着窗外|天色渐暗|阳光洒在/.test(text) ? '环境过渡' : '',
    /事情进入下一阶段|一切告一段落|接下来就是|随后他们来到了|时间很快过去/.test(text) ? '概括式换场' : '',
    /没有信息量|拖字数|纯过渡/.test(text) ? '正文承认无信息过渡' : '',
  ].filter(Boolean)
  const compressionSignals = /过渡不是填充|没有信息量就(?:删掉|删除)|直接跳过|一句带过|压缩|带过|删无信息量过渡|不拖泥带水/.test(text)
  const usefulTransitionSignals = /余韵|后果|压力延续|回应悬念|验证|反转|升级|下一步目标|信息差|风险|代价/.test(text)
  const delivered = fillerRisks.length === 0 && (compressionSignals || usefulTransitionSignals)
  return {
    key: 'transition_compression_rules',
    label: '过渡压缩',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 88 : Math.max(12, [fillerRisks.length === 0, compressionSignals, usefulTransitionSignals].filter(Boolean).length * 28),
    evidence: uniqueBriefStrings([
      compressionSignals ? '过渡压缩信号可见' : '',
      usefulTransitionSignals ? '过渡承担信息/风险/情绪/目标' : '',
      ...fillerRisks,
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      ...fillerRisks,
      !compressionSignals && !usefulTransitionSignals ? '缺过渡压缩或有效信息承载' : '',
    ], 8),
    issue: delivered ? '' : '过渡场景没有被压缩：纯移动、寒暄、环境描写或概括式换场正在拖慢信息流。',
    repair_instruction: delivered ? '' : '按 oh-story 信息流修复：过渡不是填充，没有信息量就删掉；纯移动/寒暄/环境描写直接跳过或压成一句，并把过场改成信息、风险、情绪余波或下一步目标。',
  }
}

function informationFlowPriority(missed: any[]) {
  if (missed.some(item => item.key === 'no_infodump_guardrails')) return '优先删背景说明书'
  if (missed.some(item => item.key === 'transition_compression_rules')) return '优先删无信息量过渡'
  if (missed.some(item => item.key === 'reveal_order')) return '优先修揭示顺序'
  if (missed.some(item => item.key === 'suspense_responses')) return '优先补悬念回应'
  if (missed.some(item => item.key === 'information_units')) return '优先补信息团'
  return ''
}

export function buildInformationFlowSyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const contract = informationFlowContractForSync(contextPackage, chapter)
  const checks = [
    normalizeInformationFlowCheck(
      'information_units',
      '信息团',
      [
        contract.information_units,
        contract.informationUnits,
        contract.scene_information_units,
        contract.sceneInformationUnits,
      ],
      chapterText,
      '补足每个场景的信息团，让读者能一句话概括这段在推进什么信息。',
    ),
    normalizeInformationFlowCheck(
      'reveal_order',
      '揭示顺序',
      [
        contract.reveal_order,
        contract.revealOrder,
        contract.progression_chain,
        contract.progressionChain,
      ],
      chapterText,
      '按发现、验证、反转、回收、升级或推出新目标的顺序重排信息释放。',
      30,
    ),
    normalizeInformationFlowCheck(
      'suspense_responses',
      '悬念回应',
      [
        contract.suspense_responses,
        contract.suspenseResponses,
        contract.transition_rules,
        contract.transitionRules,
      ],
      chapterText,
      '回应、升级或明确延迟上一场悬念，不能断裂换题。',
    ),
    buildInformationFlowTransitionCompressionCheck(contract, chapterText),
    buildInformationFlowInfodumpCheck(contract, chapterText),
  ].filter(Boolean)
  const delivered = checks.filter((item: any) => item.delivered)
  const missed = checks.filter((item: any) => !item.delivered)
  const missedCount = missed.length
  const score = Math.max(0, Math.min(100, Math.round(
    checks.length ? checks.reduce((sum: number, item: any) => sum + Number(item.score || 0), 0) / checks.length : 82,
  )))
  const status = missedCount > 0 || score < 78 ? 'warn' : 'ok'
  const priorityRepair = informationFlowPriority(missed)

  return {
    report_id: `information-flow-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: checks.length === 0 ? '信息流未配置' : status === 'ok' ? '信息流 OK' : `信息流缺口 ${missedCount}`,
    summary: checks.length === 0
      ? '本章没有配置 information_flow_contract，建议补充信息团、揭示顺序、悬念回应、过渡压缩和无背景说明书规则。'
      : status === 'ok'
        ? '正文的信息团、揭示顺序、悬念回应、过渡压缩和无背景说明书规则已基本落地。'
        : `正文有 ${missedCount} 项信息流缺口，${priorityRepair || '优先保证信息随冲突释放'}。`,
    missed_count: missedCount,
    priority_repair: priorityRepair,
    quality_checks: asArray(contract.quality_checks || contract.qualityChecks).map((item: any) => compactBriefText(item)).filter(Boolean).slice(0, 8),
    planned: checks,
    delivered,
    missed,
    next_actions: status === 'ok'
      ? ['保持信息流：每个场景都有可概括信息团，信息随冲突释放，揭示顺序递进，悬念有回应或明确延迟，无信息量过渡直接删除或压缩。']
      : [
          '下一次修订必须补足信息流：信息随冲突释放，按揭示顺序递进，回应上一场悬念，删无信息量过渡和背景说明书。',
          '每个场景至少交付一个可概括信息团；纯移动、寒暄、环境描写和设定说明没有信息量时直接删除或压缩。',
        ],
  }
}

function expectationThresholdContractForSync(contextPackage: any = {}, chapter: any = {}) {
  const target = contextPackage?.chapter_target || {}
  const brief = {
    ...(target?.pre_draft_brief || {}),
    ...(target?.preDraftBrief || {}),
    ...(contextPackage?.pre_draft_brief || {}),
    ...(contextPackage?.preDraftBrief || {}),
    ...(chapter?.raw_payload?.pre_draft_brief || {}),
    ...(chapter?.raw_payload?.preDraftBrief || {}),
  }
  return target?.expectation_threshold_contract
    || target?.expectationThresholdContract
    || contextPackage?.expectation_threshold_contract
    || contextPackage?.expectationThresholdContract
    || brief?.expectation_threshold_contract
    || brief?.expectationThresholdContract
    || {}
}

function expectationThresholdArray(...values: any[]) {
  return uniqueBriefStrings(values.flatMap(value => Array.isArray(value) ? value : value ? [value] : []).map((item: any) => compactBriefText(item)).filter(Boolean), 20)
}

function normalizeExpectationThresholdCheck(key: string, label: string, values: any[], chapterText: string, fix: string, threshold = 32) {
  const planned = expectationThresholdArray(values)
  if (!planned.length) return null
  const checked = planned.map(text => {
    const match = anchorMatchScore(text, chapterText)
    return {
      text,
      score: match.score,
      evidence: match.matched,
      delivered: match.score >= threshold,
    }
  })
  const missed = checked.filter(item => !item.delivered)
  return {
    key,
    label,
    text: planned.join('；'),
    expected: planned.join('；'),
    score: Math.round(checked.reduce((sum, item) => sum + Number(item.score || 0), 0) / Math.max(1, checked.length)),
    evidence: checked.flatMap(item => item.evidence).filter(Boolean).slice(0, 8),
    delivered: missed.length === 0,
    status: missed.length === 0 ? 'ok' : 'warn',
    missed_items: missed.map(item => item.text),
    issue: missed.length === 0 ? '' : `${label}未充分落地：${missed.map(item => item.text).join('；')}`,
    repair_instruction: missed.length === 0 ? '' : fix,
  }
}

function buildExpectationThresholdNextOpenLoopCheck(contract: any, chapterText: string) {
  const planned = expectationThresholdArray(
    contract.nested_units,
    contract.nestedUnits,
    contract.next_open_loop,
    contract.nextOpenLoop,
    contract.vacuum_guardrails,
    contract.vacuumGuardrails,
  )
  const anchorCheck = normalizeExpectationThresholdCheck(
    'next_open_loop',
    '下一开环',
    planned,
    chapterText,
    '闭环当前目标前后必须立起下一目标、新门槛、新线索、新困境或新期待。',
    28,
  )
  const vacuumRisks = scanExpectationVacuumRisks(chapterText)
  if (!anchorCheck && !vacuumRisks.length) return null
  if (!vacuumRisks.length) return anchorCheck
  const base = anchorCheck || {
    key: 'next_open_loop',
    label: '下一开环',
    text: '闭环当前目标前后必须立起下一目标、新门槛、新线索、新困境或新期待。',
    expected: '闭环当前目标前后必须立起下一目标、新门槛、新线索、新困境或新期待。',
    evidence: [],
    missed_items: [],
    issue: '',
    repair_instruction: '',
  }
  return {
    ...base,
    score: Math.min(Number(base.score || 100), Math.max(0, 100 - vacuumRisks.length * 35)),
    delivered: false,
    status: 'warn',
    evidence: [...asArray(base.evidence), ...vacuumRisks.map((item: any) => compactBriefText(item.evidence))].filter(Boolean).slice(0, 8),
    missed_items: [...asArray(base.missed_items), ...vacuumRisks.map((item: any) => compactBriefText(item.evidence))].filter(Boolean).slice(0, 8),
    issue: '章尾闭合当前麻烦但缺少下一开环。',
    repair_instruction: '闭环当前目标前后必须立起下一目标、新门槛、新线索、新困境或新期待。',
  }
}

function buildExpectationBeforePayoffCheck(contract: any, chapterText: string) {
  const planned = expectationThresholdArray(
    contract.expectation_before_payoff_rules,
    contract.expectationBeforePayoffRules,
  )
  if (!planned.length) return null
  const text = String(chapterText || '')
  const scored = planned.map(item => ({ text: item, match: anchorMatchScore(item, chapterText) }))
  const tensionSignals = [
    /期待感\s*(?:>|大于|高于)\s*爽点|铺垫[^。！？!?]{0,24}(?:不少于|多于|长于|拉长)|延迟满足|将满未满|满足而未满足/.test(text) ? '期待感大于爽点' : '',
    /先[^。！？!?]{0,24}(?:铺垫|拉长|加压|设门槛|吊起|种下)[^。！？!?]{0,48}(?:再|才|最后)[^。！？!?]{0,24}(?:兑现|释放|爽点|反证|打脸)/.test(text) ? '先铺垫再释放' : '',
    /释放前一刻|爽点到来前|需求最大|张力最高|没有立刻兑现/.test(text) ? '释放前张力可见' : '',
  ].filter(Boolean)
  const rushed = /没有期待铺垫|缺少期待铺垫|爽点立刻释放|没铺垫就兑现|没有铺垫就兑现|马上兑现|读者还没开始等|提前泄气|铺垫不足/.test(text)
  const deliveredItems = scored.filter(item => item.match.score >= 28).length
  const delivered = !rushed && (deliveredItems >= 1 || tensionSignals.length >= 2)
  return {
    key: 'expectation_before_payoff',
    label: '期待大于爽点',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? Math.max(86, Math.round((deliveredItems / Math.max(1, planned.length)) * 100)) : Math.max(18, tensionSignals.length * 24),
    evidence: uniqueBriefStrings([
      ...scored.flatMap(item => item.match.matched),
      ...tensionSignals,
      rushed ? '爽点立刻释放/期待铺垫不足' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : planned.filter(item => anchorMatchScore(item, chapterText).score < 28).slice(0, 8),
    issue: delivered ? '' : '期待铺垫不足：爽点释放太快，读者需求还没有被拉到最高点。',
    repair_instruction: delivered ? '' : '按 oh-story 期待感 > 爽点修复：铺垫期待远比展现爽点重要；爽点前必须先用危机、门槛、信息差、延迟满足或将满未满的动作拉长需求，铺垫篇幅不少于释放篇幅，不要提前泄气。',
  }
}

function expectationThresholdPriority(missed: any[]) {
  if (missed.some(item => item.key === 'three_expectation_lines')) return '优先补三种期待线'
  if (missed.some(item => item.key === 'expectation_before_payoff')) return '优先补期待铺垫'
  if (missed.some(item => item.key === 'next_open_loop')) return '优先补下一开环'
  if (missed.some(item => item.key === 'two_long_one_short')) return '优先补两长一短'
  if (missed.some(item => item.key === 'thresholds')) return '优先拆门槛'
  if (missed.some(item => item.key === 'dynamic_thresholds')) return '优先补动态加码'
  return ''
}

function expectationThreeLinesArray(value: any) {
  const raw = value || {}
  if (Array.isArray(raw)) return expectationThresholdArray(raw)
  return uniqueBriefStrings([
    raw.plot_expectation,
    raw.plotExpectation,
    raw.story_expectation,
    raw.storyExpectation,
    raw.theme_payoff,
    raw.themePayoff,
    raw.theme_sweetener,
    raw.themeSweetener,
    raw.freshness_hook,
    raw.freshnessHook,
    raw.novelty_hook,
    raw.noveltyHook,
  ].map((item: any) => compactBriefText(item)).filter(Boolean), 8)
}

export function buildExpectationThresholdSyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const contract = expectationThresholdContractForSync(contextPackage, chapter)
  const twoLongOneShort = expectationThresholdArray(
    contract.short_expectation,
    contract.shortExpectation,
    contract.current_expectations,
    contract.currentExpectations,
    contract.medium_expectations,
    contract.mediumExpectations,
    contract.long_expectations,
    contract.longExpectations,
  )
  const checks = [
    normalizeExpectationThresholdCheck(
      'two_long_one_short',
      '两长一短',
      twoLongOneShort,
      chapterText,
      '恢复两长一短：短期期待驱动当前单元，1-2条长期期待保持远期拉力。',
      30,
    ),
    normalizeExpectationThresholdCheck(
      'thresholds',
      '门槛拆分',
      [
        contract.thresholds,
        contract.gates,
        contract.conditions,
        contract.payoff_or_delay_plan,
        contract.payoffOrDelayPlan,
      ],
      chapterText,
      '把大目标拆成资源型、成就型、多条件型、动态门槛或收集型条件，不能一步解决。',
      30,
    ),
    normalizeExpectationThresholdCheck(
      'dynamic_thresholds',
      '动态加码',
      [
        contract.dynamic_thresholds,
        contract.dynamicThresholds,
      ],
      chapterText,
      '每跨越一个门槛就立刻设立下一个门槛、代价或更高条件。',
      30,
    ),
    normalizeExpectationThresholdCheck(
      'three_expectation_lines',
      '三种期待线',
      expectationThreeLinesArray(contract.three_expectation_lines || contract.threeExpectationLines),
      chapterText,
      '补齐三种期待线：剧情期待负责吊胃口，主题甜头负责持续满足，新鲜感负责间歇刺激，三者必须同时有正文证据。',
      30,
    ),
    buildExpectationBeforePayoffCheck(contract, chapterText),
    buildExpectationThresholdNextOpenLoopCheck(contract, chapterText),
  ].filter(Boolean)
  const delivered = checks.filter((item: any) => item.delivered)
  const missed = checks.filter((item: any) => !item.delivered)
  const missedCount = missed.length
  const score = Math.max(0, Math.min(100, Math.round(
    checks.length ? checks.reduce((sum: number, item: any) => sum + Number(item.score || 0), 0) / checks.length : 82,
  )))
  const status = missedCount > 0 || score < 78 ? 'warn' : 'ok'
  const priorityRepair = expectationThresholdPriority(missed)

  return {
    report_id: `expectation-threshold-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: checks.length === 0 ? '期待阈值未配置' : status === 'ok' ? '期待阈值 OK' : `期待阈值缺口 ${missedCount}`,
    summary: checks.length === 0
      ? '本章没有配置 expectation_threshold_contract，建议补充两长一短、三种期待线、门槛拆分、动态加码、期待铺垫和下一开环。'
      : status === 'ok'
        ? '正文已基本兑现两长一短、三种期待线、门槛拆分、动态加码、期待铺垫和下一开环。'
        : `正文有 ${missedCount} 项期待阈值缺口，${priorityRepair || '优先恢复两长一短和下一开环'}。`,
    missed_count: missedCount,
    priority_repair: priorityRepair,
    quality_checks: asArray(contract.quality_checks || contract.qualityChecks).map((item: any) => compactBriefText(item)).filter(Boolean).slice(0, 8),
    planned: checks,
    delivered,
    missed,
    next_actions: status === 'ok'
      ? ['保持期待阈值：两长一短和三种期待线同时在线，门槛分批提出，期待铺垫不少于爽点释放，兑现当前目标前先立下一开环。']
      : [
          '下一次修订必须补期待阈值：恢复两长一短，补剧情期待 + 主题甜头 + 新鲜感，拆分系统性门槛，补动态加码，补期待感 > 爽点的铺垫，先立下一开环，再兑现旧期待。',
          '不能让大目标一步解决；每跨过一个门槛，就要立刻给出新门槛、新代价、新线索或更大的长期期待。',
        ],
  }
}

function emotionalArcContractForSync(contextPackage: any = {}, chapter: any = {}) {
  const target = contextPackage?.chapter_target || {}
  const brief = {
    ...(target?.pre_draft_brief || {}),
    ...(target?.preDraftBrief || {}),
    ...(contextPackage?.pre_draft_brief || {}),
    ...(contextPackage?.preDraftBrief || {}),
    ...(chapter?.raw_payload?.pre_draft_brief || {}),
    ...(chapter?.raw_payload?.preDraftBrief || {}),
  }
  return target?.emotional_arc_contract
    || target?.emotionalArcContract
    || contextPackage?.emotional_arc_contract
    || contextPackage?.emotionalArcContract
    || brief?.emotional_arc_contract
    || brief?.emotionalArcContract
    || {}
}

function emotionalArcArray(...values: any[]) {
  return uniqueBriefStrings(values.flatMap(value => asArray(value)).map((item: any) => compactBriefText(item)).filter(Boolean), 20)
}

function emotionalArcHeuristicEvidence(key: string, chapterText: string) {
  const text = String(chapterText || '')
  const hasPressure = /压迫|承压|当众|公开|逼|认罪|不该如此|羞辱|威胁|调动/.test(text)
  const hasSafety = /底牌|旧印章|证据|潜在解法|后手|暗牌|冷静|没有争辩|机会|线索/.test(text)
  const hasRelease = /反证|反击|反制|释放|爽|目标达成|改口|态度转变|全场|翻盘|洗清|证明/.test(text)
  const hasNextExpectation = /新的期待|第二个证人|第三个证人|下一|背面露出|线索|新目标|更大问题|名字/.test(text)
  if (key === 'emotion_formula' && hasPressure && hasRelease && hasNextExpectation) {
    return ['压迫调动', hasSafety ? '安全感信号' : '', '反证释放', '新期待'].filter(Boolean)
  }
  if (key === 'scene_emotion_steps' && hasPressure && hasRelease) {
    return ['压迫调动', hasSafety ? '底牌/潜在解法' : '', '释放兑现'].filter(Boolean)
  }
  if (key === 'expectation_rules' && hasNextExpectation) {
    return ['新期待已立起']
  }
  return []
}

function normalizeEmotionalArcCheck(key: string, label: string, values: any[], chapterText: string, fix: string, threshold = 30) {
  const planned = emotionalArcArray(values)
  if (!planned.length) return null
  const checked = planned.map(text => {
    const match = anchorMatchScore(text, chapterText)
    return {
      text,
      score: match.score,
      evidence: match.matched,
      delivered: match.score >= threshold,
    }
  })
  const missed = checked.filter(item => !item.delivered)
  const heuristicEvidence = missed.length ? emotionalArcHeuristicEvidence(key, chapterText) : []
  if (heuristicEvidence.length) {
    return {
      key,
      label,
      text: planned.join('；'),
      expected: planned.join('；'),
      score: Math.max(82, Math.round(checked.reduce((sum, item) => sum + Number(item.score || 0), 0) / Math.max(1, checked.length))),
      evidence: uniqueBriefStrings([...checked.flatMap(item => item.evidence), ...heuristicEvidence], 8),
      delivered: true,
      status: 'ok',
      missed_items: [],
      issue: '',
      repair_instruction: '',
    }
  }
  return {
    key,
    label,
    text: planned.join('；'),
    expected: planned.join('；'),
    score: Math.round(checked.reduce((sum, item) => sum + Number(item.score || 0), 0) / Math.max(1, checked.length)),
    evidence: checked.flatMap(item => item.evidence).filter(Boolean).slice(0, 8),
    delivered: missed.length === 0,
    status: missed.length === 0 ? 'ok' : 'warn',
    missed_items: missed.map(item => item.text),
    issue: missed.length === 0 ? '' : `${label}未充分落地：${missed.map(item => item.text).join('；')}`,
    repair_instruction: missed.length === 0 ? '' : fix,
  }
}

function payoffEscalationDimensionEvidence(chapterText: string) {
  const text = String(chapterText || '')
  const impact = /影响范围|个人|群体|全场|全校|全网|社会|宗门|审判庭|公开|扩散|长老|权威|官方|行业/.test(text)
  const depth = /揭示深度|表象|本质|颠覆|黑幕|根源|背后|真相|规则|改写|推翻/.test(text)
  const status = /身份落差|身份|路人|大佬|权威|马甲|掉马|全场震惊|改口|承认|跪|低头/.test(text)
  return [
    impact ? '影响范围递增' : '',
    depth ? '揭示深度递增' : '',
    status ? '身份落差递增' : '',
  ].filter(Boolean)
}

function normalizePayoffReverseDesignCheck(contract: any, chapterText: string) {
  const reverse = contract.payoff_reverse_design || contract.payoffReverseDesign
  if (!reverse || typeof reverse !== 'object') return null
  const text = String(chapterText || '')
  const payoffPattern = /爽点类型|目标达成|态度转变|收获盘点|能力碾压|隐藏身份|掉马|情感圆满|反证|反击|反制|洗清|改口|态度转变|获得|奖励|收获|证明|翻盘/
  const expectationPattern = /期待点|拉起期待|读者[^。；\n]*(等|期待|想知道)|等待|悬念|信息差|门槛|误判|将满未满|压迫|承压|逼|认罪|压罪|能不能|会不会/
  const setupPattern = /铺垫|先铺|前置|伏笔|底牌|后手|旧印章|账册|证据|袖口|物件|规则漏洞|关系|轻视|嘲笑|误判|公开审判/
  const explicitReverse = /爽点倒推|先[^。；\n]*(爽点类型|让读者满足)[^。；\n]*再[^。；\n]*(期待|期待点)[^。；\n]*最后[^。；\n]*(铺垫|倒推)|爽点类型\s*->\s*期待点\s*->\s*铺垫/.test(text)
  const payoffMatch = text.match(payoffPattern)
  const expectationMatch = text.match(expectationPattern)
  const setupMatch = text.match(setupPattern)
  const payoffIndex = payoffMatch?.index ?? -1
  const expectationIndex = expectationMatch?.index ?? -1
  const setupIndex = setupMatch?.index ?? -1
  const hasPayoffType = payoffIndex >= 0
  const hasExpectationPoint = expectationIndex >= 0
  const hasSetup = setupIndex >= 0
  const hasReverseChain = explicitReverse
    || (hasSetup && hasExpectationPoint && hasPayoffType && setupIndex <= payoffIndex && expectationIndex <= payoffIndex)
  const delivered = hasPayoffType && hasExpectationPoint && hasSetup && hasReverseChain
  const planned = uniqueBriefStrings([
    ...asArray(reverse.design_order || reverse.designOrder),
    ...asArray(reverse.expectation_point_rules || reverse.expectationPointRules),
    ...asArray(reverse.setup_rules || reverse.setupRules),
    ...asArray(reverse.quality_checks || reverse.qualityChecks),
  ].map((item: any) => compactBriefText(item)).filter(Boolean), 12)
  return {
    key: 'payoff_reverse_design',
    label: '爽点倒推法',
    text: planned.join('；') || '先定爽点类型 -> 再定期待点 -> 最后倒推铺垫。',
    expected: planned.join('；') || '先定爽点类型 -> 再定期待点 -> 最后倒推铺垫。',
    score: delivered ? 88 : Math.max(12, [hasPayoffType, hasExpectationPoint, hasSetup, hasReverseChain].filter(Boolean).length * 22),
    evidence: uniqueBriefStrings([
      hasPayoffType ? '爽点类型/释放结果可见' : '',
      hasExpectationPoint ? '期待点/压力拉起可见' : '',
      hasSetup ? '铺垫物件/证据/规则/关系可见' : '',
      hasReverseChain ? '铺垫 -> 期待升高 -> 爽点释放链条可见' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      !hasPayoffType ? '缺先定爽点类型' : '',
      !hasExpectationPoint ? '缺期待点设计' : '',
      !hasSetup ? '缺铺垫倒推' : '',
      !hasReverseChain ? '缺铺垫 -> 期待升高 -> 爽点释放链条' : '',
    ], 8),
    issue: delivered ? '' : '正文没有体现 oh-story 爽点倒推法：需要先明确爽点类型，再设计期待点，最后让铺垫反向服务释放。',
    repair_instruction: delivered ? '' : '按 oh-story 爽点倒推法修复：先确定读者满足方式（能力碾压/目标达成/收获盘点/态度转变/隐藏身份/情感圆满度），再拉起对应期待点，最后补能在释放时回收的物件、证据、关系、规则漏洞或对手误判铺垫。',
  }
}

function normalizePayoffTierRulesCheck(contract: any, chapterText: string) {
  const planned = emotionalArcArray(contract.payoff_tier_rules, contract.payoffTierRules)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const hasDailySmallPayoff = /日常小装逼|日常(?:生活)?展示优势|维持读者耐心|随手(?:展示|露一手)|小回报|小爽点|只用一句|轻描淡写/.test(text)
  const hasCoreMainlinePayoff = /核心爽点|主线目标|围绕主线|切在主线|推进主线|服务主线|反证旧账|旧账主线|拿回(?:审判)?资格|破解(?:规则|案件)|洗清|证明|目标达成|主线[^。；\n]*(反证|推进|破解|拿回|改写|完成)/.test(text)
  const offTrackPayoffSignal = /偏离爽点|背离主线|离开主线|和[^。；\n]*主线无关|无关[^。；\n]*装逼|去别处装逼|酒楼[^。；\n]*打脸|路人[^。；\n]*打脸|随手打脸路人|支线[^。；\n]*(装逼|打脸)[^。；\n]*(无关|不影响)|跑去[^。；\n]*(打脸|装逼)/.test(text)
  const offTrackPayoffNegated = /(?:没有|不|避免|删掉|删除|改写|改成)[^。；\n]{0,18}(?:偏离爽点|背离主线|离开主线|去别处装逼|偏离主线)/.test(text)
  const hasOffTrackPayoff = offTrackPayoffSignal && !offTrackPayoffNegated
  const hasEffectiveCoreMainlinePayoff = hasCoreMainlinePayoff && !hasOffTrackPayoff
  const delivered = hasEffectiveCoreMainlinePayoff && !hasOffTrackPayoff
  return {
    key: 'payoff_tier_rules',
    label: '装逼层级',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 88 : Math.max(12, [hasDailySmallPayoff, hasEffectiveCoreMainlinePayoff, !hasOffTrackPayoff].filter(Boolean).length * 28),
    evidence: uniqueBriefStrings([
      hasDailySmallPayoff ? '日常小装逼控制篇幅/维持耐心' : '',
      hasEffectiveCoreMainlinePayoff ? '核心爽点服务主线目标' : '',
      hasOffTrackPayoff ? '出现偏离主线的装逼/打脸' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      !hasEffectiveCoreMainlinePayoff ? '缺核心爽点服务主线目标' : '',
      hasOffTrackPayoff ? '偏离爽点背离主线' : '',
    ], 8),
    issue: delivered ? '' : '正文没有按 oh-story 装逼层级管理爽点：核心爽点必须切在主线目标，偏离主线的爽点要删或改成主线推进。',
    repair_instruction: delivered ? '' : '按 oh-story 装逼层级修复：日常小装逼只用于大爽点间隙维持耐心；核心爽点必须围绕主线目标推进；删除或改写背离主线去别处装逼的桥段，让每次打脸、反证、能力展示都改变主线目标、关系、资源、规则或下一步行动。',
  }
}

function normalizePayoffDensityRulesCheck(contract: any, chapterText: string) {
  const planned = emotionalArcArray(contract.payoff_density_rules, contract.payoffDensityRules)
  if (!planned.length) return null
  const text = String(chapterText || '')
  const densityRisks = scanPayoffDensityRisks(text)
  const explicitSinglePayoffStretch = /拉长单个爽点|单个爽点[^。；\n]*(铺垫|拖|拉长)|反复铺垫同一个大爽点|一千多字[^。；\n]*(没有|缺少)[^。；\n]*(信息增量|能力展示|危机反制|关系变化|小回收)/.test(text)
  const payoffSignals = uniqueBriefStrings([
    /信息增量|发现|确认|揭开|线索/.test(text) ? '信息增量' : '',
    /能力展示|辨伪|露一手|展示优势/.test(text) ? '能力展示' : '',
    /危机反制|反制|反击|破局|规则漏洞/.test(text) ? '危机反制' : '',
    /关系变化|站到|站队|支持|改口|态度转变/.test(text) ? '关系变化' : '',
    /小回收|小回报|收益结算|拿到|获得|奖励|阶段结算/.test(text) ? '小回收' : '',
  ], 8)
  const delivered = densityRisks.length === 0 && !explicitSinglePayoffStretch && payoffSignals.length >= 2
  return {
    key: 'payoff_density_rules',
    label: '多爽点密度',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 88 : Math.max(12, payoffSignals.length * 18 + (densityRisks.length ? 0 : 18) + (!explicitSinglePayoffStretch ? 16 : 0)),
    evidence: uniqueBriefStrings([
      ...payoffSignals,
      ...densityRisks.map((item: any) => compactBriefText(item.evidence || item.fix)).filter(Boolean),
      explicitSinglePayoffStretch ? '长铺垫只等一个爽点' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      payoffSignals.length < 2 ? '小回报数量不足' : '',
      densityRisks.length ? '存在 800-1200 字回报密度缺口' : '',
      explicitSinglePayoffStretch ? '拉长单个爽点铺垫' : '',
    ], 8),
    issue: delivered ? '' : '正文没有按 oh-story 爽点密度规则拆出多个小回报，可能把单个爽点铺垫拉得过长。',
    repair_instruction: delivered ? '' : '按 oh-story 爽点密度修复：不要拉长单个爽点的铺垫，而是多想几个爽点；每 800-1200 字至少落一次信息增量、能力展示、危机反制、关系变化或小回收，把长铺垫拆成发现、确认、反制、站队、收益结算或新期待。',
  }
}

function normalizeEmotionModuleRecompositionRulesCheck(contract: any, chapterText: string) {
  const planned = emotionalArcArray(
    contract.emotion_module_recomposition_rules,
    contract.emotionModuleRecompositionRules,
  )
  if (!planned.length) return null
  const text = String(chapterText || '')
  const repeatSignal = /重复|套路|模板|同一个(?:戏剧单元|英雄救美|退婚打脸|打脸模板)|同样结构|反复使用|继续使用/.test(text)
  const noSceneChange = /没有换场景|未换场景|场景没有变化|还是同一场景/.test(text)
  const noOpponentChange = /没有换对手|未换对手|对手没有变化|还是同一对手/.test(text)
  const noNewEmotion = /没有新情绪|没加新情绪|未加新情绪|情绪没有变化/.test(text)
  const noStakesChange = /stakes[^。；\n]{0,20}没有变化|奖励[^。；\n]{0,20}没有变化|代价[^。；\n]{0,20}没有变化|复杂度[^。；\n]{0,20}没有变化/.test(text)
  const negatedRepeatUnit = /没有重复同一个戏剧单元|并未重复同一个戏剧单元|不再重复同一个戏剧单元/.test(text)
  const explicitNoVariation = !negatedRepeatUnit && /重复同一个戏剧单元|同样结构|没有换场景|没有换对手|没有新情绪|stakes[^。；\n]{0,20}没有变化|奖励[^。；\n]{0,20}没有变化/.test(text)
  const hasSceneChange = !noSceneChange && /换场景|场景从[^。；\n]{0,30}换到|换到[^。；\n]{0,16}(审判庭|酒楼|战场|家宴|直播间|擂台)|新场景/.test(text)
  const hasOpponentChange = !noOpponentChange && /换对手|对手从[^。；\n]{0,30}换成|新对手|从路人换成|从小反派换成/.test(text)
  const hasNewEmotion = !noNewEmotion && /加新情绪|新增[^。；\n]{0,18}情绪|新情绪|愧疚|遗憾|心疼|羞耻|安全感|掌控感|旧痛|歉意/.test(text)
  const hasStakesChange = !noStakesChange && /stakes|提高[^。；\n]{0,20}(代价|奖励|风险|门槛|复杂度)|代价[^。；\n]{0,20}(提高|升级|扩大)|奖励[^。；\n]{0,20}(提高|升级|变复杂)|从[^。；\n]{0,24}提高到|从[^。；\n]{0,24}扩大到/.test(text)
  const variationEvidence = uniqueBriefStrings([
    hasSceneChange ? '场景变化' : '',
    hasOpponentChange ? '对手变化' : '',
    hasNewEmotion ? '新增情绪角度' : '',
    hasStakesChange ? 'stakes/奖励复杂度提高' : '',
  ], 8)
  const delivered = !explicitNoVariation && (!repeatSignal || variationEvidence.length > 0)
  return {
    key: 'emotion_module_recomposition_rules',
    label: '情绪模块重组',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 88 : Math.max(12, variationEvidence.length * 22),
    evidence: uniqueBriefStrings([
      repeatSignal ? '检测到套路/模板复用信号' : '未检测到同一戏剧单元重复',
      ...variationEvidence,
      explicitNoVariation ? '正文显式承认重复模板无变化' : '',
    ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : ['重复戏剧单元没有换场景/对手/新情绪/stakes'],
    issue: delivered ? '' : '正文复用同一套路时没有完成情绪模块重组，读者会感到戏剧单元重复磨损。',
    repair_instruction: delivered ? '' : '按 oh-story 情绪模块重组修复：同一爽感可以重复，但不能重复同一个戏剧单元；至少换场景、换对手、加新情绪或提高 stakes/奖励复杂度之一。',
  }
}

function normalizePayoffEscalationRulesCheck(contract: any, chapterText: string) {
  const planned = emotionalArcArray(
    contract.payoff_escalation_rules,
    contract.payoffEscalationRules,
  )
  if (!planned.length) return null
  const risks = scanPayoffEscalationRisks(chapterText)
  const dimensionEvidence = payoffEscalationDimensionEvidence(chapterText)
  const checked = planned.map(text => {
    const match = anchorMatchScore(text, chapterText)
    const deliveredByDimension =
      (/影响范围/.test(text) && dimensionEvidence.some(item => /影响范围/.test(item)))
      || (/揭示深度/.test(text) && dimensionEvidence.some(item => /揭示深度/.test(item)))
      || (/身份落差/.test(text) && dimensionEvidence.some(item => /身份落差/.test(item)))
    return {
      text,
      score: Math.max(match.score, deliveredByDimension ? 86 : 0),
      evidence: [...match.matched, ...(deliveredByDimension ? dimensionEvidence : [])],
      delivered: deliveredByDimension || match.score >= 26,
    }
  })
  const missed = checked.filter(item => !item.delivered)
  const delivered = risks.length === 0 && missed.length === 0
  return {
    key: 'payoff_escalation_rules',
    label: '爽点递增对比',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 88 : Math.max(38, Math.round(checked.reduce((sum, item) => sum + Number(item.score || 0), 0) / Math.max(1, checked.length)) - risks.length * 18),
    evidence: uniqueBriefStrings([
      ...checked.flatMap(item => item.evidence),
      ...risks.map((item: any) => item.evidence || item.fix),
    ].filter(Boolean), 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: risks.length
      ? risks.map((item: any) => compactBriefText(item.label || item.key)).filter(Boolean).slice(0, 8)
      : missed.map(item => item.text),
    issue: delivered ? '' : '爽点递增对比未充分落地：连续爽点需要逐级增加影响范围、揭示深度或身份落差。',
    repair_instruction: delivered ? '' : '按 oh-story 爽点递增对比修复：连续爽点必须逐级增加影响范围、揭示深度或身份落差；把重复的“震惊/打脸/赢了”改成个人 -> 群体 -> 社会，表象 -> 本质 -> 颠覆，或路人 -> 大佬 -> 全场震惊。',
  }
}

function normalizeEmotionalTurningRulesCheck(contract: any, chapterText: string) {
  const planned = emotionalArcArray(
    contract.emotional_turning_rules,
    contract.emotionalTurningRules,
    contract.failure_mode_guards,
    contract.failureModeGuards,
  )
  if (!planned.length) return null
  const text = String(chapterText || '')
  const hasTransition = /情绪转向|情绪转折|从[^。！？\n]{0,18}(?:变成|转成|跳到)|压迫[^。！？\n]{0,24}(?:释放|爽感|反击)|愤怒[^。！？\n]{0,24}(?:释然|冷静|爽感)|不安[^。！？\n]{0,24}(?:真相|震惊)/.test(text)
  const explicitNoTrigger = /没有(?:任何)?(?:新证据|新信息|新动作|新代价|新关系压力|触发事件|任何人改口)|无理由|只是忽然|莫名其妙|突然(?:变好|释然|高兴|爽了)|没有遇到任何事件/.test(text)
  const triggerSignals = uniqueBriefStrings([
    /新证据|第二份账册|账册|尾号|袖口墨痕|旧印章|线索|真相|缺页|证人/.test(text) ? '新证据/线索触发' : '',
    /新信息|发现|揭开|暴露|指向|对上|浮出/.test(text) ? '新信息触发' : '',
    /递出|按住|翻开|拿出|出手|拦住|改口|站到|退开|公开承认|反击|反证/.test(text) ? '新动作/关系变化触发' : '',
    /代价|失去|风险|逼认罪|承压|压迫升级|公开升级|站队|审判资格/.test(text) ? '新代价/压力触发' : '',
    /事件触发|触发情绪转向|由[^。！？\n]{0,24}触发/.test(text) ? '事件触发自检' : '',
  ], 8)
  const hasTrigger = !explicitNoTrigger && triggerSignals.length > 0
  const longFlatEmotion = /一直很(?:压抑|痛苦|愤怒|难受|沉默)|连续\s*5\+?\s*小节没有情绪转折|一路(?:虐到底|爽到底)|场面停住|众人也一直沉默/.test(text)
  const delivered = hasTransition && hasTrigger && !explicitNoTrigger && !longFlatEmotion
  return {
    key: 'emotional_turning_rules',
    label: '情绪转向',
    text: planned.join('；'),
    expected: planned.join('；'),
    score: delivered ? 88 : Math.max(12, [hasTransition, hasTrigger, !explicitNoTrigger, !longFlatEmotion].filter(Boolean).length * 22),
    evidence: delivered
      ? uniqueBriefStrings(['事件触发情绪转向', ...triggerSignals], 8)
      : uniqueBriefStrings([
          hasTransition ? '有情绪转向自述' : '缺情绪转向',
          !hasTrigger ? '缺新证据/新信息/新动作/新代价触发' : '',
          explicitNoTrigger ? '存在无触发转向或忽然释然' : '',
          longFlatEmotion ? '情绪长期太平或原地压抑' : '',
        ], 8),
    delivered,
    status: delivered ? 'ok' : 'warn',
    missed_items: delivered ? [] : uniqueBriefStrings([
      !hasTransition ? '缺每 3-5 小节一次情绪转向' : '',
      !hasTrigger ? '缺触发事件：新证据/新信息/新动作/新代价/新关系压力' : '',
      explicitNoTrigger ? '情绪无理由跳步' : '',
      longFlatEmotion ? '连续小节没有有效情绪转折' : '',
    ], 8),
    issue: delivered ? '' : '情绪转向没有可见触发事件，或正文只自述“情绪转向”但缺少新证据、新信息、新动作、新代价或新关系压力。',
    repair_instruction: delivered ? '' : '按 oh-story 情绪转向修复：每次情绪转向都必须由事件触发；给转向前补新证据、新信息、新动作、新代价或新关系压力，例如第二份账册、证人改口、盟友站队、规则漏洞暴露、压迫升级后的反证动作，再让角色从愤怒/压迫逐步转到冷静反击/爽感释放。',
  }
}

function buildEmotionalArcDeterministicCheck(chapterText: string) {
  const risks = [
    ...scanEmotionalStasisRisks(chapterText),
    ...scanDownwardSafetyRisks(chapterText),
    ...scanOppressionPurposeRisks(chapterText),
    ...scanPayoffDensityRisks(chapterText),
    ...scanPayoffEscalationRisks(chapterText),
    ...scanTrumpCardEffectRisks(chapterText),
  ]
  if (!risks.length) return null
  const hasDownward = risks.some((item: any) => /下行情节|压制目的/.test(String(item.label || item.key || '')))
  const label = hasDownward ? '下行情节安全感' : '情绪弧确定性扫描'
  return {
    key: 'deterministic_emotional_arc',
    label,
    text: '情绪弧必须避免原地打转、连续下压无安全感、无回报长段和爽点不递增。',
    expected: '情绪弧必须避免原地打转、连续下压无安全感、无回报长段和爽点不递增。',
    score: Math.max(0, 100 - risks.length * 18),
    evidence: risks.map((item: any) => compactBriefText(item.evidence || item.fix)).filter(Boolean).slice(0, 8),
    delivered: false,
    status: 'warn',
    missed_items: risks.map((item: any) => compactBriefText(item.label || item.key)).filter(Boolean).slice(0, 8),
    issue: `正文触发 ${risks.length} 项情绪弧确定性风险。`,
    repair_instruction: '按 oh-story 情绪弧修复：补调动 -> 行动/转折 -> 释放；下压时给安全感，爽点要有递进和可见读者收益。',
  }
}

function emotionalArcPriority(missed: any[]) {
  if (missed.some(item => item.label === '下行情节安全感')) return '优先补下行情节安全感'
  if (missed.some(item => item.key === 'payoff_reverse_design')) return '优先补爽点倒推链'
  if (missed.some(item => item.key === 'payoff_tier_rules')) return '优先修正装逼层级'
  if (missed.some(item => item.key === 'payoff_density_rules')) return '优先补多爽点密度'
  if (missed.some(item => item.key === 'emotion_module_recomposition_rules')) return '优先重组情绪模块'
  if (missed.some(item => item.key === 'payoff_escalation_rules')) return '优先补爽点递增'
  if (missed.some(item => item.key === 'scene_emotion_steps')) return '优先补调动释放'
  if (missed.some(item => item.key === 'emotion_formula')) return '优先补情绪公式'
  if (missed.some(item => item.key === 'payoff_types')) return '优先补爽点释放'
  return ''
}

export function buildEmotionalArcSyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const contract = emotionalArcContractForSync(contextPackage, chapter)
  const checks = [
    normalizeEmotionalArcCheck(
      'emotion_formula',
      '情绪公式',
      [
        contract.emotion_formula,
        contract.emotionFormula,
        contract.arc_shape,
        contract.arcShape,
      ],
      chapterText,
      '正文必须让读者看见平静 -> 调动 -> 释放 -> 爽，而不是只把事件写正确。',
      26,
    ),
    normalizeEmotionalArcCheck(
      'scene_emotion_steps',
      '调动释放',
      [
        contract.scene_emotion_steps,
        contract.sceneEmotionSteps,
        contract.pressure_methods,
        contract.pressureMethods,
      ],
      chapterText,
      '补出调动和释放：先让压力、期待或不该如此可感，再用行动结果、反应差异或新信息完成释放。',
      28,
    ),
    normalizeEmotionalArcCheck(
      'payoff_types',
      '爽点释放',
      [
        contract.payoff_types,
        contract.payoffTypes,
      ],
      chapterText,
      '补出目标达成、态度转变、收获盘点、能力碾压或其他可见读者收益。',
      28,
    ),
    normalizePayoffReverseDesignCheck(contract, chapterText),
    normalizePayoffTierRulesCheck(contract, chapterText),
    normalizePayoffDensityRulesCheck(contract, chapterText),
    normalizeEmotionModuleRecompositionRulesCheck(contract, chapterText),
    normalizePayoffEscalationRulesCheck(contract, chapterText),
    normalizeEmotionalArcCheck(
      'expectation_rules',
      '断期待禁止',
      [
        contract.expectation_rules,
        contract.expectationRules,
      ],
      chapterText,
      '闭环一个期待时，必须同时开启新的期待或更大问题。',
      28,
    ),
    normalizeEmotionalArcCheck(
      'safety_rules',
      '下行情节安全感',
      [
        contract.safety_rules,
        contract.safetyRules,
      ],
      chapterText,
      '下行情节中必须给读者看见底牌、潜在解法、盟友动作、规则漏洞或反击窗口。',
      28,
    ),
    normalizeEmotionalArcCheck(
      'emotional_three_blades',
      '情绪三板斧',
      [
        contract.bonding_setup_rules,
        contract.bondingSetupRules,
        contract.emotional_tear_rules,
        contract.emotionalTearRules,
        contract.lingering_aftertaste_rules,
        contract.lingeringAftertasteRules,
      ],
      chapterText,
      '补情绪三板斧：前段用具体物件/数字/重复动作铺羁绊，中段用反差/错位/延迟真相撕裂，结尾用安静细节或物件回声收束。',
      30,
    ),
    normalizeEmotionalTurningRulesCheck(contract, chapterText),
    buildEmotionalArcDeterministicCheck(chapterText),
  ].filter(Boolean)
  const delivered = checks.filter((item: any) => item.delivered)
  const missed = checks.filter((item: any) => !item.delivered)
  const missedCount = missed.length
  const score = Math.max(0, Math.min(100, Math.round(
    checks.length ? checks.reduce((sum: number, item: any) => sum + Number(item.score || 0), 0) / checks.length : 82,
  )))
  const status = missedCount > 0 || score < 78 ? 'warn' : 'ok'
  const priorityRepair = emotionalArcPriority(missed)

  return {
    report_id: `emotional-arc-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: checks.length === 0 ? '情绪弧未配置' : status === 'ok' ? '情绪弧 OK' : `情绪弧缺口 ${missedCount}`,
    summary: checks.length === 0
      ? '本章没有配置 emotional_arc_contract，建议补充情绪公式、调动释放、爽点类型、爽点倒推法、装逼层级、多爽点密度、情绪模块重组、爽点递增对比、期待规则和安全感规则。'
      : status === 'ok'
        ? '正文已基本兑现情绪公式、调动释放、爽点释放、爽点倒推法、装逼层级、多爽点密度、情绪模块重组、爽点递增对比和下行情节安全感。'
        : `正文有 ${missedCount} 项情绪弧缺口，${priorityRepair || '优先补调动释放和安全感'}。`,
    missed_count: missedCount,
    priority_repair: priorityRepair,
    quality_checks: asArray(contract.quality_checks || contract.qualityChecks).map((item: any) => compactBriefText(item)).filter(Boolean).slice(0, 8),
    planned: checks,
    delivered,
    missed,
    next_actions: status === 'ok'
      ? ['保持情绪弧：平静 -> 调动 -> 释放 -> 爽，先按爽点类型 -> 期待点 -> 铺垫倒推章纲，正文再按铺垫 -> 期待升高 -> 爽点释放呈现；核心爽点切在主线上，日常小装逼只维持耐心，避免偏离爽点；不要拉长单个爽点铺垫，800-1200 字内要有信息增量、能力展示、危机反制、关系变化或小回收；复用同一情绪模块时换场景/换对手/加新情绪或提高 stakes；爽点按影响范围、揭示深度或身份落差递增，下压有安全感。']
      : [
          '下一次修订必须补情绪弧：恢复平静 -> 调动 -> 释放 -> 爽，先定爽点类型，再拉期待点，最后倒推铺垫；正文按铺垫 -> 期待升高 -> 爽点释放呈现，核心爽点必须服务主线目标，删掉或改写偏离主线的爽点；不要拉长单个爽点铺垫，要拆出多个小回报；复用同一情绪模块时必须换场景/换对手/加新情绪或提高 stakes，并按影响范围、揭示深度或身份落差兑现递增释放。',
          '连续下压不能只让主角受辱受损；必须给出底牌、潜在解法、盟友动作、规则漏洞、反击窗口或明确读者收益。',
        ],
  }
}

function characterArcBriefFromContext(contextPackage: any, chapter: any = {}) {
  const syncContextPackage = contextWithChapterRawPreDraftForSync(contextPackage, chapter)
  const target = syncContextPackage?.chapter_target || {}
  const brief = syncContextPackage?.pre_draft_brief || syncContextPackage?.preDraftBrief || {}
  return target.character_arc_brief
    || target.characterArcBrief
    || brief.character_arc_brief
    || brief.characterArcBrief
    || syncContextPackage?.character_arc_context
    || syncContextPackage?.characterArcContext
    || {}
}

function characterArcRepairInstruction(key: string) {
  if (key === 'growth_beat') return '补出角色在本章发生的可见成长节点，必须体现认知、选择、关系或行动方式变化。'
  if (key === 'desire') return '补出角色本章想要什么，让欲望推动行动，而不是只被事件推着走。'
  if (key === 'flaw_pressure') return '补出角色缺陷、恐惧或旧习惯被冲突压迫的瞬间。'
  if (key === 'relationship_shift') return '补出人物关系的可见变化，例如信任、敌意、亏欠、试探或结盟。'
  if (key === 'voice_anchor') return '补出角色稳定口吻和行动风格，避免所有人物说话像同一个旁白。'
  return '把人物弧光缺口写成角色欲望、缺陷受压、关系变化、成长节点或口吻锚点。'
}

function normalizeCharacterArcDimension(key: string, label: string, expected: any, chapterText: string, threshold = 42) {
  const text = compactText(expected, 240)
  if (!text) return null
  const match = anchorMatchScore(text, chapterText)
  const delivered = match.score >= threshold
  return {
    key,
    label,
    text,
    expected: text,
    score: match.score,
    evidence: match.matched,
    delivered,
    status: delivered ? 'ok' : 'warn',
    issue: delivered ? '' : `${label}未充分兑现：${text}`,
    repair_instruction: delivered ? '' : characterArcRepairInstruction(key),
  }
}

function characterArcPriority(missed: any[]) {
  if (missed.some(item => item.key === 'growth_beat')) return '优先补成长节点'
  if (missed.some(item => item.key === 'desire')) return '优先补角色欲望'
  if (missed.some(item => item.key === 'flaw_pressure')) return '优先补缺陷受压'
  if (missed.some(item => item.key === 'relationship_shift')) return '优先补关系变化'
  if (missed.some(item => item.key === 'voice_anchor')) return '优先补人物口吻'
  return ''
}

export function buildCharacterArcSyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const arc = characterArcBriefFromContext(contextPackage, chapter)
  const sceneCards = storyDriveSceneCards(contextWithChapterRawPreDraftForSync(contextPackage, chapter), chapter)
  const dimensions = [
    normalizeCharacterArcDimension(
      'desire',
      '角色欲望',
      firstCompactText(
        arc.desire,
        arc.character_desire,
        arc.characterDesire,
        arc.goal,
        firstSceneCardText(sceneCards, ['character_goal', 'characterGoal', 'desire', 'goal']),
      ),
      chapterText,
      40,
    ),
    normalizeCharacterArcDimension(
      'flaw_pressure',
      '缺陷受压',
      firstCompactText(
        arc.flaw_pressure,
        arc.flawPressure,
        arc.inner_conflict,
        arc.innerConflict,
        arc.fear,
        firstSceneCardText(sceneCards, ['flaw_pressure', 'flawPressure', 'inner_conflict', 'fear', 'pressure']),
      ),
      chapterText,
      40,
    ),
    normalizeCharacterArcDimension(
      'relationship_shift',
      '关系变化',
      firstCompactText(
        arc.relationship_shift,
        arc.relationshipShift,
        arc.relationship_change,
        arc.relationshipChange,
        firstSceneCardText(sceneCards, ['relationship_shift', 'relationshipShift', 'relationship_change', 'relationshipChange']),
      ),
      chapterText,
      40,
    ),
    normalizeCharacterArcDimension(
      'growth_beat',
      '成长节点',
      firstCompactText(
        arc.growth_beat,
        arc.growthBeat,
        arc.character_growth,
        arc.characterGrowth,
        arc.arc_step,
        arc.arcStep,
        firstSceneCardText(sceneCards, ['growth_beat', 'growthBeat', 'character_growth', 'arc_step', 'exit_state']),
      ),
      chapterText,
      40,
    ),
    normalizeCharacterArcDimension(
      'voice_anchor',
      '口吻锚点',
      firstCompactText(
        arc.voice_anchor,
        arc.voiceAnchor,
        arc.voice_rule,
        arc.voiceRule,
        arc.dialogue_style,
        firstSceneCardText(sceneCards, ['voice_anchor', 'voiceAnchor', 'voice_rule', 'dialogue_style']),
      ),
      chapterText,
      36,
    ),
  ].filter(Boolean)

  const delivered = dimensions.filter((item: any) => item.delivered)
  const missed = dimensions.filter((item: any) => !item.delivered)
  const score = Math.max(0, Math.min(100, Math.round(
    dimensions.length ? dimensions.reduce((sum: number, item: any) => sum + Number(item.score || 0), 0) / dimensions.length : 82,
  )))
  const status = missed.length > 0 || score < 78 ? 'warn' : 'ok'
  const priorityRepair = characterArcPriority(missed)

  return {
    report_id: `character-arc-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: dimensions.length === 0 ? '人物弧光未配置' : status === 'ok' ? '人物弧光 OK' : `人物弧光缺口 ${missed.length}`,
    summary: dimensions.length === 0
      ? '本章没有明确的人物弧光任务，建议在开写任务书中补角色欲望、缺陷受压、关系变化和成长节点。'
      : status === 'ok'
        ? '本章角色欲望、缺陷受压、关系变化、成长节点和口吻锚点已基本落地。'
        : `本章有 ${missed.length} 项人物弧光缺口，${priorityRepair || '优先补人物成长节点'}。`,
    missed_count: missed.length,
    priority_repair: priorityRepair,
    dimensions,
    planned: dimensions,
    delivered,
    missed,
    next_actions: status === 'ok'
      ? ['保持角色欲望、缺陷受压、关系变化、成长节点和口吻锚点的连续执行。']
      : [
          '下一次修订必须补出人物成长：角色欲望、缺陷受压、关系变化、成长节点和口吻锚点至少落地主要缺口。',
          '不能只补心理旁白；新增内容必须写成角色行动、选择、对话反应、关系反馈或可见状态变化。',
          '人物成长不能改长期方向；只推进本章应承担的阶段性变化。',
        ],
  }
}

export function buildChapterAttractionReviewReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const syncContextPackage = contextWithChapterRawPreDraftForSync(contextPackage, chapter)
  const target = syncContextPackage?.chapter_target || {}
  const retentionBrief = retentionBriefFromContext(contextPackage, chapter)
  const dimensions = [
    normalizeAttractionDimension('opening_hook', '开篇钩子', retentionBrief.opening_hook || retentionBrief.openingHook || target.opening_hook || target.openingHook || target.summary, chapterText, { openingOnly: true, threshold: 44 }),
    normalizeAttractionDimension('scene_drive', '场景推进', sceneDriveExpectation(syncContextPackage, chapter) || target.conflict || target.core_conflict || target.coreConflict, chapterText, { threshold: 40 }),
    normalizeAttractionDimension('payoff_density', '爽点密度', retentionBrief.payoff_promise || retentionBrief.payoffPromise || target.reader_payoff || target.readerPayoff || target.payoff, chapterText, { threshold: 42 }),
    normalizeAttractionDimension('page_turn', '章末翻页', retentionBrief.ending_question || retentionBrief.endingQuestion || target.ending_hook || target.endingHook, chapterText, { tailOnly: true, threshold: 42 }),
    normalizeAttractionDimension('spread_scene', '传播场面', retentionBrief.short_drama_scene || retentionBrief.shortDramaScene || target.signature_scene_brief?.signature_scene || target.signatureSceneBrief?.signatureScene || target.ip_scene_hook || target.ipSceneHook, chapterText, { threshold: 42 }),
  ]
  const weak = dimensions.filter(item => item.status === 'warn')
  const score = Math.max(0, Math.min(100, Math.round(dimensions.reduce((sum, item) => sum + Number(item.score || 0), 0) / Math.max(1, dimensions.length))))
  const status = weak.length > 0 || score < 78 ? 'warn' : 'ok'
  const priorityRepair = chapterAttractionPriority(dimensions)
  return {
    report_id: `chapter-attraction-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: status === 'ok' ? '吸引力 OK' : `吸引力缺口 ${weak.length}`,
    summary: status === 'ok'
      ? '本章开篇钩子、场景推进、爽点密度、章末翻页和传播场面已形成连续读者拉力。'
      : `本章有 ${weak.length} 项吸引力执行缺口，${priorityRepair || '优先处理读者翻页动力'}。`,
    weak_count: weak.length,
    priority_repair: priorityRepair,
    dimensions,
    weak_dimensions: weak,
    next_actions: status === 'ok'
      ? ['保持当前章的读者拉力执行结构，并在下一章继续承接章末问题。']
      : [
          '前300字必须尽快给出异常、危险、欲望或反常信息。',
          '每个场景补齐目标、阻碍、转折、回报，避免纯解释或纯氛围过场。',
          '最后300字必须留下下一章非看不可的危险、选择、反转或未解答案。',
          '补出可视化传播场面和短周期爽点，让读者能复述本章最有记忆点的一幕。',
        ],
  }
}

function innovationBriefFromContext(contextPackage: any, chapter: any = {}) {
  const syncContextPackage = contextWithChapterRawPreDraftForSync(contextPackage, chapter)
  const target = syncContextPackage?.chapter_target || {}
  const brief = syncContextPackage?.pre_draft_brief || syncContextPackage?.preDraftBrief || {}
  return target.innovation_brief || target.innovationBrief || brief.innovation_brief || brief.innovationBrief || {}
}

function normalizeInnovationBeat(key: string, label: string, value: any) {
  const text = compactText(value, 180)
  return text ? { key, label, text } : null
}

function innovationBeatMatch(beat: any, chapterText: string) {
  const match = anchorMatchScore(beat.text, chapterText)
  const key = String(beat.key || '')
  const threshold = key === 'chapter_angle'
    ? 22
    : key.startsWith('differentiation_guardrail')
      ? 38
      : 44
  const delivered = match.score >= threshold || (key === 'chapter_angle' && match.score >= 20 && asArray(match.matched).length >= 2)
  return {
    ...beat,
    score: match.score,
    evidence: match.matched,
    delivered,
  }
}

export function buildInnovationSyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const innovationBrief = innovationBriefFromContext(contextPackage, chapter)
  const planned = [
    normalizeInnovationBeat('chapter_angle', '创新角度', innovationBrief.chapter_angle || innovationBrief.chapterAngle),
    ...asArray(innovationBrief.execution_points || innovationBrief.executionPoints).map((item: any, index: number) => normalizeInnovationBeat(`execution_point_${index + 1}`, '执行点', item)),
    ...asArray(innovationBrief.differentiation_guardrails || innovationBrief.differentiationGuardrails).map((item: any, index: number) => normalizeInnovationBeat(`differentiation_guardrail_${index + 1}`, '差异护栏', item)),
    ...asArray(innovationBrief.ip_adaptation_hooks || innovationBrief.ipAdaptationHooks).map((item: any, index: number) => normalizeInnovationBeat(`ip_adaptation_hook_${index + 1}`, 'IP化场面', item)),
  ].filter(Boolean)
  const checked = planned.map(item => innovationBeatMatch(item, chapterText))
  const delivered = checked.filter(item => item.delivered)
  const missed = checked.filter(item => !item.delivered)
  const missedCount = missed.length
  const score = Math.max(0, Math.min(100, Math.round(
    planned.length ? (delivered.length / planned.length) * 100 : 82,
  )))
  const status = missedCount > 0 || score < 78 ? 'warn' : 'ok'

  return {
    report_id: `innovation-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: status === 'ok' ? '创新 OK' : `创新缺口 ${missedCount}`,
    summary: status === 'ok'
      ? '本章创新角度、执行点、差异护栏和可视化场面已基本落地。'
      : `创新执行有 ${missedCount} 项未在正文中充分兑现。`,
    missed_count: missedCount,
    planned,
    delivered,
    missed,
    next_actions: status === 'ok'
      ? ['保持开写任务书的创新执行和写后复盘闭环。']
      : [
          '下一次修订优先补足创新执行 missed 项，避免把本章写成普通套路章。',
          '把创新角度转成可见选择、机制反差、规则代价或 IP 化场面，不要只靠旁白解释卖点。',
      ],
  }
}

function signatureSceneBriefFromContext(contextPackage: any, chapter: any = {}) {
  const syncContextPackage = contextWithChapterRawPreDraftForSync(contextPackage, chapter)
  return normalizeSignatureSceneBrief(
    syncContextPackage?.chapter_target?.signature_scene_brief
      || syncContextPackage?.chapter_target?.signatureSceneBrief
      || syncContextPackage?.signature_scene_brief
      || syncContextPackage?.signatureSceneBrief
      || syncContextPackage?.pre_draft_brief?.signature_scene_brief
      || syncContextPackage?.pre_draft_brief?.signatureSceneBrief
      || syncContextPackage?.preDraftBrief?.signature_scene_brief
      || syncContextPackage?.preDraftBrief?.signatureSceneBrief
      || chapter?.raw_payload?.signature_scene_brief
      || chapter?.raw_payload?.signatureSceneBrief,
  )
}

function normalizeSignatureSceneSyncBeat(key: string, label: string, text: any, threshold = 58) {
  const normalizedText = compactText(text, 180)
  return normalizedText ? { key, label, text: normalizedText, threshold } : null
}

function signatureSceneSyncBeatMatch(beat: any, chapterText: string) {
  const match = anchorMatchScore(beat.text, chapterText)
  const delivered = match.score >= Number(beat.threshold || 58)
  return {
    ...beat,
    score: match.score,
    evidence: match.matched,
    delivered,
  }
}

export function buildSignatureSceneSyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const signatureSceneBrief = signatureSceneBriefFromContext(contextPackage, chapter)
  const planned = [
    normalizeSignatureSceneSyncBeat('signature_scene', '标志性场面', signatureSceneBrief?.signature_scene, 58),
    normalizeSignatureSceneSyncBeat('scene_repair_target', '补位目标', signatureSceneBrief?.scene_repair_target, 50),
    normalizeSignatureSceneSyncBeat('reader_payoff', '读者回报', signatureSceneBrief?.reader_payoff, 42),
    normalizeSignatureSceneSyncBeat('storyline_service', '剧情线服务', signatureSceneBrief?.storyline_service, 50),
  ].filter(Boolean)

  if (!planned.length) {
    return {
      report_id: `signature-scene-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
      chapter_id: chapter?.id || null,
      chapter_no: chapter?.chapter_no || null,
      score: null,
      status: 'ok',
      label: '强场面未计划',
      summary: '本章没有明确标志性强场面补位任务，不做兑现复盘。',
      planned_count: 0,
      missed_count: 0,
      planned: [],
      delivered: [],
      missed: [],
      next_actions: ['后续如近10章强场面覆盖不足，先在滚动规划和开写任务书中补标志性场面。'],
    }
  }

  const rawChecked = planned.map(item => signatureSceneSyncBeatMatch(item, chapterText))
  const signatureDelivered = rawChecked.some(item => item.key === 'signature_scene' && item.delivered)
  const checked = rawChecked.map(item => {
    if (item.key !== 'scene_repair_target' || item.delivered || !signatureDelivered) return item
    return {
      ...item,
      score: Math.max(Number(item.score || 0), 80),
      evidence: ['标志性场面已落地'],
      delivered: true,
    }
  })
  const delivered = checked.filter(item => item.delivered)
  const missed = checked.filter(item => !item.delivered)
  const missedCount = missed.length
  const score = Math.max(0, Math.min(100, Math.round((delivered.length / planned.length) * 100)))
  const signatureSceneMissed = missed.some(item => item.key === 'signature_scene')
  const status = signatureSceneMissed || missedCount > 0 || score < 78 ? 'warn' : 'ok'

  return {
    report_id: `signature-scene-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: status === 'ok' ? '强场面 OK' : `强场面漏写 ${missedCount}`,
    summary: status === 'ok'
      ? '本章开写任务书里的标志性场面、补位目标、读者回报和剧情线服务已基本落地。'
      : `标志性强场面补位有 ${missedCount} 项未在正文中充分兑现。`,
    planned_count: planned.length,
    missed_count: missedCount,
    planned,
    delivered,
    missed,
    next_actions: status === 'ok'
      ? ['保持强场面补位从滚动规划到正文交稿的兑现闭环。']
      : [
          '下一次修订优先补回开写任务书指定的标志性场面，把它写成可视化动作、空间冲突、规则代价或公开反转。',
          '不要只补气氛描写；必须让 scene_repair_target、reader_payoff 和 storyline_service 在正文事件中可见。',
      ],
  }
}

function storyUnitContextFromContext(contextPackage: any, chapter: any = {}) {
  const target = contextPackage?.chapter_target || contextPackage?.chapterTarget || {}
  return normalizeStoryUnitContext(
    target?.story_unit_context
      || target?.storyUnitContext
      || contextPackage?.story_unit_context
      || contextPackage?.storyUnitContext
      || contextPackage?.pre_draft_brief?.story_unit_context
      || contextPackage?.pre_draft_brief?.storyUnitContext
      || contextPackage?.preDraftBrief?.story_unit_context
      || contextPackage?.preDraftBrief?.storyUnitContext
      || chapter?.raw_payload?.pre_draft_brief?.story_unit_context
      || chapter?.raw_payload?.pre_draft_brief?.storyUnitContext
      || chapter?.raw_payload?.preDraftBrief?.story_unit_context
      || chapter?.raw_payload?.preDraftBrief?.storyUnitContext
      || chapter?.raw_payload?.story_unit_context
      || chapter?.raw_payload?.storyUnitContext,
    Number(chapter?.chapter_no || target?.chapter_no || target?.chapterNo || 0),
  )
}

function normalizeStoryUnitSyncBeat(key: string, label: string, text: any, source = 'story_unit', threshold = 58) {
  const normalizedText = compactText(text, 180)
  return normalizedText ? { key, label, text: normalizedText, source, threshold } : null
}

function storyUnitSyncBeatMatch(beat: any, chapterText: string) {
  const match = anchorMatchScore(beat.text, chapterText)
  const delivered = match.score >= Number(beat.threshold || 58)
  return {
    ...beat,
    score: match.score,
    evidence: match.matched,
    delivered,
  }
}

function storyUnitForbiddenTouched(beat: any, chapterText: string) {
  const match = anchorMatchScore(String(beat.text || '').replace(/^不得|禁止|不可/, ''), chapterText)
  const touched = match.score >= 42
  return {
    ...beat,
    score: match.score,
    evidence: match.matched,
    touched,
  }
}

export function buildStoryUnitSyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const storyUnit = storyUnitContextFromContext(contextPackage, chapter)
  if (!storyUnit) {
    return {
      report_id: `story-unit-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
      chapter_id: chapter?.id || null,
      chapter_no: chapter?.chapter_no || null,
      score: null,
      status: 'ok',
      label: '剧情单元未计划',
      summary: '本章没有明确剧情单元任务，不做单元职责复盘。',
      missed_count: 0,
      rushed_count: 0,
      forbidden_count: 0,
      story_unit: null,
      planned: [],
      delivered: [],
      missed: [],
      rushed_ahead: [],
      forbidden_touched: [],
      next_actions: [],
    }
  }

  const role = compactBriefText(storyUnit.current_chapter_role)
  const roleText = normalizedMatchText(role)
  const roleRequired = [
    /入口|开场|进场/.test(role)
      ? normalizeStoryUnitSyncBeat('entry_hook', '入口钩子', storyUnit.entry_hook || role, 'story_unit', 50)
      : null,
    /高潮|回报|兑现|打脸|结算/.test(role)
      ? normalizeStoryUnitSyncBeat('mini_climax_payoff', '小高潮/回报', storyUnit.mini_climax_payoff || role, 'story_unit', 58)
      : null,
    /出单元|出场|收束|转入|承接下一|下一段/.test(role)
      ? normalizeStoryUnitSyncBeat('exit_hook', '出单元钩子', storyUnit.exit_hook || role, 'story_unit', 58)
      : null,
    /压力|升级|推进|冲突/.test(role)
      ? normalizeStoryUnitSyncBeat('pressure_escalation', '压力升级', asArray(storyUnit.pressure_escalation)[0] || role, 'story_unit', 50)
      : null,
  ].filter(Boolean)
  const fallbackRequired = roleRequired.length
    ? []
    : [
        normalizeStoryUnitSyncBeat('current_chapter_role', '当前职责', role || storyUnit.unit_goal, 'story_unit', 46),
      ].filter(Boolean)
  const setupOptional = asArray(storyUnit.setup_and_storyline)
    .slice(0, 3)
    .map((item: any, index: number) => normalizeStoryUnitSyncBeat(`setup_and_storyline_${index + 1}`, '伏笔/剧情线', item, 'story_unit_setup', 48))
    .filter(Boolean)
  const required = [...roleRequired, ...fallbackRequired]
  const planned = [...required, ...setupOptional]
  const checkedRequired = required.map(item => storyUnitSyncBeatMatch(item, chapterText))
  const checkedOptional = setupOptional.map(item => storyUnitSyncBeatMatch(item, chapterText))
  const delivered = [...checkedRequired, ...checkedOptional].filter(item => item.delivered)
  const missed = checkedRequired.filter(item => !item.delivered)
  const rushCandidates = [
    !/高潮|回报|兑现|打脸|结算/.test(role)
      ? normalizeStoryUnitSyncBeat('mini_climax_payoff', '后段小高潮', storyUnit.mini_climax_payoff, 'story_unit_rush', 58)
      : null,
    !/出单元|收束|转入/.test(role)
      ? normalizeStoryUnitSyncBeat('exit_hook', '出单元钩子', storyUnit.exit_hook, 'story_unit_rush', 58)
      : null,
  ].filter(Boolean)
  const rushedAhead = rushCandidates
    .map(item => storyUnitSyncBeatMatch(item, chapterText))
    .filter(item => item.delivered)
  const forbiddenTouched = asArray(storyUnit.forbidden_advance)
    .slice(0, 6)
    .map((item: any, index: number) => normalizeStoryUnitSyncBeat(`forbidden_advance_${index + 1}`, '禁抢跑', item, 'story_unit_forbidden', 42))
    .filter(Boolean)
    .map(item => storyUnitForbiddenTouched(item, chapterText))
    .filter(item => item.touched)

  const missedCount = missed.length
  const rushedCount = rushedAhead.length
  const forbiddenCount = forbiddenTouched.length
  const status = missedCount || rushedCount || forbiddenCount ? 'warn' : 'ok'
  const score = Math.max(0, Math.min(100, Math.round(100 - missedCount * 24 - rushedCount * 22 - forbiddenCount * 28)))
  const riskParts = [
    missedCount ? `单元漏写 ${missedCount}` : '',
    rushedCount ? `单元抢跑 ${rushedCount}` : '',
    forbiddenCount ? `禁抢跑 ${forbiddenCount}` : '',
  ].filter(Boolean)

  return {
    report_id: `story-unit-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: status === 'ok' ? '剧情单元 OK' : riskParts.join(' · '),
    summary: status === 'ok'
      ? '本章已完成当前剧情单元职责，且未明显提前消费后段小高潮或出单元钩子。'
      : `本章剧情单元职责存在 ${missedCount + rushedCount + forbiddenCount} 项风险。`,
    missed_count: missedCount,
    rushed_count: rushedCount,
    forbidden_count: forbiddenCount,
    story_unit: {
      title: storyUnit.title,
      chapter_range_label: storyUnit.chapter_range_label,
      current_chapter_role: storyUnit.current_chapter_role,
      unit_goal: storyUnit.unit_goal,
    },
    role_key: roleText,
    planned,
    delivered,
    missed,
    rushed_ahead: rushedAhead,
    forbidden_touched: forbiddenTouched,
    next_actions: status === 'ok'
      ? ['保持剧情单元任务书、正文生成和交稿复盘闭环。']
      : [
          '下一次修订优先补足当前剧情单元职责 missed 项，尤其是入口钩子、压力升级或本章回报。',
          '把 rushed_ahead 和 forbidden_touched 中的后段内容改成暗示、误导或延迟兑现，不要在本章提前解决。',
      ],
  }
}

const volumeBeatPattern = /小高潮|中高潮|卷末|高潮|爆点|转折|反转|大回报|强冲突|阶段收束|收束|破局|打脸|揭底|真相|压轴/

function volumeBeatBriefFromContext(contextPackage: any, chapter: any = {}) {
  const syncContextPackage = contextWithChapterRawPreDraftForSync(contextPackage, chapter)
  const target = syncContextPackage?.chapter_target || {}
  const brief = syncContextPackage?.pre_draft_brief || syncContextPackage?.preDraftBrief || {}
  return {
    explicit: target.volume_beat_brief || target.volumeBeatBrief || brief.volume_beat_brief || brief.volumeBeatBrief || {},
    nextBatch: nextBatchBriefFromContext(contextPackage, brief, chapter) || {},
    sceneCards: [
      ...asArray(target.scene_cards || target.sceneCards),
      ...asArray(brief.scene_briefs || brief.sceneBriefs),
    ],
  }
}

function normalizeVolumeBeat(key: string, label: string, value: any, source = 'volume_beat') {
  const text = compactText(value, 180)
  return text ? { key, label, text, source } : null
}

function uniqueVolumeBeats(items: any[]) {
  const seen = new Set<string>()
  const rows: any[] = []
  for (const item of items.filter(Boolean)) {
    const key = normalizedMatchText(item.text)
    if (!key || seen.has(key)) continue
    seen.add(key)
    rows.push(item)
  }
  return rows
}

function volumeBeatMatch(beat: any, chapterText: string) {
  const match = anchorMatchScore(beat.text, chapterText)
  const threshold = beat.key === 'current_chapter_role' ? 44 : 70
  return {
    ...beat,
    score: match.score,
    evidence: match.matched,
    delivered: match.score >= threshold,
  }
}

export function buildVolumeBeatSyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const beatContext = volumeBeatBriefFromContext(contextPackage, chapter)
  const currentRole = firstDefined(
    beatContext.explicit.current_chapter_role,
    beatContext.explicit.currentChapterRole,
    beatContext.explicit.chapter_role,
    beatContext.explicit.chapterRole,
    beatContext.nextBatch.current_chapter_role,
    beatContext.nextBatch.currentChapterRole,
  )
  const explicitBeats = [
    normalizeVolumeBeat('volume_goal', '卷级目标', beatContext.explicit.volume_goal || beatContext.explicit.volumeGoal || beatContext.explicit.goal),
    normalizeVolumeBeat('climax_promise', '高潮承诺', beatContext.explicit.climax_promise || beatContext.explicit.climaxPromise || beatContext.explicit.climax),
    ...asArray(beatContext.explicit.required_beats || beatContext.explicit.requiredBeats).map((item: any, index: number) => normalizeVolumeBeat(`required_beat_${index + 1}`, '爆点动作', item)),
  ].filter(Boolean)
  const hasExplicitVolumeBeat = explicitBeats.length > 0 || volumeBeatPattern.test(currentRole)
  const sceneBeats = beatContext.sceneCards.flatMap((card: any, index: number) => {
    const candidates = [
      normalizeVolumeBeat(`turning_point_${index + 1}`, '转折点', card?.turning_point || card?.turningPoint || card?.turn || card?.reversal, 'scene_card'),
      normalizeVolumeBeat(`reader_payoff_${index + 1}`, '读者回报', card?.reader_payoff || card?.readerPayoff || card?.payoff || card?.reader_reward || card?.readerReward, 'scene_card'),
      normalizeVolumeBeat(`ending_hook_${index + 1}`, '钩子推进', card?.ending_hook_seed || card?.endingHookSeed || card?.ending_hook || card?.endingHook, 'scene_card'),
    ].filter(Boolean)
    return hasExplicitVolumeBeat ? candidates : candidates.filter(item => volumeBeatPattern.test(item.text))
  })
  const planned = uniqueVolumeBeats([
    volumeBeatPattern.test(currentRole) ? normalizeVolumeBeat('current_chapter_role', '本章爆点职责', currentRole) : null,
    ...explicitBeats,
    ...sceneBeats,
  ])
  const checked = planned.map(item => volumeBeatMatch(item, chapterText))
  const delivered = checked.filter(item => item.delivered)
  const missed = checked.filter(item => !item.delivered)
  const missedCount = missed.length
  const score = Math.max(0, Math.min(100, Math.round(
    planned.length ? (delivered.length / planned.length) * 100 : 82,
  )))
  const status = missedCount > 0 || score < 78 ? 'warn' : 'ok'

  return {
    report_id: `volume-beat-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: planned.length === 0 ? '爆点未计划' : status === 'ok' ? '爆点 OK' : `爆点漏兑现 ${missedCount}`,
    summary: planned.length === 0
      ? '本章没有明确卷级高潮或爆点承诺。'
      : status === 'ok'
        ? '本章卷级爆点、转折和读者回报已基本兑现。'
        : `本章有 ${missedCount} 项卷级爆点或小高潮承诺未在正文中充分兑现。`,
    missed_count: missedCount,
    planned,
    delivered,
    missed,
    next_actions: status === 'ok'
      ? ['保持卷级爆点预算、章节任务书和正文兑现闭环。']
      : [
          '下一次修订优先补足卷级爆点 missed 项，把小高潮/中高潮/卷末爆点写成可见行动、反转和回报。',
          '如果正文只铺信息没有兑现转折，优先补现场冲突、选择代价、反制结果和章末升级。',
        ],
  }
}

function millionWordRunwayFromContext(contextPackage: any = {}, preDraftBrief: any = null) {
  const chapterTarget = contextPackage?.chapter_target || {}
  const brief = preDraftBrief || contextPackage?.pre_draft_brief || contextPackage?.preDraftBrief || {}
  return chapterTarget.million_word_runway
    || chapterTarget.millionWordRunway
    || brief.million_word_runway
    || brief.millionWordRunway
    || contextPackage?.million_word_runway
    || contextPackage?.millionWordRunway
    || null
}

function runwayFromContext(contextPackage: any, chapter: any = {}) {
  const syncContextPackage = contextWithChapterRawPreDraftForSync(contextPackage, chapter)
  return millionWordRunwayFromContext(syncContextPackage) || {}
}

function normalizeRunwayQuestion(item: any, index: number) {
  const text = compactText(item?.answer || item?.text || item?.summary || item?.value || '', 180)
  if (!text) return null
  return {
    key: String(item?.key || `question_${index + 1}`),
    label: compactText(item?.label || item?.title || `本章四问 ${index + 1}`, 60),
    text,
  }
}

function normalizeRunwayFuel(item: any, index: number) {
  const text = compactText(typeof item === 'string' ? item : item?.text || item?.name || item?.title || item?.summary || item?.description || '', 180)
  return text ? { key: `reader_fuel_${index + 1}`, text } : null
}

function runwayBeatMatch(beat: any, chapterText: string) {
  const match = anchorMatchScore(beat.text, chapterText)
  return {
    ...beat,
    score: match.score,
    evidence: match.matched,
    delivered: match.score >= 44,
  }
}

function runwayRedlineTouched(redLines: any[], chapterText: string) {
  const normalizedChapterText = normalizedMatchText(chapterText)
  return redLines
    .map((item: any) => ({ text: compactText(typeof item === 'string' ? item : item?.text || item?.name || item?.title || item?.summary || item?.description || '', 180) }))
    .filter((item: any) => item.text && normalizedChapterText.includes(normalizedMatchText(item.text)))
}

export function buildRunwaySyncReport(project: any, chapter: any, contextPackage: any, chapterText: string) {
  const runway = runwayFromContext(contextPackage, chapter)
  const fourQuestions = [
    ...asArray(runway?.fourQuestions),
    ...asArray(runway?.four_questions),
  ]
    .map(normalizeRunwayQuestion)
    .filter(Boolean)
  const readerFuel = [
    ...asArray(runway?.readerFuel),
    ...asArray(runway?.reader_fuel),
  ]
    .map(normalizeRunwayFuel)
    .filter(Boolean)
  const redLines = [
    ...asArray(runway?.redLines),
    ...asArray(runway?.red_lines),
  ]

  const questionChecks = fourQuestions.map(item => runwayBeatMatch(item, chapterText))
  const fuelChecks = readerFuel.map(item => runwayBeatMatch(item, chapterText))
  const fourQuestionDelivered = questionChecks.filter(item => item.delivered)
  const fourQuestionMissed = questionChecks.filter(item => !item.delivered)
  const readerFuelDelivered = fuelChecks.filter(item => item.delivered)
  const readerFuelMissed = fuelChecks.filter(item => !item.delivered)
  const redlineTouched = runwayRedlineTouched(redLines, chapterText)
  const riskCount = fourQuestionMissed.length + readerFuelMissed.length + redlineTouched.length
  const plannedCount = fourQuestions.length + readerFuel.length
  const deliveredCount = fourQuestionDelivered.length + readerFuelDelivered.length
  const score = Math.max(0, Math.min(100, Math.round(
    plannedCount
      ? (deliveredCount / plannedCount) * 100 - redlineTouched.length * 22
      : redlineTouched.length ? 62 - redlineTouched.length * 12 : 82,
  )))
  const status = riskCount > 0 || score < 78 ? 'warn' : 'ok'

  return {
    report_id: `runway-sync-${chapter?.id || chapter?.chapter_no || Date.now()}`,
    chapter_id: chapter?.id || null,
    chapter_no: chapter?.chapter_no || null,
    score,
    status,
    label: status === 'ok' ? '航线 OK' : `航线风险 ${riskCount}`,
    summary: status === 'ok'
      ? '本章已基本兑现百万字航线的本章四问、读者燃料和红线约束。'
      : `百万字航线存在 ${riskCount} 项兑现风险。`,
    risk_count: riskCount,
    four_questions: questionChecks,
    four_question_delivered: fourQuestionDelivered,
    four_question_missed: fourQuestionMissed,
    reader_fuel: fuelChecks,
    reader_fuel_delivered: readerFuelDelivered,
    reader_fuel_missed: readerFuelMissed,
    redline_touched: redlineTouched,
    next_actions: status === 'ok'
      ? ['保持百万字航线：本章四问、读者燃料、禁用红线要继续进入开写任务书和交稿复盘。']
      : [
          '下一次修订优先补足 four_question_missed 和 reader_fuel_missed，避免章节只完成事件但不服务长期追读。',
          '如果 redline_touched 有内容，必须改掉提前揭露、越级回收或破坏长期核心的段落。',
        ],
  }
}

export function normalizeDiscoveredAssets(assets: any[] = [], options: {
  existingCharacters?: any[]
  existingSettings?: any[]
  chapter?: any
} = {}) {
  const existingCharacterNames = new Set((options.existingCharacters || []).map(item => String(item?.name || '').trim()).filter(Boolean))
  const existingSettingKeys = new Set((options.existingSettings || []).map(item => `${item?.entity_type}:${String(item?.name || '').trim()}`).filter(Boolean))
  const seen = new Set<string>()
  const chapterNo = Number(options.chapter?.chapter_no || 0) || null
  const chapterId = Number(options.chapter?.id || 0) || null
  const normalized: any[] = []

  for (const asset of asArray(assets)) {
    const entityType = String(asset?.entity_type || asset?.type || '')
    const name = String(asset?.name || asset?.title || '').trim()
    if (!DISCOVERED_ASSET_TYPES.includes(entityType) || !name) continue
    if (entityType === 'character' && existingCharacterNames.has(name)) continue
    const key = `${entityType}:${name}`
    if (existingSettingKeys.has(key) || seen.has(key)) continue
    seen.add(key)
    const suggestedState = asset?.state_json || asset?.suggested_state || asset?.state || {}
    normalized.push({
      entity_type: entityType,
      name,
      summary: String(asset?.summary || asset?.description || asset?.role || asset?.effect || '').trim(),
      evidence: String(asset?.evidence || asset?.quote || asset?.source_text || '').trim(),
      source_excerpt: String(asset?.source_excerpt || asset?.quote || asset?.evidence || '').trim(),
      first_chapter_no: asset?.first_chapter_no ?? chapterNo,
      constraints_json: asset?.constraints_json || asset?.constraints || {},
      state_json: {
        ...(suggestedState && typeof suggestedState === 'object' && !Array.isArray(suggestedState) ? suggestedState : {}),
        ...(chapterNo ? { first_seen_chapter: chapterNo } : {}),
      },
      payload_json: {
        source: 'story_state_discovered_asset',
        source_chapter_id: chapterId,
        source_chapter_no: chapterNo,
        raw: asset,
      },
    })
  }
  return normalized
}

export function normalizeIpSceneCandidates(candidates: any[] = [], chapter: any = {}) {
  const normalized: any[] = []
  const seen = new Set<string>()
  const chapterNo = Number(chapter?.chapter_no || 0) || null
  const chapterId = Number(chapter?.id || 0) || null

  for (const candidate of asArray(candidates)) {
    const title = String(candidate?.title || candidate?.name || '').trim()
    const summary = String(candidate?.summary || candidate?.description || '').trim()
    if (!title || !summary) continue
    const key = title.toLowerCase()
    if (seen.has(key)) continue
    seen.add(key)

    normalized.push({
      title,
      summary,
      visual_hook: String(candidate?.visual_hook || candidate?.visual || candidate?.image_hook || '').trim(),
      adaptation_value: String(candidate?.adaptation_value || candidate?.ip_value || candidate?.short_drama_value || '').trim(),
      spread_point: String(candidate?.spread_point || candidate?.comment_point || candidate?.discussion_point || '').trim(),
      evidence: String(candidate?.evidence || candidate?.quote || '').trim(),
      source_excerpt: String(candidate?.source_excerpt || candidate?.excerpt || candidate?.evidence || '').trim(),
      tags: asArray(candidate?.tags).map((item: any) => String(item || '').trim()).filter(Boolean).slice(0, 8),
      chapter_id: chapterId,
      chapter_no: chapterNo,
      payload_json: {
        source: 'story_state_ip_scene_intake',
        source_chapter_id: chapterId,
        source_chapter_no: chapterNo,
        raw: candidate,
      },
    })
  }

  return normalized
}

export function normalizeMemeBank(rawBank: any[] = []) {
  const normalized: any[] = []
  const seen = new Set<string>()
  for (const raw of asArray(rawBank)) {
    const memeKey = String(raw?.meme_key || raw?.key || raw?.name || raw?.title || '').trim()
    const functionText = String(raw?.function || raw?.usage_function || raw?.emotion_function || raw?.purpose || '').trim()
    const directPhrases = [
      ...asArray(raw?.unsafe_direct_phrases),
      ...asArray(raw?.direct_phrases),
      raw?.direct_phrase,
      raw?.phrase,
    ].map((item: any) => String(item || '').trim()).filter(Boolean)
    if (!memeKey || (!functionText && directPhrases.length === 0 && !String(raw?.abstract_usage || '').trim())) continue
    const key = memeKey.toLowerCase()
    if (seen.has(key)) continue
    seen.add(key)
    const abstractUsage = String(raw?.abstract_usage || raw?.usage || '').trim()
    normalized.push({
      meme_key: memeKey,
      function: functionText || '情绪共鸣/传播点',
      tone: String(raw?.tone || raw?.voice || '轻度').trim(),
      suitable_genres: asArray(raw?.suitable_genres || raw?.genres).map((item: any) => String(item || '').trim()).filter(Boolean),
      unsafe_direct_phrases: Array.from(new Set(directPhrases)),
      abstract_usage: [
        abstractUsage || `${functionText || memeKey} 只转化为吐槽节奏、角色口吻或情绪功能。`,
        '不直接复刻原句。',
      ].join('').replace(/。+/g, '。'),
      expires_at: String(raw?.expires_at || raw?.expire_at || '').trim(),
      forbidden_scenes: asArray(raw?.forbidden_scenes || raw?.禁用场景).map((item: any) => String(item || '').trim()).filter(Boolean),
      risk_level: String(raw?.risk_level || raw?.过期风险 || 'medium').trim(),
    })
  }
  return normalized
}

export function normalizeStyleSampleBank(rawBank: any[] = []) {
  const normalized: any[] = []
  const seen = new Set<string>()
  for (const raw of asArray(rawBank)) {
    const sampleKey = String(raw?.sample_key || raw?.key || raw?.name || raw?.title || '').trim()
    if (!sampleKey) continue
    const key = sampleKey.toLowerCase()
    if (seen.has(key)) continue
    seen.add(key)

    const sceneFunction = String(raw?.scene_function || raw?.function || raw?.usage_function || raw?.purpose || '').trim()
    const narrativeRhythm = String(raw?.narrative_rhythm || raw?.rhythm || raw?.pacing || '').trim()
    const sentencePattern = String(raw?.sentence_pattern || raw?.sentence_density || raw?.sentence_length || '').trim()
    const dialogueRatio = String(raw?.dialogue_ratio || raw?.dialogue_density || '').trim()
    const voiceRules = asArray(raw?.voice_rules || raw?.character_voice || raw?.voice)
      .map((item: any) => String(item || '').trim())
      .filter(Boolean)
    const applicableScenes = Array.from(new Set(asArray(
      raw?.applicable_scenes || raw?.applicableScenes || raw?.suitable_scenes || raw?.apply_to || raw?.适用场景,
    ).map((item: any) => String(item || '').trim()).filter(Boolean)))
    const avoidScenes = Array.from(new Set([
      ...asArray(raw?.avoid_scenes || raw?.avoidScenes || raw?.unsuitable_scenes || raw?.not_for || raw?.不适用场景),
      ...asArray(raw?.forbidden_scenes || raw?.禁用场景),
    ].map((item: any) => String(item || '').trim()).filter(Boolean)))
    const selectionReason = String(raw?.selection_reason || raw?.selectionReason || raw?.match_reason || raw?.命中理由 || '').trim()
    const abstractUsage = String(raw?.abstract_usage || raw?.usage || '').trim()
    const unsafeDirectPhrases = [
      ...asArray(raw?.unsafe_direct_phrases),
      ...asArray(raw?.unsafeDirectPhrases),
      ...asArray(raw?.forbidden_copy),
      ...asArray(raw?.forbiddenCopy),
      ...asArray(raw?.direct_phrases),
      ...asArray(raw?.directPhrases),
      raw?.direct_phrase,
      raw?.directPhrase,
      raw?.forbidden_phrase,
      raw?.forbiddenPhrase,
    ].map((item: any) => String(item || '').trim()).filter(Boolean)
    const sourceChapterNo = Number(raw?.source_chapter_no ?? raw?.sourceChapterNo ?? 0) || null
    const sourceChapterId = Number(raw?.source_chapter_id ?? raw?.sourceChapterId ?? 0) || null
    const sourceQualityScore = Number(raw?.source_quality_score ?? raw?.sourceQualityScore ?? raw?.quality_score ?? 0)

    normalized.push({
      sample_key: sampleKey,
      scene_function: sceneFunction || '叙述节奏样本',
      narrative_rhythm: narrativeRhythm || '按本章场景压力调整节奏',
      sentence_pattern: sentencePattern || '短中句结合，解释压短',
      dialogue_ratio: dialogueRatio || '按冲突需要控制对白比例',
      voice_rules: voiceRules,
      abstract_usage: [
        abstractUsage || sceneFunction || narrativeRhythm || `${sampleKey} 的表达方法`,
        '；只学习节奏、句式密度、对白比例和情绪转折，不学习具体桥段、设定和原句。',
      ].join('').replace(/；+/g, '；'),
      unsafe_direct_phrases: Array.from(new Set(unsafeDirectPhrases)),
      applicable_scenes: applicableScenes,
      avoid_scenes: avoidScenes,
      ...(selectionReason ? { selection_reason: selectionReason } : {}),
      suitable_genres: asArray(raw?.suitable_genres || raw?.genres).map((item: any) => String(item || '').trim()).filter(Boolean),
      forbidden_scenes: asArray(raw?.forbidden_scenes || raw?.禁用场景).map((item: any) => String(item || '').trim()).filter(Boolean),
      ...(sourceChapterNo ? { source_chapter_no: sourceChapterNo } : {}),
      ...(sourceChapterId ? { source_chapter_id: sourceChapterId } : {}),
      ...(Number.isFinite(sourceQualityScore) && sourceQualityScore > 0 ? { source_quality_score: sourceQualityScore } : {}),
    })
  }
  return normalized
}

export function normalizeChapterBenchmarkSampleBank(rawBank: any[] = []) {
  const normalized: any[] = []
  const seen = new Set<string>()
  for (const raw of asArray(rawBank)) {
    const sampleKey = String(raw?.sample_key || raw?.key || raw?.name || raw?.title || '').trim()
    if (!sampleKey) continue
    const key = sampleKey.toLowerCase()
    if (seen.has(key)) continue
    seen.add(key)

    const openingHook = String(raw?.opening_hook || raw?.openingHook || raw?.hook || '').trim()
    const conflictPattern = String(raw?.conflict_pattern || raw?.conflictPattern || raw?.conflict || '').trim()
    const payoffPattern = String(raw?.payoff_pattern || raw?.payoffPattern || raw?.payoff || '').trim()
    const endingHookPattern = String(raw?.ending_hook_pattern || raw?.endingHookPattern || raw?.ending_hook || '').trim()
    const sceneBudgetPattern = String(raw?.scene_budget_pattern || raw?.sceneBudgetPattern || raw?.scene_budget || raw?.structure || '').trim()
    const dialoguePattern = String(raw?.dialogue_pattern || raw?.dialoguePattern || raw?.dialogue || '').trim()
    const visualPattern = String(raw?.visual_pattern || raw?.visualPattern || raw?.visual_scene || '').trim()
    const abstractUsage = String(raw?.abstract_usage || raw?.usage || '').trim()
    const doNotCopy = [
      ...asArray(raw?.do_not_copy),
      ...asArray(raw?.doNotCopy),
      ...asArray(raw?.forbidden_copy),
      ...asArray(raw?.forbiddenCopy),
      ...asArray(raw?.unsafe_direct_phrases),
      ...asArray(raw?.unsafeDirectPhrases),
      raw?.source_excerpt,
      raw?.sample_text,
      raw?.direct_phrase,
      raw?.directPhrase,
    ].map((item: any) => String(item || '').trim()).filter(Boolean)

    normalized.push({
      sample_key: sampleKey,
      genre: String(raw?.genre || raw?.type || '').trim(),
      quality_axes: Array.from(new Set([
        ...asArray(raw?.quality_axes || raw?.axes),
        openingHook ? '开篇钩子' : '',
        conflictPattern ? '冲突推进' : '',
        payoffPattern ? '爽点兑现' : '',
        endingHookPattern ? '章末追读' : '',
        sceneBudgetPattern ? '场景节拍' : '',
        dialoguePattern ? '对白节奏' : '',
        visualPattern ? '场面可视化' : '',
      ].map((item: any) => String(item || '').trim()).filter(Boolean))),
      opening_hook: openingHook || '开篇 300 字内给出异常、危险、欲望或反常信息',
      conflict_pattern: conflictPattern || '每个场景都有目标、阻碍、转折和可见代价',
      payoff_pattern: payoffPattern || '把爽点写成行动结果、信息增量或情绪回报',
      ending_hook_pattern: endingHookPattern || '章末保留一个读者必须继续看的未解问题',
      scene_budget_pattern: sceneBudgetPattern || '按开局钩子、冲突升级、回报反转、章末钩子分配篇幅',
      dialogue_pattern: dialoguePattern || '对白必须推动冲突、试探信息或暴露关系变化',
      visual_pattern: visualPattern || '关键场面要有空间、动作、道具或规则反馈，便于短剧/漫剧转化',
      abstract_usage: [
        abstractUsage || '对照样例的章节结构、冲突节拍、爽点密度和章末追读设计。',
        '只学习章节结构、信息密度、冲突节拍、爽点兑现和章末钩子，不学习具体桥段、设定和原句。',
      ].join('').replace(/。+/g, '。'),
      do_not_copy: Array.from(new Set([
        ...doNotCopy,
        '不得复制样例桥段、角色名、专有设定和原句',
        '不得把样例剧情替换成本章剧情',
      ])),
    })
  }
  return normalized
}

